# ---- v14: the relay's newer routes, the outbox, restarts --------------------
SEND_MANY_MAX = 32          # members per group request (relay 12.2's limit)
OUTBOX_EVERY = 30.0         # seconds between outbox passes while connected
OUTBOX_DAY = 24 * 3600      # after this, an unsent message waits for a tap
RESTART_WAIT_MAX = 300      # the longest "come back in" a relay is obeyed for

# ---- v9 media ---------------------------------------------------------------
# Photos and voice notes are sealed with a fresh per-file AES-256-GCM key,
# uploaded to the relay as an opaque blob, and referenced from a normal
# end-to-end message that carries the key. The relay keeps blobs only for a
# while; past that the recipient asks the sender to upload again, and the
# sender's device — which still holds the file — does it (see the 'resend'
# control). Long-term storage is the phones', never the relay's.
MEDIA_DIR = DATA_DIR / "media"
MAX_MEDIA_BYTES = 8 * 1024 * 1024    # hard cap for one sealed blob
IMAGE_MAX_EDGE = 1280                # photos are resized to fit this box…
IMAGE_JPEG_QUALITY = 60              # …and re-encoded: ~100-200 KB typical
THUMB_EDGE = 40                      # inline preview, travels in the message
THUMB_QUALITY = 40
# v12: a picture from elsewhere (a photo someone sent, a page's picture for
# a preview) is measured before it is decoded, and refused past these.
FOREIGN_MAX_EDGE = 8192
FOREIGN_MAX_PIXELS = 4096 * 4096
RECEIVED_KEEP_EDGE = 2 * IMAGE_MAX_EDGE  # bigger than any we send: redrawn
VOICE_SAMPLE_RATE = 16000            # wideband speech
VOICE_BITRATE = 24000                # AAC-LC: ~3 KB per second of speech
MAX_VOICE_SECONDS = 300
MEDIA_MIME = {"image": ("image/jpeg", "image/png", "image/webp"),
              "voice": ("audio/mp4", "audio/aac", "audio/ogg",
                        "audio/3gpp", "audio/amr", "audio/wav")}

# ---- v9.1.2 pictures ----------------------------------------------------------
# A profile picture is small enough to travel inside one ordinary end-to-end
# message (a 'pic' control), so it needs no relay storage and never expires:
# it goes to the people you write to, and again only when it changes. A
# group's picture is the admin's to set ('gpic'). Every v9.1.2 message says
# which version of its author's picture is current, so a device that missed
# one — reinstalled, restored from a key — asks for it ('picreq').
PICTURES_DIR = DATA_DIR / "pictures"
PICTURE_EDGE = 320                  # pictures are square, this many pixels…
PICTURE_MAX_BYTES = 30 * 1024       # …and at most this big as a JPEG
PICTURE_ACCEPT_BYTES = 48 * 1024    # the most we take from someone else
PICTURE_SOURCE_EDGE = 1600          # a photo is cropped from at most this
#: x.ft: what the sender's app can do, so nobody is sent what it would
#: ignore. Bits only ever get added.
FEATURE_PICTURES = 1
FEATURE_CALLS = 2
FEATURE_TIMER = 4                   # v11: honours disappearing messages
FEATURES = FEATURE_PICTURES | FEATURE_CALLS | FEATURE_TIMER

