class ChatHistorySheet(Sheet):
    """Plaintext export (.json / .txt) and import (.json) of one chat."""

    def __init__(self, app: "FextApp", peer: str) -> None:
        name, _kind = conversation_title(app, peer)
        super().__init__("Chat history", subtitle=f"{name} — plaintext copies "
                                                  f"that stay on this device")
        self.app, self.peer, self.name = app, peer, name
        self.add(button_row(Btn("Export .json", kind="quiet",
                                on_release=lambda _w: self._export("json")),
                            Btn("Export .txt", kind="quiet",
                                on_release=lambda _w: self._export("txt"))))
        self.add(Btn("Import .json", kind="quiet",
                     on_release=lambda _w: self._import()))
        self.io_status = self.status_label()
        self.add(Btn("Done", kind="text",
                     on_release=lambda _w: self.dismiss()))

    def _author(self, m: dict) -> str:
        if m["direction"] == "out":
            return self.app.keys.username or "Me"
        if m.get("kind") == "event":
            return "·"
        return self.app.conversation_screen.author_name(
            m.get("author") or m["peer"])

    def _export(self, fmt: str) -> None:
        EXPORT_DIR.mkdir(parents=True, exist_ok=True)
        stamp = datetime.now().strftime("%Y%m%d_%H%M%S")
        safe = re.sub(r"[^A-Za-z0-9_-]+", "_", self.name)[:40] or "chat"
        path = EXPORT_DIR / f"fext_chat_{safe}_{stamp}.{fmt}"
        messages = self.app.store.messages_for(self.peer)
        contact = self.app.store.get_contact(self.peer) or {}
        try:
            if fmt == "json":
                path.write_text(json.dumps({
                    "fext_chat_export": 2,
                    "identity": self.app.keys.address,
                    "peer": {"address": self.peer,
                             "username": contact.get("username") or
                             self.name},
                    "exported_at": now_iso(),
                    "messages": [dict({"direction": m["direction"],
                                       "body": m["body"],
                                       "created_at": m["created_at"],
                                       "status": m["status"],
                                       "read": m["read"]},
                                      **({"author": m["author"]}
                                         if m.get("author") else {}))
                                 for m in messages
                                 if m.get("kind") != "event"],
                }, indent=2, ensure_ascii=False), "utf-8")
            else:
                lines = [f"{APP_NAME} — {self.name} ({self.peer})",
                         f"Exported {now_iso()}", ""]
                for m in messages:
                    lines.append(f"[{m['created_at']}] {self._author(m)}: "
                                 f"{m['body']}")
                path.write_text("\n".join(lines) + "\n", "utf-8")
            opened = open_folder_in_explorer(EXPORT_DIR)
            note = f"Exported {len(messages)} messages to {path}"
            if opened:
                note += " (the folder is open)"
            self.set_status(self.io_status, note)
        except OSError as exc:
            self.set_status(self.io_status, f"Export failed: {exc}", T.alert)

    def _import(self) -> None:
        ImportChooserModal(self._import_file).open()

    def _import_file(self, path: str) -> None:
        try:
            data = json.loads(Path(path).read_text("utf-8"))
            if data.get("fext_chat_export") != 2 or \
                    not isinstance(data.get("messages"), list):
                raise ValueError(f"not a {APP_NAME} chat export")
            added = 0
            for m in data["messages"]:
                if not isinstance(m, dict):
                    continue
                ok = self.app.store.import_message(
                    peer=self.peer,
                    direction=str(m.get("direction", "")),
                    body=sanitize_text(str(m.get("body", ""))),
                    created_at=str(m.get("created_at", now_iso()))[:64],
                    status=int(m.get("status", 1) or 0) if
                    str(m.get("status", 1)).lstrip("-").isdigit() else 1,
                    read=1)
                added += 1 if ok else 0
            self.set_status(self.io_status, (
                f"Imported {added} new messages "
                f"({len(data['messages']) - added} already here)"))
            self.app.conversation_screen._rendered_peer = None
            self.app.refresh_chat(self.peer)
            self.app.refresh_sidebar()
        except (OSError, ValueError, json.JSONDecodeError) as exc:
            self.set_status(self.io_status, f"Import failed: {exc}", T.alert)


ContactSettingsModal = ChatHistorySheet     # pre-9.1 name


class RemoveIdentityModal(Sheet):
    """Confirm removing an identity from this device.

    The private key IS the identity: once it is gone, the address, its
    history and any coins on it cannot be recovered. So the key export is
    offered BEFORE the destructive button. Releasing the name on the relay
    is a separate choice — another device may still use the same key.
    """

    def __init__(self, app: "FextApp", address: str) -> None:
        ident = app.keys.find(address) or {}
        label = ident.get("label") or short_addr(address, 12)
        super().__init__(f"Remove “{label}”?")
        self.app = app
        self.address = address
        self.username = ident.get("username")
        self._release = bool(self.username)
        self.add(hint(
            "This deletes its private key and its chats from this device. "
            "The key cannot be recovered afterwards — if you might want "
            "this identity back, copy the key first."))
        self.add(InfoLabel(address, color=T.accent, font_size=fs(14)))
        self.add(Btn("Copy the private key first", kind="danger",
                     on_release=lambda _w: self._copy_key()))
        if self.username:
            self.release_switch = ToggleSwitch(
                True, lambda on: setattr(self, "_release", on))
            self.add(ListRow(None, f"Release “{self.username}” on the relay",
                             "Frees the name and removes you from the "
                             "directory. Leave it if another device still "
                             "uses this key.", control=self.release_switch,
                             on_tap=self.release_switch.flip,
                             padding=[0, dp(8), 0, dp(8)]))
        self.status = self.status_label()
        self.confirm = Btn("Remove identity", kind="solid_danger",
                           on_release=lambda _w: self._confirm())
        self.add(button_row(Btn("Cancel", kind="quiet",
                                on_release=lambda _w: self.dismiss()),
                            self.confirm))

    def _copy_key(self) -> None:
        """private_export() reads the ACTIVE identity, so switch, read and
        switch back — in a finally."""
        active = self.app.keys.address
        try:
            self.app.keys.activate(self.address)
            data = json.loads(self.app.keys.private_export())
            Clipboard.copy(data["private_key_wif"])
            self.set_status(self.status, "The private key is on the "
                            "clipboard — paste it somewhere safe now.",
                            T.accent)
        except Exception as exc:
            self.set_status(self.status, f"Could not export the key: {exc}",
                            T.alert)
        finally:
            try:
                self.app.keys.activate(active)
            except Exception:
                pass

    def _confirm(self) -> None:
        self.confirm.disabled = True
        self.set_status(self.status, "Removing…")
        threading.Thread(target=self._worker, daemon=True).start()

    def _worker(self) -> None:
        note = ""
        if self._release and self.username:
            previous = self.app.keys.address
            try:
                self.app.keys.activate(self.address)
                ApiClient(self.app.keys).deregister()
            except (requests.RequestException, ApiClient.ApiError):
                note = (" (the relay could not be reached, so the name is "
                        "still registered)")
            finally:
                try:
                    self.app.keys.activate(previous)
                except Exception:
                    pass
        run_on_ui(self._finish, note)

    def _finish(self, note: str) -> None:
        self.dismiss()
        self.app.on_identity_removed(self.address, note)


class IdentitySheet(Sheet):
    """Tap your disc on the chat list: who you are now, every identity on
    this device (switch, rename, remove), a new one, and settings."""

    def __init__(self, app: "FextApp") -> None:
        super().__init__("Identities")
        self.app = app
        keys = app.keys
        self.card.padding = [0, dp(8), 0, dp(16)]
        self.title_label.padding = [dp(22), 0]
        rows = []
        for ident in keys.identities:
            rows.append(self._row(ident, ident["address"] == keys.address))
        self.add(rows_card(rows, inset=dp(76)))
        self.add(Rule())
        self.add(rows_card([
            ListRow("plus", "New identity", "Mine a fresh key or import one",
                    on_tap=self._new),
            ListRow("sliders", "Settings", "Appearance, notifications, keys",
                    on_tap=self._settings)]))

    def _row(self, ident: dict, active: bool) -> BoxLayout:
        address = ident["address"]
        line = BoxLayout(size_hint_y=None, height=max(dp(68), line_height(17)
                                                      + line_height(14) +
                                                      dp(22)),
                         padding=[dp(20), 0, dp(8), 0], spacing=dp(4))
        row = TappableBox(orientation="horizontal", spacing=dp(14),
                          on_tap=lambda a=address: self._switch(a))
        row.add_widget(Avatar(address, ident.get("username") or
                              ident.get("label") or "?", diameter=dp(42),
                              pos_hint={"center_y": .5}))
        texts = BoxLayout(orientation="vertical", padding=[0, dp(12)])
        name = single_line(ident.get("label") or "?", fs(17), T.text,
                           bold=active)
        texts.add_widget(name)
        texts.add_widget(single_line(
            f"@{ident.get('username') or 'unregistered'} · "
            f"{short_addr(address, 10)}", fs(14), T.text_3))
        row.add_widget(texts)
        if active:
            mark = CapsLabel("Active", size=10.5, color=T.accent,
                             size_hint=(None, None), halign="right",
                             pos_hint={"center_y": .5})
            mark.width = mark.natural_width
            row.add_widget(mark)
        line.add_widget(row)
        line.add_widget(IconButton("edit", label="Rename identity",
                                   pos_hint={"center_y": .5},
                                   on_release=lambda _w: self._rename(
                                       address)))
        line.add_widget(IconButton("delete", tint=T.alert,
                                   label="Remove identity",
                                   pos_hint={"center_y": .5},
                                   on_release=lambda _w: self._remove(
                                       address)))
        return line

    def _switch(self, address: str) -> None:
        self.dismiss()
        if address != self.app.keys.address:
            self.app._activate_identity(address)

    def _remove(self, address: str) -> None:
        self.dismiss()
        RemoveIdentityModal(self.app, address).open()

    def _rename(self, address: str) -> None:
        self.dismiss()
        RenameIdentityModal(self.app, address).open()

    def _new(self) -> None:
        self.dismiss()
        NewIdentityModal(self.app).open()

    def _settings(self) -> None:
        self.dismiss()
        self.app.open_settings()


ProfileMenuModal = IdentitySheet            # pre-9.1 name


# =============================================================================
#  The menu — a drawer from the left over the page, blurred (v9.1.2)
# =============================================================================
_BLUR_FS = """
$HEADER$
uniform vec2 step_dir;
void main(void) {
    /* a 9-tap Gaussian folded into five bilinear fetches */
    vec4 c = texture2D(texture0, tex_coord0) * 0.2270270270;
    c += texture2D(texture0, tex_coord0 + step_dir * 1.3846153846) * 0.3162162162;
    c += texture2D(texture0, tex_coord0 - step_dir * 1.3846153846) * 0.3162162162;
    c += texture2D(texture0, tex_coord0 + step_dir * 3.2307692308) * 0.0702702703;
    c += texture2D(texture0, tex_coord0 - step_dir * 3.2307692308) * 0.0702702703;
    gl_FragColor = c;
}
"""


def blurred_snapshot(widget, scale: float = 0.2, passes: int = 3):
    """The widget as drawn now, shrunk and blurred, for the menu's backdrop:
    (texture, the framebuffers that own it) — or None where the GPU cannot
    do it (the caller then dims the page plainly). Drawn once, when the
    menu opens, at a fifth of the size: the blur costs next to nothing."""
    w, h = max(8, int(widget.width * scale)), max(8, int(widget.height * scale))
    parent = widget.parent
    index = parent.canvas.indexof(widget.canvas) if parent is not None else -1
    keep = []
    try:
        # A canvas has one parent: lend it to the framebuffer and put it
        # back exactly where it was (what Widget.export_as_image does).
        if index > -1:
            parent.canvas.remove(widget.canvas)
        try:
            shot = Fbo(size=(w, h), with_stencilbuffer=True, noadd=True)
            with shot:
                ClearColor(*C(T.bg))
                ClearBuffers()
                Scale(scale, scale, 1)
                Translate(-widget.x, -widget.y, 0)
            shot.add(widget.canvas)
            shot.draw()
            shot.remove(widget.canvas)
        finally:
            if index > -1:
                parent.canvas.insert(index, widget.canvas)
        keep.append(shot)
        tex = shot.texture
        for _ in range(passes):
            for direction in ((1.6 / w, 0.0), (0.0, 1.6 / h)):
                f = Fbo(size=(w, h), fs=_BLUR_FS, noadd=True)
                if not f.shader.success:
                    raise RuntimeError("the blur shader did not compile")
                f["step_dir"] = direction
                with f:
                    ClearColor(0, 0, 0, 0)
                    ClearBuffers()
                    Color(1, 1, 1, 1)
                    Rectangle(texture=tex, size=(w, h))
                f.draw()
                keep.append(f)
                tex = f.texture
        return tex, keep
    except Exception as exc:
        log.info("blurred backdrop unavailable (%s); dimming instead", exc)
        return None


class DrawerRow(ButtonBehavior, BoxLayout):
    """One line of the menu: a glyph and a word or two."""

    def __init__(self, icon: str, title: str, on_tap: Callable, **kw):
        kw.setdefault("size_hint_y", None)
        kw.setdefault("height", max(dp(52), line_height(17) + dp(20)))
        kw.setdefault("padding", [dp(22), 0, dp(16), 0])
        kw.setdefault("spacing", dp(22))
        super().__init__(**kw)
        glyph = Widget(size_hint_x=None, width=dp(24))
        glyph.bind(pos=lambda w, *_a: ListRow._glyph(w, icon, T.text_2),
                   size=lambda w, *_a: ListRow._glyph(w, icon, T.text_2))
        self.add_widget(glyph)
        self.title = single_line(title, fs(17), T.text)
        self.add_widget(self.title)
        with self.canvas.before:
            self._bg = Color(0, 0, 0, 0)
            self._rect = Rectangle()
        self.bind(pos=self._sync, size=self._sync,
                  state=lambda _w, st: setattr(
                      self._bg, "rgba", C(T.press) if st == "down"
                      else (0, 0, 0, 0)))
        self.bind(on_release=lambda _w: on_tap())

    def _sync(self, *_a):
        self._rect.pos, self._rect.size = self.pos, self.size


class NavDrawer(FloatLayout):
    """The menu. It comes in from the left over 80% of the screen, and the
    page behind it fades back, blurred: a tinted copy of what was
    showing. Your identity heads it, with the others to switch
    to and a new one; then your profile, a new group and saved messages;
    then settings and about. Tap outside it, or press back, to close it."""

    progress = NumericProperty(0.0)
    WIDTH_SHARE, MAX_WIDTH = 0.8, dp(400)

    def __init__(self, app: "FextApp", **kw):
        kw.setdefault("size_hint", (1, 1))
        super().__init__(**kw)
        self.app = app
        self.is_open = False
        self._frost = None
        self._show_identities = True
        with self.canvas.before:
            self._glass_col = Color(1, 1, 1, 0)
            self._glass = Rectangle()
            self._tint_col = Color(0, 0, 0, 0)
            self._tint = Rectangle()
        self.theme = T.name
        self.panel = BoxLayout(orientation="vertical", size_hint=(None, None))
        paint_round(self.panel, T.surface if T.dark else T.bg, radius=0)
        with self.panel.canvas.after:
            self._edge_col = Color(*C(T.rule))
            self._edge = Rectangle()
        self.scroll = ScrollView(bar_width=dp(2), do_scroll_x=False)
        self.column = BoxLayout(orientation="vertical", size_hint_y=None,
                                padding=[0, 0, 0, dp(24)])
        self.column.bind(minimum_height=self.column.setter("height"))
        self.scroll.add_widget(self.column)
        self.panel.add_widget(self.scroll)
        self.add_widget(self.panel)
        self.bind(pos=self._layout, size=self._layout,
                  progress=self._layout)

    # ---- geometry ------------------------------------------------------------
    def panel_width(self) -> float:
        return min(self.width * self.WIDTH_SHARE, self.MAX_WIDTH)

    def _layout(self, *_a):
        pw, p = self.panel_width(), self.progress
        self.panel.size = (pw, self.height)
        self.panel.pos = (self.x - pw * (1 - p), self.y)
        self._edge.pos = (self.panel.right - 1, self.panel.y)
        self._edge.size = (1, self.panel.height)
        self._glass.pos, self._glass.size = self.pos, self.size
        self._tint.pos, self._tint.size = self.pos, self.size
        self._glass_col.a = p if self._frost is not None else 0
        # the page fades back: blurred where the GPU allows, dimmed always
        self._tint_col.rgba = list(T.scrim[:3]) + [
            p * (0.42 if self._frost is not None else 0.6)]

    # ---- opening and closing -------------------------------------------------
    def open(self, drag: bool = False) -> None:
        """Slide in; `drag`: stay shut, for a finger to bring in (v11)."""
        if self.is_open:
            return
        self.is_open = True
        self.app.conversation_screen.cancel_backfill()
        frost = blurred_snapshot(self.app.manager)
        self._frost = frost
        self._glass.texture = frost[0] if frost else None
        self.rebuild()
        self.scroll.scroll_y = 1
        if self.parent is None:
            self.app.layers.add_widget(self)
        Animation.cancel_all(self, "progress")
        if drag:
            self.progress = 0.0
        elif motion(1):
            Animation(progress=1.0, d=LAYER_IN + 0.04,
                      t="out_cubic").start(self)
        else:
            self.progress = 1.0

    def settle_open(self) -> None:
        """Let go past half way: the rest of the way in."""
        Animation.cancel_all(self, "progress")
        if motion(1):
            Animation(progress=1.0, d=0.12, t="out_cubic").start(self)
        else:
            self.progress = 1.0

    def close(self, then: Optional[Callable] = None) -> None:
        """Slide away; `then` runs at once, so the next page is already
        moving in underneath as the menu goes."""
        if not self.is_open:
            if then is not None:
                then()
            return
        self.is_open = False
        Animation.cancel_all(self, "progress")

        def gone(*_a):
            if self.parent is not None:
                self.parent.remove_widget(self)
            self._glass.texture = None
            self._frost = None
        if motion(1):
            anim = Animation(progress=0.0, d=LAYER_OUT, t="in_quad")
            anim.bind(on_complete=gone)
            anim.start(self)
        else:
            self.progress = 0.0
            gone()
        if then is not None:
            then()

    def on_touch_down(self, touch):
        if not self.is_open:
            return False
        if self.panel.collide_point(*touch.pos):
            super().on_touch_down(touch)
            return True
        self.close()                     # a tap on the page behind
        return True

    def on_touch_move(self, touch):
        if self.is_open:
            super().on_touch_move(touch)
        return self.is_open

    def on_touch_up(self, touch):
        if self.is_open:
            super().on_touch_up(touch)
        return self.is_open

    # ---- contents ------------------------------------------------------------
    def rebuild(self) -> None:
        col, app = self.column, self.app
        col.clear_widgets()
        keys = app.keys
        col.add_widget(self._header())
        if keys.has_identity and self._show_identities:
            for ident in sorted(keys.identities,
                                key=lambda i: i["address"] != keys.address):
                col.add_widget(self._identity_row(ident))
        col.add_widget(DrawerRow("person_add", "New identity",
                                 lambda: self.close(lambda: NewIdentityModal(
                                     app).open())))
        col.add_widget(Rule())
        if keys.has_identity:
            col.add_widget(DrawerRow("person", "My profile",
                                     lambda: self.close(app.open_profile)))
            col.add_widget(DrawerRow("group", "New group",
                                     lambda: self.close(app.open_new_group)))
            col.add_widget(DrawerRow(
                "bookmark", "Saved messages",
                lambda: self.close(lambda: app.open_conversation(
                    keys.address))))
            col.add_widget(Rule())
        col.add_widget(DrawerRow("sliders", "Settings",
                                 lambda: self.close(app.open_settings)))
        col.add_widget(DrawerRow("info", "About",
                                 lambda: self.close(lambda: AboutSheet(
                                     app).open())))

    def _header(self) -> Widget:
        keys, app = self.app.keys, self.app
        head = BoxLayout(orientation="vertical", size_hint_y=None,
                         padding=[dp(20), dp(26), dp(8), dp(14)],
                         spacing=dp(10))
        head.bind(minimum_height=head.setter("height"))
        if not keys.has_identity:
            head.add_widget(single_line(APP_NAME, fs(24), T.text,
                                        size_hint_y=None,
                                        height=line_height(24)))
            return head
        name = keys.label or keys.username or "?"
        top = BoxLayout(size_hint_y=None, height=dp(72))
        disc = AvatarButton(keys.address, keys.username or keys.label,
                            diameter=dp(64), size=(dp(72), dp(72)))
        disc.bind(on_release=lambda _w: self.close(app.open_profile))
        top.add_widget(disc)
        top.add_widget(Widget())
        head.add_widget(top)
        line = BoxLayout(size_hint_y=None, height=max(TOUCH, line_height(19)
                                                      + line_height(14)))
        texts = TappableBox(orientation="vertical",
                            on_tap=lambda: self.close(app.open_profile))
        texts.add_widget(single_line(name, fs(19), T.text, bold=True))
        texts.add_widget(single_line(
            f"@{keys.username or 'unregistered'}  ·  "
            f"{short_addr(keys.address, 10)}", fs(14), T.text_3,
            italic=True))
        line.add_widget(texts)
        line.add_widget(IconButton(
            "chevron_up" if self._show_identities else "chevron_down",
            label="Hide identities" if self._show_identities
            else "Show identities", pos_hint={"center_y": .5},
            on_release=lambda _w: self._toggle_identities()))
        head.add_widget(line)
        return head

    def _toggle_identities(self) -> None:
        self._show_identities = not self._show_identities
        self.rebuild()

    def _identity_row(self, ident: dict) -> Widget:
        keys = self.app.keys
        address = ident["address"]
        active = address == keys.address
        row = TappableBox(orientation="horizontal", size_hint_y=None,
                          height=max(dp(56), line_height(16) + dp(22)),
                          padding=[dp(18), 0, dp(18), 0], spacing=dp(16),
                          on_tap=lambda: self._switch(address))
        row.add_widget(Avatar(address, ident.get("username") or
                              ident.get("label") or "?", diameter=dp(32),
                              pos_hint={"center_y": .5}))
        texts = BoxLayout(orientation="vertical", padding=[0, dp(9)])
        texts.add_widget(single_line(ident.get("label") or "?", fs(16),
                                     T.text, bold=active))
        texts.add_widget(single_line(
            f"@{ident.get('username') or 'unregistered'}", fs(13.5),
            T.text_3))
        row.add_widget(texts)
        if active:
            tick = Widget(size_hint_x=None, width=dp(24))
            tick.bind(pos=lambda w, *_a: ListRow._glyph(w, "check", T.accent),
                      size=lambda w, *_a: ListRow._glyph(w, "check",
                                                         T.accent))
            row.add_widget(tick)
        return row

    def _switch(self, address: str) -> None:
        if address == self.app.keys.address:
            self.close()
            return
        self.close(lambda: self.app._activate_identity(address))


