def caps_tag(text: str, color: Optional[str] = None) -> CapsLabel:
    """A small capitals tag sized to its text (ADMIN, YOU, ACTIVE)."""
    tag = CapsLabel(text, size=10.5, color=color or T.accent,
                    size_hint=(None, None), halign="right")
    tag.width = tag.natural_width + dp(2)
    return tag


class ConversationRow(ButtonBehavior, BoxLayout):
    """One chat in the list: disc, name over a one-line preview, the time
    and the unread count on the right, a hairline that starts where the
    text does. Groups show who spoke last; your own last message shows its
    ticks."""

    LONG_PRESS = 0.42                     # seconds, as BubbleRow

    def __init__(self, conv: dict, on_open: Callable[[str], None],
                 author_name: Optional[Callable] = None, screen=None, **kw):
        kw.setdefault("size_hint_y", None)
        kw.setdefault("height", max(dp(76), line_height(18) +
                                    line_height(15.5) + dp(26)))
        kw.setdefault("padding", [dp(18), dp(10), dp(18), dp(10)])
        kw.setdefault("spacing", dp(14))
        super().__init__(**kw)
        peer, kind = conv["peer"], conv.get("kind", "dm")
        self.peer, self.kind, self.conv = peer, kind, conv
        self._screen, self._press, self._held = screen, None, False
        if kind == "self":
            name = "Saved messages"
        elif kind == "group":
            name = conv.get("group_name") or "Group"
        else:
            name = conv.get("username") or short_addr(peer, 14)
        unread = int(conv.get("unread") or 0)
        muted = kind != "self" and bool(conv.get("muted"))
        with self.canvas.before:
            self._wash_col = Color(*T.select)
            self._wash_col.a = 0
            self._wash = Rectangle()
            self._bg = Color(0, 0, 0, 0)
            self._rect = Rectangle()
        hairline(self, "bottom", inset=dp(18) + dp(52) + dp(14))
        self.bind(pos=self._sync, size=self._sync,
                  state=lambda _w, st: setattr(
                      self._bg, "rgba", C(T.press) if st == "down"
                      else (0, 0, 0, 0)))
        self.bind(on_release=lambda _w: self._released(on_open))

        self.avatar = Avatar(peer, name, diameter=dp(52), kind=kind,
                             pos_hint={"center_y": .5})
        self.add_widget(self.avatar)
        middle = BoxLayout(orientation="vertical", padding=[0, dp(2)])
        top = BoxLayout(spacing=dp(6))
        top.add_widget(single_line(name, fs(18), T.text, bold=True))
        for flag, glyph in ((conv.get("blocked"), "block"), (muted, "bell_off"),
                            (conv.get("pinned"), "pin")):
            if flag:
                mark = Widget(size_hint_x=None, width=dp(18))
                mark.bind(pos=lambda w, *_a, g=glyph: self._mark(w, g),
                          size=lambda w, *_a, g=glyph: self._mark(w, g))
                top.add_widget(mark)
        when = Label(text=pretty_day(conv.get("last_at") or "")
                     if conv.get("preview") is not None else "",
                     font_size=fs(13.5),
                     color=C(T.accent if unread and not muted else T.text_3),
                     size_hint_x=None, halign="right", valign="middle")
        when.bind(texture_size=lambda w, v: setattr(w, "width", v[0]),
                  size=lambda w, v: setattr(w, "text_size", (None, v[1])))
        when.texture_update()
        top.add_widget(when)
        middle.add_widget(top)

        bottom = BoxLayout(spacing=dp(6))
        preview, italic = self._preview(conv, kind, author_name)
        draft = " ".join(str(conv.get("draft") or "").split())
        if draft:
            mark = Label(text="Draft:", font_size=fs(15.5), color=C(T.alert),
                         size_hint_x=None, halign="left", valign="middle")
            mark.texture_update()
            mark.width = mark.texture_size[0] + dp(2)
            bottom.add_widget(mark)
            preview, italic = draft, False
        elif conv.get("last_direction") == "out" and \
                conv.get("last_kind") != "event" and kind != "self":
            status = int(conv.get("last_status") or 0)
            if not conv.get("ticks_enabled", 1) and kind == "dm":
                status = min(status, 1)
            count, tint, clock = tick_look(status)
            ticks = TickMarks(count=count, tint=tint, clock=clock,
                              pos_hint={"center_y": .5})
            bottom.add_widget(ticks)
        text = single_line(preview, fs(15.5), T.text_2 if unread else T.text_3,
                           italic=italic)
        bottom.add_widget(text)
        if unread:
            holder = AnchorLayout(size_hint_x=None, width=dp(44),
                                  anchor_x="right")
            holder.add_widget(UnreadBadge(min(unread, 9999), muted=muted))
            bottom.add_widget(holder)
        elif conv.get("marked_unread"):           # marked unread by hand
            holder = AnchorLayout(size_hint_x=None, width=dp(44),
                                  anchor_x="right")
            holder.add_widget(UnreadBadge(0, muted=muted, dot=True))
            bottom.add_widget(holder)
        middle.add_widget(bottom)
        self.add_widget(middle)

    @staticmethod
    def _preview(conv: dict, kind: str, author_name) -> tuple:
        body = conv.get("preview")
        if body is None:
            if kind == "self":
                return ("Jot things down — they stay on this device", True)
            if kind == "group":
                return ("A new group. Say something to everyone", True)
            return ("Say hello — sealed end to end", True)
        body = " ".join(str(body).split())
        if conv.get("last_kind") == "event":
            return body, True
        if kind == "group":
            if conv.get("last_direction") == "out":
                return f"You: {body}", False
            who = author_name(conv.get("last_author")) if author_name and \
                conv.get("last_author") else ""
            return (f"{who}: {body}" if who else body), False
        return body, False

    def _sync(self, *_a):
        self._rect.pos, self._rect.size = self.pos, self.size
        self._wash.pos, self._wash.size = self.pos, self.size

    def set_selected(self, selected: bool) -> None:
        self._wash_col.a = T.select[3] if selected else 0

    @staticmethod
    def _mark(widget, glyph: str):
        widget.canvas.clear()
        with widget.canvas:
            draw_icon(glyph, (widget.x + widget.width / 2),
                      (widget.y + widget.height / 2), dp(14), C(T.text_3))

    # ---- touches: tap opens, hold selects (then taps add and remove) --------
    def on_touch_down(self, touch):
        if not self.collide_point(*touch.pos) or touch.is_mouse_scrolling:
            return super().on_touch_down(touch)
        self._held = False
        screen = self._screen
        if screen is not None and self.kind != "self":
            if screen.selecting:
                screen.toggle_selection(self.peer)
                return True
            if getattr(touch, "button", "left") == "right":
                screen.start_selection(self.peer)
                return True
            self._press = (touch.uid, touch.pos, Clock.schedule_once(
                lambda _dt: self._long_press(touch), self.LONG_PRESS))
        return super().on_touch_down(touch)

    def _long_press(self, touch):
        if self._press and self._press[0] == touch.uid and not swiped(touch):
            self._press = None
            self._held = True
            self.state = "normal"
            self._screen.start_selection(self.peer)

    def on_touch_move(self, touch):
        if self._press and self._press[0] == touch.uid:
            ox, oy = self._press[1]
            if abs(touch.x - ox) > dp(10) or abs(touch.y - oy) > dp(10):
                self._press[2].cancel()
                self._press = None
        return super().on_touch_move(touch)

    def on_touch_up(self, touch):
        if self._press and self._press[0] == touch.uid:
            self._press[2].cancel()
            self._press = None
        return super().on_touch_up(touch)

    def _released(self, on_open) -> None:
        if self._held:              # the hold selected it; do not open it
            self._held = False
            return
        on_open(self.peer)


class ArchiveRow(ButtonBehavior, BoxLayout):
    """The way into archived chats, at the top of the list: how many, and
    how many of their messages are unread. With another icon and title
    (v14), the way into message requests."""

    def __init__(self, count: int, unread: int, on_open: Callable,
                 icon: str = "archive", title: str = "Archived chats", **kw):
        kw.setdefault("size_hint_y", None)
        kw.setdefault("height", max(dp(60), line_height(17) + dp(26)))
        kw.setdefault("padding", [dp(18), dp(6), dp(18), dp(6)])
        kw.setdefault("spacing", dp(14))
        super().__init__(**kw)
        disc = Widget(size_hint_x=None, width=dp(52))

        def paint(w, *_a):
            w.canvas.clear()
            with w.canvas:
                Color(*C(T.surface_hi))
                d = dp(44)
                SmoothEllipse(pos=(w.x + (w.width - d) / 2,
                                   w.y + (w.height - d) / 2), size=(d, d))
                draw_icon(icon, w.x + w.width / 2, w.y + w.height / 2,
                          dp(22), C(T.text_2))
        disc.bind(pos=paint, size=paint)
        self.add_widget(disc)
        self.add_widget(single_line(title, fs(17), T.text_2))
        tail = BoxLayout(size_hint_x=None, width=dp(64), spacing=dp(6))
        tail.add_widget(single_line(str(count), fs(14), T.text_3,
                                    halign="right"))
        if unread:
            holder = AnchorLayout(size_hint_x=None, width=dp(36),
                                  anchor_x="right")
            holder.add_widget(UnreadBadge(min(unread, 9999), muted=True))
            tail.add_widget(holder)
        self.add_widget(tail)
        hairline(self, "bottom", inset=dp(18) + dp(52) + dp(14))
        with self.canvas.before:
            self._bg = Color(0, 0, 0, 0)
            self._rect = Rectangle()
        self.bind(pos=lambda *_a: self._sync(), size=lambda *_a: self._sync(),
                  state=lambda _w, st: setattr(
                      self._bg, "rgba", C(T.press) if st == "down"
                      else (0, 0, 0, 0)))
        self.bind(on_release=lambda _w: on_open())

    def _sync(self):
        self._rect.pos, self._rect.size = self.pos, self.size


class FabButton(IconButton):
    """The compose button: a larger gold disc, lifted off the page."""

    def _redraw(self, *_a):
        self.canvas.clear()
        d = min(self.width, self.height)
        with self.canvas:
            Color(0, 0, 0, .28 if T.dark else .12)
            Ellipse(pos=((self.x + self.width / 2) - d / 2, (self.y + self.height / 2) - d / 2 -
                         dp(2)), size=(d, d))
            Color(*C(T.accent_press if self.state == "down" else T.accent))
            SmoothEllipse(pos=((self.x + self.width / 2) - d / 2,
                               (self.y + self.height / 2) - d / 2),
                          size=(d, d))
            draw_icon(self._icon, (self.x + self.width / 2), (self.y + self.height / 2), dp(24),
                      C(T.on_accent), width=dp(1.0))


class ChatsScreen(SwipeGestures, Screen):
    """Home: the wordmark, who you are, your conversations, and the button
    that starts a new one."""

    def __init__(self, app: "FextApp", **kw):
        super().__init__(name="chats", **kw)
        self.app = app
        root = FloatLayout()
        paint_round(root, T.bg, radius=0)
        self.add_widget(root)
        column = BoxLayout(orientation="vertical", size_hint=(1, 1),
                           pos_hint={"x": 0, "y": 0})
        root.add_widget(column)

        # ---- the head: the menu, the wordmark (who you are beneath), search --
        head = BoxLayout(size_hint_y=None, height=max(dp(72), line_height(26)
                                                      + line_height(13.5)
                                                      + dp(22)),
                         padding=[dp(4), dp(4), dp(6), dp(4)], spacing=dp(2))
        head.add_widget(IconButton("menu", label="Menu",
                                   pos_hint={"center_y": .5},
                                   on_release=lambda _w:
                                   self.app.open_drawer()))
        titles = BoxLayout(orientation="vertical",
                           padding=[dp(6), dp(10), 0, dp(8)])
        self.brand = single_line(APP_NAME, fs(26), T.text)
        titles.add_widget(self.brand)
        # Not in capitals: an address is case-sensitive Base58.
        self.me_label = single_line("", fs(13.5), T.text_3, italic=True)
        titles.add_widget(self.me_label)
        head.add_widget(titles)
        head.add_widget(IconButton("search", label="Search",
                                   pos_hint={"center_y": .5},
                                   on_release=lambda _w:
                                   self.app.open_search()))
        hairline(head, "bottom", inset=dp(20), inset_right=dp(20))
        self.head = head
        self.head_box = BoxLayout(size_hint_y=None, height=head.height)
        self.head_box.add_widget(head)
        column.add_widget(self.head_box)
        # ---- search: the head becomes a field, the list becomes results ------
        self.searching = False
        self._search_ev = None
        self.search_head = BoxLayout(size_hint_y=None, height=head.height,
                                     padding=[dp(4), dp(4), dp(6), dp(4)],
                                     spacing=dp(2))
        self.search_head.add_widget(IconButton(
            "back", label="Close search", pos_hint={"center_y": .5},
            on_release=lambda _w: self.exit_search()))
        self.search_field = Field("Search names and messages",
                                  pos_hint={"center_y": .5})
        self.search_field.input.font_size = fs(18)
        self.search_field.input.bind(text=lambda _w, v: self._search_soon())
        self.search_head.add_widget(self.search_field)
        self.search_clear = IconButton(
            "close", label="Clear search", pos_hint={"center_y": .5},
            on_release=lambda _w: setattr(self.search_field, "text", ""))
        self.search_head.add_widget(self.search_clear)
        # ---- hold a chat: the head becomes what can be done with it --------
        self.selected: list = []          # peers, in the order picked
        self.view = "chats"               # or "archive", "requests" (v14)
        self._rows: dict = {}             # peer -> (signature, row)
        self.select_head = BoxLayout(size_hint_y=None, height=head.height,
                                     padding=[dp(4), dp(4), dp(4), dp(4)],
                                     spacing=dp(2))
        self.select_head.add_widget(IconButton(
            "close", label="Cancel selection", pos_hint={"center_y": .5},
            on_release=lambda _w: self.clear_selection()))
        self.select_count = single_line("1", fs(21), T.text,
                                        padding=[dp(6), 0])
        self.select_head.add_widget(self.select_count)
        self.act_mute = IconButton("bell_off", label="Mute",
                                   pos_hint={"center_y": .5},
                                   on_release=lambda _w: self._act_mute())
        self.act_archive = IconButton("archive", label="Archive",
                                      pos_hint={"center_y": .5},
                                      on_release=lambda _w:
                                      self._act_archive())
        self.act_delete = IconButton("delete", label="Delete",
                                     pos_hint={"center_y": .5},
                                     on_release=lambda _w: self._act_delete())
        self.act_more = IconButton("more", label="More",
                                   pos_hint={"center_y": .5},
                                   on_release=lambda _w: self._act_more())
        for button in (self.act_mute, self.act_archive, self.act_delete,
                       self.act_more):
            self.select_head.add_widget(button)
        self.archive_head = BoxLayout(size_hint_y=None, height=head.height,
                                      padding=[dp(4), dp(4), dp(6), dp(4)],
                                      spacing=dp(2))
        self.archive_head.add_widget(IconButton(
            "back", label="Back to chats", pos_hint={"center_y": .5},
            on_release=lambda _w: self.show_archive(False)))
        self.archive_head.add_widget(single_line("Archived chats", fs(22),
                                                 T.text, padding=[dp(6), 0]))
        self.requests_head = BoxLayout(size_hint_y=None, height=head.height,
                                       padding=[dp(4), dp(4), dp(6), dp(4)],
                                       spacing=dp(2))
        self.requests_head.add_widget(IconButton(
            "back", label="Back to chats", pos_hint={"center_y": .5},
            on_release=lambda _w: self.show_view("chats")))
        self.requests_head.add_widget(single_line(
            "Message requests", fs(22), T.text, padding=[dp(6), 0]))

        # ---- the status line: tap it to reconnect at once --------------------
        ribbon = TappableBox(on_tap=lambda: self.app.retry_now(),
                             orientation="horizontal", size_hint_y=None,
                             height=max(dp(40), line_height(14) + dp(12)),
                             padding=[dp(20), 0, dp(20), 0])
        self.status_label = Label(text="Starting…", font_size=fs(14),
                                  italic=True, color=C(T.text_3),
                                  halign="left", valign="middle",
                                  shorten=True, shorten_from="right")
        self.status_label.bind(size=lambda w, v: setattr(w, "text_size", v))
        ribbon.add_widget(self.status_label)
        self.retry_hint = CapsLabel("Tap to retry", size=10, color=T.accent,
                                    size_hint=(None, 1), halign="right")
        self.retry_hint.width = self.retry_hint.natural_width + dp(4)
        self.retry_hint.opacity = 0
        ribbon.add_widget(self.retry_hint)
        column.add_widget(ribbon)

        # ---- the list --------------------------------------------------------
        self.scroll = ScrollView(bar_width=dp(3), do_scroll_x=False)
        self.list = BoxLayout(orientation="vertical", size_hint_y=None,
                              padding=[0, 0, 0, dp(96)])
        self.list.bind(minimum_height=self.list.setter("height"))
        self.scroll.add_widget(self.list)
        column.add_widget(self.scroll)

        # ---- the compose button ----------------------------------------------
        self.fab = FabButton("edit", label="New conversation",
                             size=(dp(60), dp(60)),
                             on_release=lambda _w: self.app.open_compose())
        holder = AnchorLayout(anchor_x="right", anchor_y="bottom",
                              padding=[0, 0, dp(20), dp(24)],
                              size_hint=(1, 1), pos_hint={"x": 0, "y": 0})
        holder.add_widget(self.fab)
        root.add_widget(holder)
        self.fab_holder, self._root = holder, root

    # ---- v11: a swipe to the right brings the menu in ------------------------------
    def swipe_kind(self, touch, dx: float) -> Optional[str]:
        if dx <= 0 or self.searching or self.selecting:
            return None
        wx, wy = window_pos(self, *touch.opos)
        return "menu" if hits(self.scroll, wx, wy) else None

    # ---- search ----------------------------------------------------------------
    def enter_search(self) -> None:
        if self.searching or not self.app.keys.has_identity:
            return
        self.clear_selection()
        self.searching = True
        self._set_head()
        self.search_field.text = ""
        self._show_results("")
        Clock.schedule_once(lambda _dt: setattr(self.search_field.input,
                                                "focus", True), 0.05)

    def exit_search(self) -> None:
        if not self.searching:
            return
        self.searching = False
        if self._search_ev is not None:
            self._search_ev.cancel()
            self._search_ev = None
        self.search_field.input.focus = False
        self._set_head()
        self.app.refresh_sidebar()

    def _search_soon(self) -> None:
        """Search as you type, once the typing pauses for a moment."""
        if not self.searching:
            return
        if self._search_ev is not None:
            self._search_ev.cancel()
        self._search_ev = Clock.schedule_once(
            lambda _dt: self._show_results(self.search_field.text), 0.18)

    def _show_results(self, query: str) -> None:
        self._search_ev = None
        self.list.clear_widgets()
        self.scroll.scroll_y = 1
        app = self.app
        q = (query or "").strip()
        if not q:
            self.list.add_widget(InfoLabel(
                "Names, usernames, addresses and the words of your "
                "messages, on this device only.", color=T.text_3,
                italic=True, font_size=fs(15.5), halign="center",
                padding=[dp(32), dp(28)]))
            return
        fold = q.casefold()
        chats = []
        for conv in app.store.conversations(me=app.keys.address):
            name, kind = conversation_title(app, conv["peer"])
            hay = " ".join(filter(None, (name, conv.get("username"),
                                         conv["peer"]))).casefold()
            if fold in hay:
                chats.append((conv["peer"], name, kind))
        hits = app.store.search_messages(q, limit=80)
        if chats:
            self.list.add_widget(SectionHead("Chats"))
            for peer, name, kind in chats[:12]:
                self.list.add_widget(PersonRow(
                    peer, name, short_addr(peer, 14) if kind == "dm" else
                    ("Group" if kind == "group" else "Saved messages"),
                    kind=kind, on_tap=lambda p=peer: self._open(p)))
        if hits:
            self.list.add_widget(SectionHead(
                f"Messages · {len(hits)}{'+' if len(hits) >= 80 else ''}"))
            author = app.conversation_screen.author_name
            for hit in hits:
                title, kind = conversation_title(app, hit["peer"])
                body = hit["body"] or ""
                if kind == "group" and hit.get("author"):
                    body = f"{author(hit['author'])}: {body}"
                elif hit["direction"] == "out" and kind != "self":
                    body = f"You: {body}"
                self.list.add_widget(SearchHit(
                    title, hit["peer"], kind, pretty_time(hit["created_at"]),
                    search_snippet(body, q), on_tap=lambda h=hit:
                    self._open(h["peer"], h["id"])))
        if not chats and not hits:
            self.list.add_widget(InfoLabel(
                f"Nothing here matches “{q}”.", color=T.text_3,
                italic=True, font_size=fs(15.5), halign="center",
                padding=[dp(32), dp(28)]))

    def _open(self, peer: str, message_id: Optional[int] = None) -> None:
        self.search_field.input.focus = False
        if message_id is None:
            self.app.open_conversation(peer)
        else:
            self.app.open_conversation_at(peer, message_id)

    def refresh_header(self) -> None:
        keys = self.app.keys
        if not keys.has_identity:
            self.me_label.text = "end-to-end encrypted correspondence"
            return
        self.me_label.text = (f"@{keys.username}" if keys.username
                              else "unregistered") + \
            f"  ·  {short_addr(keys.address, 10)}"

    def set_status(self, text: str, color: str) -> None:
        self.status_label.text = text
        color = retint(color)
        calm = color in (T.ok, T.text_3)
        self.status_label.color = C(T.text_3 if calm else color)
        # Offer the retry only when it would do something, and only once.
        self.retry_hint.opacity = 0 if calm or "retry" in text.lower() else 1

    def refresh_list(self, conversations: list) -> None:
        """Saved messages first, then pinned chats (the latest pin first),
        then the rest by recent activity — or, in the archive, only the
        archived ones. Rows whose chat has not changed are kept, not
        rebuilt, which is what makes coming back to the list cheap."""
        if self.searching:              # results stay until search closes
            return
        self._convs = {c["peer"]: c for c in conversations}
        self.list.clear_widgets()
        keys = self.app.keys
        if not keys.has_identity:
            self.list.add_widget(self._empty_state())
            return
        notes = next((c for c in conversations if c.get("kind") == "self"),
                     None) or {"peer": keys.address, "kind": "self",
                               "preview": None, "unread": 0}
        rest = [c for c in conversations if c.get("kind") != "self"]
        # v14: someone new waits under Message requests (blocked: nowhere).
        requests = [c for c in rest if c.get("request") and
                    not c.get("blocked")]
        rest = [c for c in rest if not c.get("request")]
        archived = [c for c in rest if c.get("archived")]
        live = [c for c in rest if not c.get("archived")]
        if self.view == "archive":
            shown = sorted(archived, key=lambda c: -(c.get("pinned") or 0)) \
                if archived else []
            if not archived:
                self.show_view("chats")
                return
        elif self.view == "requests":
            shown = requests
            if not requests:
                self.show_view("chats")
                return
        else:
            pinned = sorted((c for c in live if c.get("pinned")),
                            key=lambda c: -c["pinned"])
            shown = [notes] + pinned + [c for c in live if not c.get("pinned")]
            if requests:
                self.list.add_widget(ArchiveRow(
                    len(requests), sum(int(c.get("unread") or 0)
                                       for c in requests),
                    lambda: self.show_view("requests"), icon="person_add",
                    title="Message requests"))
            if archived:
                self.list.add_widget(ArchiveRow(
                    len(archived), sum(int(c.get("unread") or 0)
                                       for c in archived),
                    lambda: self.show_view("archive")))
        author = self.app.conversation_screen.author_name
        rows = {}
        for conv in shown:
            sig = tuple(sorted((k, str(v)) for k, v in conv.items()))
            old = self._rows.get(conv["peer"])
            if old is not None and old[0] == sig:
                row = old[1]
            else:
                row = ConversationRow(conv, self.app.open_conversation,
                                      author, screen=self)
            rows[conv["peer"]] = (sig, row)
            row.set_selected(conv["peer"] in self.selected)
            self.list.add_widget(row)
        self._rows = rows
        self.selected = [p for p in self.selected if p in self._convs]
        self._sync_select_head()
        if self.view == "chats" and not live:
            self.list.add_widget(self._empty_state())

    # ---- the archive, and message requests (v14) ----------------------------------
    @property
    def showing_archive(self) -> bool:
        return self.view == "archive"

    def show_archive(self, on: bool) -> None:
        self.show_view("archive" if on else "chats")

    def show_view(self, view: str) -> None:
        if view == self.view:
            return
        self.clear_selection()
        self.view = view
        self._set_head()
        self.scroll.scroll_y = 1
        self.app.refresh_sidebar()

    def _set_head(self) -> None:
        head = (self.select_head if self.selected else
                self.search_head if self.searching else
                self.archive_head if self.view == "archive" else
                self.requests_head if self.view == "requests" else self.head)
        if head.parent is not self.head_box:
            self.head_box.clear_widgets()
            self.head_box.add_widget(head)
        # The compose button belongs to the plain list only. Out of the
        # layout, not just hidden: a hidden widget still takes taps.
        want = head is self.head
        if want and self.fab_holder.parent is None:
            self._root.add_widget(self.fab_holder)
        elif not want and self.fab_holder.parent is not None:
            self._root.remove_widget(self.fab_holder)

    # ---- selection: hold a chat, then tap more -----------------------------------
    @property
    def selecting(self) -> bool:
        return bool(self.selected)

    def start_selection(self, peer: str) -> None:
        if self.searching or peer not in self._convs or \
                self._convs[peer].get("kind") == "self" or \
                self.view == "requests":
            return
        if peer not in self.selected:
            self.selected.append(peer)
        self._paint_selection()

    def toggle_selection(self, peer: str) -> None:
        if peer in self.selected:
            self.selected.remove(peer)
        elif peer in self._convs and self._convs[peer].get("kind") != "self":
            self.selected.append(peer)
        self._paint_selection()

    def clear_selection(self) -> None:
        if self.selected:
            self.selected = []
            self._paint_selection()

    def _paint_selection(self) -> None:
        for peer, (_sig, row) in self._rows.items():
            row.set_selected(peer in self.selected)
        self._sync_select_head()

    def _sync_select_head(self) -> None:
        self._set_head()
        if not self.selected:
            return
        convs = [self._convs[p] for p in self.selected if p in self._convs]
        self.select_count.text = str(len(convs))
        mute = self.mute_choice(convs)
        self.act_mute.set_icon("bell_off" if mute else "bell")
        self.act_mute.label = ("Mute" if mute else "Unmute") + \
            (" all" if len(convs) > 1 else "")
        self.act_archive.set_icon("unarchive" if self.showing_archive
                                  else "archive")
        self.act_archive.label = "Unarchive" if self.showing_archive \
            else "Archive"

    @staticmethod
    def is_muted(conv: dict) -> bool:
        return bool(conv.get("muted"))

    @classmethod
    def mute_choice(cls, convs: list) -> bool:
        """True to offer Mute, False for Unmute: one chat, its opposite;
        several, whichever most of them need (a tie mutes)."""
        muted = sum(1 for c in convs if cls.is_muted(c))
        return muted * 2 <= len(convs) if len(convs) > 1 else not muted

    def _picked(self) -> list:
        return [self._convs[p] for p in self.selected if p in self._convs]

    def _act_mute(self) -> None:
        convs = self._picked()
        mute = self.mute_choice(convs)
        self.clear_selection()
        self.app.set_chats_muted([c["peer"] for c in convs], mute)

    def _act_archive(self) -> None:
        peers = [c["peer"] for c in self._picked()]
        archive = not self.showing_archive
        self.clear_selection()
        self.app.set_chats_archived(peers, archive)

    def _act_delete(self) -> None:
        convs = self._picked()
        if convs:
            DeleteChatsSheet(self.app, convs,
                             on_done=self.clear_selection).open()

    def _act_more(self) -> None:
        convs = self._picked()
        if not convs:
            return
        peers = [c["peer"] for c in convs]
        app = self.app
        pin = not all(c.get("pinned") for c in convs)
        unread = any(int(c.get("unread") or 0) or c.get("marked_unread")
                     for c in convs)
        items = [("unpin" if not pin else "pin",
                  ("Pin" if pin else "Unpin") +
                  (" all" if len(convs) > 1 else ""),
                  lambda: app.set_chats_pinned(peers, pin)),
                 ("read" if unread else "unread",
                  "Mark as read" if unread else "Mark as unread",
                  lambda: (app.mark_chats_read if unread
                           else app.mark_chats_unread)(peers))]
        direct = [c for c in convs if c.get("kind") == "dm"]
        if len(direct) == len(convs):
            block = not all(c.get("blocked") for c in convs)
            items.append(("block", ("Block" if block else "Unblock") +
                          (f" {len(convs)} contacts" if len(convs) > 1
                           else ""),
                          lambda: app.set_blocked(peers, block)))

        def run(action):
            self.clear_selection()
            action()
        MenuSheet([(icon, label, lambda a=action: run(a))
                   for icon, label, action in items]).open()

    def _empty_state(self) -> BoxLayout:
        box = BoxLayout(orientation="vertical", size_hint_y=None,
                        padding=[dp(32), dp(40), dp(32), 0], spacing=dp(14))
        box.bind(minimum_height=box.setter("height"))
        box.add_widget(InfoLabel(FLEURON, color=T.accent, font_size=fs(34),
                                 halign="center"))
        box.add_widget(InfoLabel("No correspondence yet", font_size=fs(22),
                                 halign="center"))
        box.add_widget(InfoLabel(
            "Add someone by their username or Fec… address, or gather "
            "several into a group. Every word is sealed on this device "
            "before it leaves, and only they can open it.",
            color=T.text_3, font_size=fs(15.5), halign="center"))
        holder = AnchorLayout(size_hint_y=None, height=TOUCH + dp(12))
        button = Btn("Add a contact", size_hint_x=None,
                     on_release=lambda _w: self.app.open_add_contact())
        button.width = max(dp(200), button.natural_width())
        holder.add_widget(button)
        box.add_widget(holder)
        return box


def search_snippet(body: str, query: str, width: int = 70) -> str:
    """Kivy markup: the words around the first match, the match in gold
    and bold, everything escaped."""
    text = " ".join((body or "").split())
    at = text.casefold().find(query.casefold()) if query else -1
    if at < 0:
        return escape_markup(text[:width])
    start = max(0, at - width // 3)
    end = min(len(text), at + len(query) + width)
    lead = ("…" if start else "") + text[start:at]
    match = text[at:at + len(query)]
    tail = text[at + len(query):end] + ("…" if end < len(text) else "")
    return (escape_markup(lead) + f"[b][color={T.accent}]"
            + escape_markup(match) + "[/color][/b]" + escape_markup(tail))


class SearchHit(ButtonBehavior, BoxLayout):
    """A message found by search: its chat, when, and the words around
    the match. Tap it to open the chat at that message."""

    def __init__(self, title: str, seed: str, kind: str, when: str,
                 snippet_markup: str, on_tap: Callable, **kw):
        kw.setdefault("size_hint_y", None)
        kw.setdefault("height", max(dp(72), line_height(16.5)
                                    + line_height(15) + dp(24)))
        kw.setdefault("padding", [dp(16), dp(8), dp(16), dp(8)])
        kw.setdefault("spacing", dp(14))
        super().__init__(**kw)
        self.add_widget(Avatar(seed, title, diameter=dp(44), kind=kind,
                               pos_hint={"center_y": .5}))
        texts = BoxLayout(orientation="vertical", spacing=dp(2))
        top = BoxLayout(size_hint_y=None, height=line_height(16.5))
        top.add_widget(single_line(title, fs(16.5), T.text, bold=True))
        stamp = single_line(when, fs(13), T.text_3, size_hint_x=None,
                            halign="right")
        stamp.texture_update()
        stamp.width = stamp.texture_size[0] + dp(4)
        top.add_widget(stamp)
        texts.add_widget(top)
        snippet = Label(text=snippet_markup, markup=True, font_size=fs(15),
                        color=C(T.text_2), halign="left", valign="top",
                        shorten=True, shorten_from="right", max_lines=1,
                        size_hint_y=None, height=line_height(15))
        snippet.bind(size=lambda w, v: setattr(w, "text_size", v))
        texts.add_widget(snippet)
        self.add_widget(texts)
        hairline(self, "bottom", inset=dp(74))
        with self.canvas.before:
            self._bg = Color(0, 0, 0, 0)
            self._rect = Rectangle()
        self.bind(pos=self._sync, size=self._sync,
                  state=lambda _w, st: setattr(
                      self._bg, "rgba", C(T.press) if st == "down"
                      else (0, 0, 0, 0)))
        self.bind(on_release=lambda _w: on_tap())

    def _sync(self, *_a):
        self._rect.pos, self._rect.size = self.pos, self.size


class ComposeSheet(Sheet):
    """The compose button's sheet: a new contact, a new group, notes to self,
    or one of the people you already know."""

    def __init__(self, app: "FextApp") -> None:
        super().__init__("New conversation")
        self.app = app
        self.card.padding = [0, dp(8), 0, dp(16)]
        self.title_label.padding = [dp(22), 0]
        self.add(rows_card([
            ListRow("person_add", "Add a contact",
                    "By username or Fec… address",
                    on_tap=lambda: self._then(app.open_add_contact)),
            ListRow("group", "New group",
                    f"You and up to {MAX_GROUP_MEMBERS - 1} others",
                    on_tap=lambda: self._then(app.open_new_group)),
            ListRow("bookmark", "Saved messages", "Kept on this device only",
                    on_tap=lambda: self._then(
                        lambda: app.open_conversation(app.keys.address))),
        ]))
        contacts = app.store.contacts() if app.store else []
        if contacts:
            self.add(SectionHead("Contacts"))
            self.add(rows_card([
                PersonRow(c["address"], c.get("username") or
                          short_addr(c["address"], 14),
                          short_addr(c["address"], 18),
                          on_tap=lambda a=c["address"]: self._then(
                              lambda: app.open_conversation(a)))
                for c in contacts], inset=dp(76)))

    def _then(self, action: Callable) -> None:
        self.dismiss()
        Clock.schedule_once(lambda _dt: action(), 0.05)


# =============================================================================
#  The conversation
# =============================================================================
_METRIC_LABEL = None


def measure_text(text: str, font_size: float, wrap_width: float,
                 italic: bool = False, markup: bool = False) -> tuple:
    """Pixel (width, height) of `text` wrapped at `wrap_width`.

    One shared, never-displayed Label measures every bubble: the widget
    that DISPLAYS message text on a desktop is a TextInput (so it can be
    selected), and a TextInput cannot report its size until the frame after
    it is given one. Text that fits keeps its natural width; only text that
    needs wrapping is measured at the wrap width.
    """
    global _METRIC_LABEL
    if _METRIC_LABEL is None:
        _METRIC_LABEL = Label(halign="left", valign="top",
                              size_hint=(None, None))
    metric = _METRIC_LABEL
    metric.font_size = font_size
    metric.italic = italic
    metric.markup = markup
    metric.text = text
    if len(text) * font_size * 0.42 < wrap_width * 3:
        metric.text_size = (None, None)
        metric.texture_update()
        width, height = metric.texture_size
        if width <= wrap_width:
            return width, height
    metric.text_size = (wrap_width, None)
    metric.texture_update()
    return metric.texture_size


_METRIC_INPUTS: dict = {}


def measure_selectable(text: str, font_size: float,
                       wrap_width: float) -> tuple:
    """measure_text for the desktop's selectable text, by its own wrapping:
    a TextInput breaks a word too long for a line (a link, mostly) where
    it runs out of room, where a label first moves it to a line of its
    own — so a label's measure left a blank line under such a message."""
    metric = _METRIC_INPUTS.get(font_size)
    if metric is None:
        metric = _METRIC_INPUTS[font_size] = SelectableText(
            font_size=font_size)
    metric.width = wrap_width + metric.padding[0] + metric.padding[2]
    lines, _flags = metric._split_smart(text)
    lines = lines or [""]
    width = max(metric._text_width(line) for line in lines)
    one = metric._label_cached.get_extents("_")[1]
    height = len(lines) * (one + metric.line_spacing) + metric.padding[1] + \
        metric.padding[3]
    return min(width, wrap_width), height


class InkTextInput(TextInput):
    """A text field whose colour emoji keep their colours (v12).

    Kivy draws a field's lines in white and tints them with the text colour,
    which is right for letters but turns a colour glyph into a silhouette of
    that colour (dark on the light page). Here each line is drawn in the
    text colour itself and the tint is white; the hint and a disabled
    field are drawn the same way, in their own colours."""

    ink = ColorProperty([0, 0, 0, 1])
    hint_ink = ColorProperty([.5, .5, .5, 1])

    def __init__(self, **kw):
        ink = kw.pop("foreground_color", None)
        hint = kw.pop("hint_text_color", None)
        super().__init__(**kw)
        if ink is not None:
            self.ink = ink
        if hint is not None:
            self.hint_ink = hint
        self.foreground_color = (1, 1, 1, 1)
        self.hint_text_color = (1, 1, 1, 1)
        self.disabled_foreground_color = (1, 1, 1, .5)
        self.bind(ink=self._reink, hint_ink=self._reink)

    def _reink(self, *_a) -> None:
        self._line_options = None
        self._trigger_refresh_text()

    def _get_line_options(self):
        options = super()._get_line_options()
        options["color"] = tuple(self.ink)
        return options

    def _create_line_label(self, text, hint=False):
        if not hint:
            return super()._create_line_label(text, hint)
        options = self._get_line_options()
        options["color"] = tuple(self.hint_ink)
        try:
            return super()._create_line_label(text, hint)
        finally:
            options["color"] = tuple(self.ink)


class SelectableText(InkTextInput):
    """Message text you can highlight and copy (desktop).

    A READ-ONLY TextInput: drag to select, Ctrl+A / Ctrl+C. A ScrollView
    holds each touch for scroll_timeout and only hands it on if the finger
    has not travelled, so a flick still scrolls. Painted to look exactly
    like a label: no ground, no border, no cursor.
    """

    def __init__(self, on_tap: Optional[Callable] = None, **kw):
        kw.setdefault("readonly", True)
        kw.setdefault("multiline", True)
        kw.setdefault("background_color", (0, 0, 0, 0))
        kw.setdefault("background_normal", "")
        kw.setdefault("background_active", "")
        kw.setdefault("background_disabled_normal", "")
        kw.setdefault("foreground_color", C(T.text))
        kw.setdefault("selection_color", C(T.accent)[:3] + [0.35])
        kw.setdefault("cursor_color", (0, 0, 0, 0))
        kw.setdefault("cursor_width", 0)
        kw.setdefault("padding", [0, 0, 0, 0])
        kw.setdefault("size_hint", (None, None))
        super().__init__(**kw)
        self._on_tap = on_tap
        self._links: list = []                    # v11: (start, end) spans
        self._link_lines = InstructionGroup()
        self.canvas.after.add(self._link_lines)
        # A TextInput scrolls to keep its cursor in view. Given the width
        # it starts with (100px) every message wraps tall, and with the
        # cursor at the end it scrolled to the LAST line — which then stayed
        # scrolled once the bubble gave it its real size, hiding the first
        # lines. The cursor lives at the start, and the view never scrolls.
        self.cursor = (0, 0)
        self.bind(size=self._unscroll, text=self._unscroll)

    def _unscroll(self, *_a):
        self.scroll_x = self.scroll_y = 0

    # ---- v11: links, underlined; which character a click is on ---------------
    def set_links(self, spans: list) -> None:
        self._links = [(start, end) for start, end, _url in spans]
        self._trigger_update_graphics()

    def _update_graphics(self, *largs):
        super()._update_graphics(*largs)
        self._draw_links()

    def _draw_links(self) -> None:
        """A gold rule under each link (a TextInput draws its text in one
        colour), line by line where a link wraps."""
        group = self._link_lines
        group.clear()
        lines = self._lines
        if not self._links or not lines:
            return
        dy = self.line_height + self.line_spacing
        left = self.x + self.padding[0] - self.scroll_x
        top = self.top - self.padding[1] + self.scroll_y
        group.add(Color(*(C(T.accent)[:3] + [0.9])))
        for start, end in self._links:
            c0, r0 = self.get_cursor_from_index(start)
            c1, r1 = self.get_cursor_from_index(end)
            for row in range(r0, min(r1, len(lines) - 1) + 1):
                line = lines[row]
                a = c0 if row == r0 else 0
                b = c1 if row == r1 else len(line.rstrip())
                if b <= a:
                    continue
                x0 = left + self._text_width(line[:a])
                x1 = left + self._text_width(line[:b])
                y = top - row * dy - self.line_height * 0.84
                group.add(Rectangle(pos=(x0, y),
                                    size=(x1 - x0, max(1.0, dp(1)))))

    def _text_width(self, text: str) -> float:
        return self._get_text_width(text, self.tab_width,
                                    self._label_cached) if text else 0.0

    def index_at(self, x: float, y: float) -> int:
        """The index in the text of the character at (x, y) — in the
        coordinates of this widget's position — or -1."""
        lines = self._lines
        if not lines:
            return -1
        col, row = self.get_cursor_from_xy(x, y)
        if row >= len(lines):
            return -1
        line = lines[row]
        left = self.x + self.padding[0] - self.scroll_x
        if x < left + self._text_width(line[:col]):
            col -= 1                     # the nearest gap is after it
        if col < 0 or col >= len(line):
            return -1
        return self.cursor_index((col, row))

    # Tapping a message marks it read; the TextInput swallows the touch, so
    # re-dispatch it — only when the press AND release were on this text.
    def on_touch_down(self, touch):
        handled = super().on_touch_down(touch)
        if handled:
            touch.ud["fext_tap_origin"] = self
        return handled

    def on_touch_up(self, touch):
        handled = super().on_touch_up(touch)
        if (self._on_tap is not None
                and touch.ud.get("fext_tap_origin") is self
                and self.collide_point(*touch.pos)):
            self._on_tap()
        return handled


def message_ext(msg: dict) -> dict:
    """The parsed `ext` column of a message row (reply, fwd, media)."""
    try:
        ext = json.loads(msg.get("ext") or "{}")
        return ext if isinstance(ext, dict) else {}
    except (TypeError, ValueError):
        return {}


_INLINE_TEXTURES: dict = {}


#: The largest inline picture shown: a photo's thumbnail is THUMB_EDGE, a
#: link preview's PREVIEW_THUMB_EDGE (v12).
INLINE_MAX_EDGE = 320


def texture_from_b64(data: str):
    """Kivy texture for a small inline JPEG (the photo thumbnail).

    Decoded once per picture and kept: a bubble repaints often (ticks,
    reactions) and must not decode it again each time. The pixels are kept
    too, because a texture made from memory has no file to reload from when
    Android recreates the GL context on resume: the reload observer puts
    them back, where it would otherwise come back blank."""
    if data in _INLINE_TEXTURES:
        return _INLINE_TEXTURES[data]
    import io as _io
    try:
        raw = b64d(data)
        header = image_header(raw)
        # Thumbnails and preview pictures are small JPEGs; anything else
        # is not decoded at all (v12).
        if header is None or header[0] != "JPEG" or \
                max(header[1:]) > INLINE_MAX_EDGE:
            return None
        from PIL import Image as _PIL
        with _PIL.open(_io.BytesIO(raw)) as im:
            tex = texture_from_pil(im)
    except Exception:
        return None
    if len(_INLINE_TEXTURES) > 400:          # a long scroll back: drop the oldest
        _INLINE_TEXTURES.pop(next(iter(_INLINE_TEXTURES)))
    _INLINE_TEXTURES[data] = tex
    return tex


class QuoteBlock(ButtonBehavior, BoxLayout):
    """The message a reply answers: a gold rule, who said it (capitals),
    and a line of what they said (italic). Tap it to go there."""

    def __init__(self, author: str, snippet: str, outgoing: bool,
                 on_tap: Optional[Callable] = None, **kw):
        kw.setdefault("orientation", "vertical")
        kw.setdefault("size_hint", (None, None))
        kw.setdefault("padding", [dp(12), dp(5), dp(8), dp(6)])
        super().__init__(**kw)
        with self.canvas.before:
            Color(*C(T.quote_own if outgoing else T.quote_peer))
            self._bg = SmoothRoundedRectangle(radius=[dp(4)])
            Color(*C(T.accent))
            self._bar = Rectangle()
        self.bind(pos=self._sync, size=self._sync)
        self.author = CapsLabel(author, size=10.5, color=T.accent)
        self.snippet = single_line(snippet, fs(15), T.text_2, italic=True,
                                   size_hint_y=None, height=line_height(15))
        self.add_widget(self.author)
        self.add_widget(self.snippet)
        self.height = self.author.height + self.snippet.height + dp(11)
        if on_tap is not None:
            self.bind(on_release=lambda _w: on_tap())

    def _sync(self, *_a):
        self._bg.pos, self._bg.size = self.pos, self.size
        self._bar.pos, self._bar.size = self.pos, (dp(2), self.height)

    def natural_width(self) -> float:
        return max(self.author.natural_width,
                   measure_text(self.snippet.text, fs(15), dp(600),
                                italic=True)[0]) + dp(22)


def clamp_lines(text: str, font_size: float, width: float, lines: int,
                italic: bool = False) -> str:
    """`text`, cut at a word and ended with an ellipsis if it would take
    more than `lines` lines at `width`."""
    one = measure_text("Ag", font_size, width, italic=italic)[1]
    room = one * lines + 0.5
    if measure_text(text, font_size, width, italic=italic)[1] <= room:
        return text
    words = text.split(" ")
    lo, hi = 0, len(words)
    while lo < hi:                       # the most words that still fit
        mid = (lo + hi + 1) // 2
        if measure_text(" ".join(words[:mid]) + "…", font_size, width,
                        italic=italic)[1] <= room:
            lo = mid
        else:
            hi = mid - 1
    if lo:
        return " ".join(words[:lo]).rstrip(",;:—-") + "…"
    cut = len(text)                      # one long word: cut it by letters
    while cut > 1 and measure_text(text[:cut] + "…", font_size, width,
                                   italic=italic)[1] > room:
        cut = cut * 3 // 4
    return text[:cut] + "…"


class LinkCard(ButtonBehavior, BoxLayout):
    """A link's preview in the message (v11): its site in capitals, its
    title, a line or two about it, and its picture — as the sender's phone
    found them; nothing is fetched to show it. Tap it to see where the
    link leads before going there."""

    THUMB = dp(56)

    def __init__(self, preview: dict, outgoing: bool, on_tap: Callable,
                 **kw):
        kw.setdefault("size_hint", (None, None))
        kw.setdefault("padding", [dp(12), dp(6), dp(8), dp(8)])
        kw.setdefault("spacing", dp(10))
        super().__init__(**kw)
        self.preview = preview
        with self.canvas.before:
            Color(*C(T.quote_own if outgoing else T.quote_peer))
            self._bg = SmoothRoundedRectangle(radius=[dp(4)])
            Color(*C(T.accent))
            self._bar = Rectangle()
        self.bind(pos=self._sync, size=self._sync)
        self.texts = BoxLayout(orientation="vertical", size_hint=(None, None),
                               spacing=dp(2), pos_hint={"top": 1})
        self.site = CapsLabel(preview.get("s") or link_host(preview["u"]),
                              size=10.5, color=T.accent)
        self.title = Label(text="", font_size=fs(15.5), color=C(T.text),
                           halign="left", valign="top",
                           size_hint=(None, None))
        self.desc = Label(text="", font_size=fs(14), italic=True,
                          color=C(T.text_2), halign="left", valign="top",
                          size_hint=(None, None))
        for part in (self.site, self.title, self.desc):
            self.texts.add_widget(part)
        self.add_widget(self.texts)
        self.thumb = None
        texture = texture_from_b64(preview["i"]) if preview.get("i") else None
        if texture is not None:
            self.thumb = KivyImage(texture=texture, size_hint=(None, None),
                                   size=(self.THUMB, self.THUMB),
                                   allow_stretch=True, keep_ratio=True,
                                   pos_hint={"top": 1})
            self.add_widget(self.thumb)
        self._laid_at = None
        self.bind(on_release=lambda _w: on_tap())

    def _sync(self, *_a):
        self._bg.pos, self._bg.size = self.pos, self.size
        self._bar.pos, self._bar.size = self.pos, (dp(2), self.height)

    def natural_width(self, max_w: float) -> float:
        return min(max_w, dp(300))

    def layout_for(self, width: float) -> float:
        """Lay the card out `width` wide; returns its height. The title
        keeps to two lines and the description to three."""
        if self._laid_at != width:
            self._laid_at = width
            pad_l, pad_t, pad_r, pad_b = self.padding
            text_w = max(dp(80), width - pad_l - pad_r - (
                self.THUMB + self.spacing if self.thumb else 0))
            self.site.size = (text_w, self.site.height)
            for label, key, size, lines, italic in (
                    (self.title, "t", 15.5, 2, False),
                    (self.desc, "d", 14, 3, True)):
                text = self.preview.get(key) or ""
                label.text = clamp_lines(text, fs(size), text_w, lines,
                                         italic=italic) if text else ""
                label.text_size = (text_w, None)
                label.texture_update()
                label.size = (text_w, label.texture_size[1] if text else 0)
            self.texts.width = text_w
            self.texts.height = (self.site.height + self.title.height +
                                 self.desc.height + self.texts.spacing * 2)
            inner = max(self.texts.height, self.THUMB if self.thumb else 0)
            self.size = (width, inner + pad_t + pad_b)
        return self.height


class MediaStatus(Label):
    """A small caption chip over a photo ('Downloading…', etc.)."""

    def __init__(self, **kw):
        super().__init__(font_size=fs(13.5), italic=True,
                         color=C("#FFFFF8"), size_hint=(None, None), **kw)
        with self.canvas.before:
            self._col = Color(0, 0, 0, .5)
            self._bg = RoundedRectangle(radius=[dp(11)])
        self.bind(pos=self._sync, size=self._sync,
                  texture_size=lambda w, v: setattr(
                      w, "size", (v[0] + dp(18), max(dp(24), v[1] + dp(6)))))

    def _sync(self, *_a):
        self._bg.pos, self._bg.size = self.pos, self.size
        self._col.a = .5 if self.text else 0


class ImageContent(ButtonBehavior, FloatLayout):
    """A photo in a bubble: the full image once it is here, the blurry
    inline thumbnail (plus a status chip) until then."""

    def __init__(self, msg: dict, media: dict, screen, **kw):
        kw.setdefault("size_hint", (None, None))
        super().__init__(**kw)
        self.msg, self.media, self.screen = msg, media, screen
        with self.canvas.before:
            Color(*C(T.surface_hi))
            self._ground = SmoothRoundedRectangle(radius=[dp(6)])
        self.bind(pos=self._sync, size=self._sync)
        self.picture = KivyImage(allow_stretch=True, keep_ratio=True,
                                 size_hint=(1, 1),
                                 pos_hint={"x": 0, "y": 0})
        self.add_widget(self.picture)
        self.chip = MediaStatus(pos_hint={"center_x": .5, "center_y": .5})
        self.add_widget(self.chip)
        self.bind(on_release=lambda _w: screen.on_media_tap(self.msg))
        self.refresh(msg)

    def _sync(self, *_a):
        self._ground.pos, self._ground.size = self.pos, self.size

    def natural_size(self, max_w: float) -> tuple:
        w0, h0 = self.media.get("w") or 4, self.media.get("h") or 3
        width = min(max_w, dp(260))
        height = max(dp(90), min(dp(340), width * h0 / float(w0)))
        return width, height

    def refresh(self, msg: dict) -> None:
        """Called on every repaint of the bubble (ticks, reactions, stars):
        it only touches the picture when what it should show has changed.
        Setting the same `source` again is not a change to Kivy, so clearing
        the texture first, as 9.1.1 did, left a white rectangle behind on
        the first repaint after a photo arrived."""
        self.msg = msg
        state = msg.get("media_state") or ""
        path = msg.get("media_path")
        if path and Path(path).is_file() and state in ("ready", ""):
            if self.picture.source != path:
                self.picture.source = path
            elif self.picture.texture is None:      # it failed, or was dropped
                self.picture.reload()
        elif self.media.get("thumb"):
            thumb = texture_from_b64(self.media["thumb"])
            if self.picture.source:
                self.picture.source = ""
            if self.picture.texture is not thumb:
                self.picture.texture = thumb
        outgoing = msg["direction"] == "out"
        if outgoing and state in ("waiting", "failed", "uploading") and \
                waits_for_tap(msg):
            state = "failed"          # v14: a day on, it waits for a tap
        if state == "pending" and not outgoing and \
                self.screen.app.store is not None and \
                not downloads_by_itself(self.screen.app.store, msg):
            state = "tap"                     # v14: it waits for a tap
        self.chip.text = {
            "uploading": "Sending…",
            "waiting": "Waiting to send",
            "tap": "Tap to download · " + size_text(
                int(self.media.get("size") or 0)),
            "pending": "Downloading…",
            "downloading": "Downloading…",
            "expired": "Expired · tap to ask again",
            "requested": "Asked for it again",
            "failed": ("Not sent · tap to retry" if outgoing
                       else "Not downloaded · tap to retry"),
            "unreadable": "This photo cannot be shown",
        }.get(state, "")


class Waveform(Widget):
    """Voice-note level bars; the played part is drawn in gold. With
    `on_seek`, a tap or a drag along it moves through the note (v11)."""

    def __init__(self, wave: str = "", on_seek: Optional[Callable] = None,
                 **kw):
        super().__init__(**kw)
        try:
            self._levels = list(b64d(wave)) if wave else []
        except (TypeError, ValueError):
            self._levels = []
        self.progress = 0.0
        self.on_seek = on_seek
        self.bind(pos=self._redraw, size=self._redraw)

    def _fraction(self, touch) -> float:
        return max(0.0, min(1.0, (touch.x - self.x) / max(1.0, self.width)))

    def on_touch_down(self, touch):
        if self.on_seek is None or not self.collide_point(*touch.pos) or \
                touch.is_mouse_scrolling:
            return super().on_touch_down(touch)
        touch.grab(self)
        touch.ud["fext_scrub"] = True
        self.set_progress(self._fraction(touch))
        return True

    def on_touch_move(self, touch):
        if touch.grab_current is self:
            self.set_progress(self._fraction(touch))
            return True
        return super().on_touch_move(touch)

    def on_touch_up(self, touch):
        if touch.grab_current is self:
            touch.ungrab(self)
            self.on_seek(self._fraction(touch))
            return True
        return super().on_touch_up(touch)

    def set_progress(self, fraction: float) -> None:
        self.progress = max(0.0, min(1.0, fraction))
        self._redraw()

    def _redraw(self, *_a):
        self.canvas.clear()
        bars = max(8, int(self.width / dp(4)))
        levels = self._levels or [60] * bars
        with self.canvas:
            for i in range(bars):
                lvl = levels[int(i * len(levels) / bars)] / 255.0
                height = max(dp(3), self.height * (0.18 + 0.82 * lvl))
                played = (i + 0.5) / bars <= self.progress
                Color(*C(T.accent if played else T.tick_grey))
                Rectangle(pos=(self.x + i * dp(4),
                               (self.y + self.height / 2) - height / 2),
                          size=(dp(2), height))


class VoiceContent(BoxLayout):
    """Play · waveform · length. Plays from the local copy once here."""

    def __init__(self, msg: dict, media: dict, screen, **kw):
        kw.setdefault("size_hint", (None, None))
        kw.setdefault("height", TOUCH)
        kw.setdefault("spacing", dp(8))
        super().__init__(**kw)
        self.msg, self.media, self.screen = msg, media, screen
        self.button = IconButton("play", tint=T.on_accent, bg=T.accent,
                                 icon_size=dp(18), label="Play voice message",
                                 pos_hint={"center_y": .5},
                                 on_release=lambda _w:
                                 screen.on_media_tap(self.msg))
        self.add_widget(self.button)
        self.wave = Waveform(media.get("wave", ""), size_hint_y=None,
                             height=dp(26), pos_hint={"center_y": .5},
                             on_seek=self._seek)
        self.add_widget(self.wave)
        dur = int(media.get("dur") or 0) // 1000
        self.length = Label(text=f"{dur // 60}:{dur % 60:02d}",
                            font_size=fs(13.5), color=C(T.text_3),
                            size_hint=(None, 1), width=dp(38))
        self.add_widget(self.length)
        # v11: while it plays, the length gives way to its speed, tapped to
        # go 1× → 1.5× → 2×.
        self.speed = SpeedChip(on_tap=self._next_speed, size_hint=(None, 1),
                               width=dp(38))
        self.refresh(msg)

    def _seek(self, fraction: float) -> None:
        path = self.msg.get("media_path")
        if not path or not Path(path).is_file():
            self.wave.set_progress(0)
            self.screen.on_media_tap(self.msg)        # fetch it first
            return
        self.screen.seek_voice(self.msg, fraction)

    def _next_speed(self) -> None:
        voice = self.screen.app.voice
        at = VOICE_SPEEDS.index(voice.speed) if voice.speed in VOICE_SPEEDS \
            else 0
        voice.set_speed(VOICE_SPEEDS[(at + 1) % len(VOICE_SPEEDS)])
        self.screen.refresh_voice_buttons()

    def natural_size(self, max_w: float) -> tuple:
        return min(max_w, dp(240)), TOUCH

    def refresh(self, msg: dict) -> None:
        self.msg = msg
        state = msg.get("media_state") or ""
        if state in ("expired", "failed"):
            self.button.set_icon("retry")
        elif state in ("pending", "downloading", "uploading", "requested"):
            self.button.set_icon("download")
        else:
            voice = self.screen.app.voice
            playing = voice.path == msg.get("media_path") and voice.playing
            self.button.set_icon("pause" if playing else "play")
            shown = self.speed if playing else self.length
            hidden = self.length if playing else self.speed
            if hidden.parent is self:
                self.remove_widget(hidden)
            if shown.parent is None:
                self.add_widget(shown)
            self.speed.text = speed_label(voice.speed)


class SpeedChip(ButtonBehavior, Label):
    """A voice note's speed, outlined, tapped to change (v11)."""

    def __init__(self, on_tap: Callable, **kw):
        kw.setdefault("font_size", fs(13))
        kw.setdefault("bold", True)
        super().__init__(color=C(T.accent), halign="center", valign="middle",
                         **kw)
        self.on_tap = on_tap
        with self.canvas.before:
            self._edge_col = Color(*C(T.accent))
            self._edge = SmoothLine(width=1.1)
        self.bind(pos=self._sync, size=self._sync)
        self.bind(on_release=lambda _w: self.on_tap())

    def _sync(self, *_a):
        w, h = min(self.width, dp(36)), dp(20)
        x, y = self.center_x - w / 2, self.center_y - h / 2
        self._edge.rounded_rectangle = (x, y, w, h, dp(10))
        self.text_size = self.size


#: Symbols below the emoji planes that are pictures by default; any other
#: (an arrow, a tick, ©) is one only when it asks to be (U+FE0F).
_EMOJI_BY_DEFAULT = set(
    "\u231a\u231b\u23e9\u23ea\u23eb\u23ec\u23f0\u23f3\u25fd\u25fe"
    "\u2614\u2615\u267f\u2693\u26a1\u26aa\u26ab\u26bd\u26be\u26c4"
    "\u26c5\u26ce\u26d4\u26ea\u26f2\u26f3\u26f5\u26fa\u26fd\u2705"
    "\u270a\u270b\u2728\u274c\u274e\u2753\u2754\u2755\u2757\u2795"
    "\u2796\u2797\u27b0\u27bf\u2b1b\u2b1c\u2b50\u2b55"
    + "".join(chr(c) for c in range(0x2648, 0x2654)))


def _emoji_base(text: str, i: int) -> bool:
    c = text[i]
    if 0x1F000 <= ord(c) <= 0x1FAFF:
        return True
    if c in _EMOJI_BY_DEFAULT:
        return True
    following = text[i + 1:i + 2]
    return 0x2000 <= ord(c) <= 0x2BFF and (
        following == "\ufe0f" or "\U0001F3FB" <= following <= "\U0001F3FF")


def emoji_only(text: str) -> int:
    """How many emoji a message is, if it is nothing else but one to
    three of them (spaces aside) — else 0 (v12). A flag, a keycap, a skin
    tone and a family joined with zero-width joiners each count as one."""
    s = "".join((text or "").split())
    if not s or len(s) > 48:
        return 0
    count = i = 0
    while i < len(s):
        c = s[i]
        if "\U0001F1E6" <= c <= "\U0001F1FF":                  # a flag
            if i + 1 < len(s) and "\U0001F1E6" <= s[i + 1] <= "\U0001F1FF":
                i += 2
            else:
                return 0
        elif c in "0123456789#*":                               # a keycap
            j = i + 1 + (s[i + 1:i + 2] == "\ufe0f")
            if s[j:j + 1] != "\u20e3":
                return 0
            i = j + 1
        elif _emoji_base(s, i):
            i += 1
            while i < len(s):
                c = s[i]
                if c == "\ufe0f" or "\U0001F3FB" <= c <= "\U0001F3FF" or \
                        "\U000E0020" <= c <= "\U000E007F":
                    i += 1                      # presentation, tone, tags
                elif c == "\u200d" and i + 1 < len(s) and \
                        _emoji_base(s, i + 1):
                    i += 2                      # joined to the next
                else:
                    break
        else:
            return 0
        count += 1
        if count > 3:
            return 0
    return count


#: How big a message of one, two or three emoji is drawn (v12).
BIG_EMOJI_SIZES = {1: 44, 2: 38, 3: 32}


def make_body(text: str, font_size, links: list = ()) -> Widget:
    """The message text: selectable on a desktop; on a phone a plain label
    (a long press there selects the whole message instead). Links in it
    are underlined, and a tap on one says where it leads (v11)."""
    if IS_MOBILE:
        return Label(text=link_markup(text, links, T.accent.lstrip("#"))
                     if links else text, markup=bool(links), color=C(T.text),
                     font_size=font_size, halign="left", valign="top",
                     size_hint=(None, None))
    body = SelectableText(text=text, font_size=font_size)
    if links:
        body.set_links(links)
    return body


class ChipFace(Widget):
    """A face inside a reaction (v13): the giver's disc, set in a ring of
    the reaction's own colour so that faces can overlap cleanly."""

    def __init__(self, seed: str, name: str, diameter: float, ring: str,
                 **kw):
        kw.setdefault("size_hint", (None, None))
        kw.setdefault("size", (diameter, diameter))
        super().__init__(**kw)
        with self.canvas:
            Color(*C(ring))
            self._ring = SmoothEllipse()
        self.disc = Avatar(seed, name, diameter=diameter - dp(3))
        self.add_widget(self.disc)
        self.bind(pos=self._sync, size=self._sync)

    def _sync(self, *_a):
        self._ring.pos, self._ring.size = self.pos, self.size
        self.disc.center = self.center


class ReactionChip(ButtonBehavior, Widget):
    """One reaction under a message: the emoji, and how many gave it — or,
    in a group, while FACES or fewer have, their faces, the latest first
    (v13). No outline (v13): a fill a shade off what it sits on (`under`),
    gold for yours. Tap it to take yours back (or to add it), hold it to
    see who gave it (v13)."""

    pop = NumericProperty(1.0)
    FACES, FACE, FACE_STEP = 3, dp(20), dp(13)

    def __init__(self, emoji: str, count: int, mine: bool, on_tap,
                 faces: Optional[list] = None, under: Optional[str] = None,
                 **kw):
        kw.setdefault("size_hint", (None, None))
        super().__init__(**kw)
        self.emoji, self.mine = emoji, mine
        faces = list(faces or [])
        if len(faces) > self.FACES:
            faces = []
        under = under or (T.surface if T.dark else T.bg)
        self.fill = mix(under, T.accent, .30) if mine else \
            mix(under, T.text, .09)
        self.label = Label(text=emoji if faces or count < 2 else
                           f"{emoji} {count}", font_size=fs(15),
                           color=C(T.text), size_hint=(None, None))
        self.label.texture_update()
        self.label.size = self.label.texture_size
        self.add_widget(self.label)
        self.faces = [ChipFace(seed, name, self.FACE, self.fill)
                      for seed, name in faces]
        pile = self.FACE + self.FACE_STEP * (len(faces) - 1) + dp(5) \
            if faces else 0
        self.size = (max(dp(40), self.label.texture_size[0] + pile + dp(18)),
                     max(dp(30), round(fs(15) * 1.7)))
        with self.canvas.before:
            PushMatrix()
            self._scale = Scale(1, 1, 1)
            self._ground_col = Color(*C(self.fill))
            self._ground = SmoothRoundedRectangle(radius=[dp(15)])
        with self.canvas.after:
            PopMatrix()
        for face in reversed(self.faces):       # the first on top
            self.add_widget(face)
        self.bind(pos=self._sync, size=self._sync, pop=self._sync,
                  state=lambda _w, s: setattr(self, "opacity",
                                              .7 if s == "down" else 1))
        self.bind(on_release=lambda _w: None if self._held() else
                  on_tap(emoji))

    def _held(self) -> bool:
        """Let go after a hold, which showed who gave it: no tap (v13)."""
        touch = self.last_touch
        return bool(touch is not None and touch.ud.get("fext_long_press"))

    def _sync(self, *_a):
        cx, cy = self.x + self.width / 2, self.y + self.height / 2
        self._scale.origin = (cx, cy)
        self._scale.x = self._scale.y = self.pop
        self._ground.pos, self._ground.size = self.pos, self.size
        self._ground.radius = [self.height / 2]
        if not self.faces:
            self.label.center = (cx, cy + dp(.5))
            return
        self.label.pos = (self.x + dp(9), cy - self.label.height / 2 + dp(.5))
        x = self.label.right + dp(5)
        for face in self.faces:
            face.pos = (x, cy - face.height / 2)
            x += self.FACE_STEP

    def animate_in(self) -> None:
        if not motion(1):
            return
        Animation.cancel_all(self, "pop")
        self.pop = 0.45
        Animation(pop=1.0, d=0.34, t="out_back").start(self)


class ReactionBar(Widget):
    """The reactions under one message, wrapping onto a second line when
    they must."""

    GAP = dp(6)

    def __init__(self, **kw):
        kw.setdefault("size_hint", (None, None))
        super().__init__(**kw)
        self.chips: list = []
        self.bind(pos=self._place)

    def set(self, reactions: list, me: str, on_tap,
            name_of: Optional[Callable] = None,
            under: Optional[str] = None) -> None:
        """Given `name_of` (in a group), the chips show who gave them as
        faces (v13); `under` is the colour they sit on."""
        for chip in self.chips:
            self.remove_widget(chip)
        groups: dict = {}
        for emoji, reactor, _at in reactions:
            groups.setdefault(emoji, []).append(reactor)
        self.chips = [ReactionChip(
            e, len(who), me in who, on_tap, under=under,
            faces=None if name_of is None else
            [(a, name_of(a)) for a in reversed(who)])
            for e, who in groups.items()]
        for chip in self.chips:
            self.add_widget(chip)

    def chip_for(self, emoji: str) -> Optional[ReactionChip]:
        return next((c for c in self.chips if c.emoji == emoji), None)

    def chip_at(self, wx: float, wy: float) -> Optional[ReactionChip]:
        """The chip at a point in window coordinates, if one is there."""
        return next((c for c in self.chips
                     if c.collide_point(*c.to_widget(wx, wy))), None)

    def layout_for(self, max_w: float) -> tuple:
        """Size for `max_w`: (width, height); 0 high when there are none."""
        if not self.chips:
            self.size = (0, 0)
            return 0, 0
        x = widest = 0.0
        rows = 1
        for chip in self.chips:
            if x and x + chip.width > max_w:
                rows += 1
                x = 0
            x += chip.width + self.GAP
            widest = max(widest, x - self.GAP)
        h = self.chips[0].height
        self.size = (widest, rows * h + (rows - 1) * self.GAP)
        self._max_w = max_w
        self._place()
        return self.size

    def _place(self, *_a):
        if not self.chips:
            return
        max_w = getattr(self, "_max_w", self.width)
        h = self.chips[0].height
        x, y = self.x, self.top - h
        for chip in self.chips:
            if x > self.x and x - self.x + chip.width > max_w:
                x, y = self.x, y - h - self.GAP
            chip.pos = (x, y)
            x += chip.width + self.GAP


class ReactorsSheet(Sheet):
    """Who reacted to a message, and with what (v13): held on one of its
    reactions, or right-clicked on a computer. A row for each, the newest
    first. With more than one kind, the reactions along the top, in their
    order under the message, choose which are listed. A tap on yours takes
    it back; on anyone else's, it opens what their disc beside a group's
    messages does."""

    def __init__(self, screen, msg: dict, only: str = "", **kw):
        words = message_text(msg) or {"image": "Photo", "voice":
                                      "Voice message"}.get(msg.get("kind"),
                                                           "")
        quote = f"\u201c{single_line_text(words, 48)}\u201d" if words else ""
        super().__init__("Reactions", subtitle=quote, **kw)
        self.screen, self.msg, self.only = screen, msg, only
        self.card.padding = [0, dp(8), 0, dp(14)]
        self.title_label.padding = [dp(22), 0]
        if self.subtitle_label is not None:
            self.subtitle_label.padding = [dp(22), 0]
        self.kinds_row = BoxLayout(size_hint=(None, 1), spacing=dp(6),
                                   padding=[dp(20), 0])
        self.kinds_row.bind(minimum_width=self.kinds_row.setter("width"))
        self.kinds = ScrollView(size_hint_y=None, do_scroll_y=False,
                                bar_width=0, height=max(dp(30),
                                                        round(fs(15) * 1.7)))
        self.kinds.add_widget(self.kinds_row)
        self.rows: list = []
        self.render()

    def _reactions(self) -> list:
        store, cid = self.screen.app.store, self.msg.get("client_msg_id")
        if store is None or not cid:
            return []
        peer = self.msg.get("peer") or self.screen.peer
        return store.reactions_for(peer, [cid]).get(cid, [])

    def render(self) -> None:
        reactions = self._reactions()
        if not reactions:
            self.dismiss()
            return
        counts: dict = {}
        for emoji, _who, _at in reactions:
            counts[emoji] = counts.get(emoji, 0) + 1
        if self.only not in counts:
            self.only = ""
        self.kinds_row.clear_widgets()
        if len(counts) > 1:
            card = T.surface if T.dark else T.bg
            self.kinds_row.add_widget(ReactionChip(
                "All", len(reactions), not self.only,
                lambda _e: self._choose(""), under=card))
            for emoji, count in counts.items():
                self.kinds_row.add_widget(ReactionChip(
                    emoji, count, emoji == self.only,
                    lambda _e, e=emoji: self._choose(e), under=card))
            if self.kinds.parent is None:
                self.card.add_widget(self.kinds, index=1)
        elif self.kinds.parent is not None:
            self.card.remove_widget(self.kinds)
        app = self.screen.app
        me = app.keys.address
        self.rows = []
        for emoji, who, at in sorted(reactions, key=lambda r: r[2],
                                     reverse=True):
            if self.only and emoji != self.only:
                continue
            mine = who == me
            name = self.screen.author_name(who)
            glyph = Label(text=emoji, font_size=fs(24), color=C(T.text),
                          size_hint=(None, None), size=(dp(40), dp(40)))
            row = PersonRow(
                who, name, "Tap to take it back" if mine else pretty_day(at),
                on_tap=(lambda e=emoji: self._take_back(e)) if mine else
                (lambda a=who: self._person(a)), trailing=glyph,
                initial_from=app.keys.username if mine else name)
            row.emoji, row.reactor = emoji, who
            self.rows.append(row)
        self.body.clear_widgets()
        self.body.add_widget(rows_card(self.rows, inset=dp(76)))
        self._fit()

    def _choose(self, emoji: str) -> None:
        self.only = emoji
        self.render()

    def _take_back(self, emoji: str) -> None:
        self.screen.app.react(self.msg["id"], emoji)
        self.render()

    def _person(self, address: str) -> None:
        self.dismiss()
        Clock.schedule_once(lambda _dt: self.screen.on_face_tap(address),
                            0.05)


class MessageBubble(BoxLayout):
    """One message: who wrote it (in a group), a 'Forwarded' note, the
    quoted message it answers, a photo or voice note, the text, its
    reactions, and the time with the ticks.

    Yours sit right on a warmer ground; theirs left on the page's surface.
    Touches belong to the enclosing BubbleRow (tap, long-press, selection);
    this class only lays out.
    """

    def __init__(self, msg: dict, ticks_enabled: bool, screen, **kw):
        kw.setdefault("orientation", "vertical")
        kw.setdefault("size_hint", (None, None))
        kw.setdefault("padding", [dp(12), dp(8), dp(12), dp(7)])
        kw.setdefault("spacing", dp(5))
        super().__init__(**kw)
        self.msg, self.screen = msg, screen
        self._last_width = 0.0
        self._text_w = self._text_h = 0.0
        self._body_floor = 0.0
        outgoing = msg["direction"] == "out"
        self.outgoing = outgoing
        ext = message_ext(msg)
        # v12: a message of nothing but one to three emoji is drawn large,
        # on the page itself, without a bubble.
        self.big = 0
        if msg.get("kind", "text") in ("text", None) and not (
                ext.get("reply") or ext.get("fwd") or ext.get("lp")):
            self.big = emoji_only(msg.get("body") or "")
        # v12: a run of messages from one person reads as one: the corners
        # on their side close up where a bubble meets the next, and only
        # the last keeps the tail (the near-square corner at the bottom).
        self.joined_above = self.joined_below = False
        self._ground = None
        if not self.big:
            with self.canvas.before:
                Color(*C(T.own if outgoing else T.peer))
                self._ground = SmoothRoundedRectangle(pos=self.pos,
                                                      size=self.size)
        self._outline = None
        if not outgoing and not T.dark and not self.big:
            # On the light page theirs are white cards with a hairline;
            # yours keep the warm ground.
            with self.canvas.after:
                Color(*C(T.rule_strong))
                self._outline = SmoothLine(width=max(1.0, dp(1) / 2.0))
        self.bind(pos=self._sync_ground, size=self._sync_ground)
        if self.big:
            self.padding = [dp(2), dp(2), dp(2), dp(4)]

        self.author = None
        author = msg.get("author")
        if not outgoing and screen.kind == "group" and author:
            self.author = CapsLabel(screen.author_name(author), size=10.5,
                                    color=ink_color(author), tracking=0.14,
                                    size_hint=(None, None))
            self.add_widget(self.author)
        self._author_index = None

        self.fwd = None
        if ext.get("fwd"):
            self.fwd = Label(text="Forwarded", italic=True, font_size=fs(14),
                             color=C(T.text_3), halign="left",
                             size_hint=(None, None), height=line_height(14))
            self.fwd.bind(size=lambda w, v: setattr(w, "text_size", v))
            self.add_widget(self.fwd)

        self.quote = None
        reply = ext.get("reply")
        if isinstance(reply, dict):
            who = screen.author_name(reply.get("from"), outgoing)
            snippet = reply.get("snip") or {"image": "Photo",
                                            "voice": "Voice message"}.get(
                reply.get("kind"), "Message")
            self.quote = QuoteBlock(who, snippet, outgoing,
                                    on_tap=lambda c=reply.get("cid"):
                                    screen.jump_to_cid(c))
            self.add_widget(self.quote)

        self.media = None
        media = ext.get("media")
        if msg.get("kind") == "image" and isinstance(media, dict):
            self.media = ImageContent(msg, media, screen)
        elif msg.get("kind") == "voice" and isinstance(media, dict):
            self.media = VoiceContent(msg, media, screen)
        if self.media is not None:
            self.add_widget(self.media)

        text = self._display_text(msg, media)
        self.links = link_spans(text) if text else []
        size = fs(BIG_EMOJI_SIZES[self.big]) if self.big else fs(17)
        self.body = make_body(text, size, self.links) if text else None
        if self.body is not None:
            if isinstance(self.body, SelectableText):
                self.body.bind(minimum_height=self._body_min_height)
            self.add_widget(self.body)

        # v11: a link's preview, as its sender's phone found it. Shown when
        # previews are on here — and on your own messages, since it is what
        # they were sent.
        self.card = None
        preview = ext.get("lp")
        if isinstance(preview, dict) and preview.get("u") and \
                preview.get("t") and (outgoing or link_previews_enabled()):
            self.card = LinkCard(preview, outgoing,
                                 on_tap=lambda u=preview["u"]:
                                 screen.on_link_tap(u))
            self.add_widget(self.card)

        self.reactions = ReactionBar()
        self._react_row = AnchorLayout(anchor_x="left", anchor_y="top",
                                       size_hint_y=None, height=0)
        self._react_row.add_widget(self.reactions)
        self._set_reactions(msg)

        self.meta = Label(text=self._stamp_text(msg), markup=True,
                          font_size=fs(12.5), color=C(T.text_3),
                          halign="right", valign="middle",
                          size_hint=(None, None), height=line_height(12.5))
        count, tint, clock = self._tick_state(msg, outgoing, ticks_enabled)
        if screen.kind == "self":
            count, clock = 0, False      # nothing is sent, so nothing to tick
        self.ticks = TickMarks(count=count, tint=tint, clock=clock,
                               pos_hint={"center_y": .5})
        self.star = Widget(size_hint=(None, None),
                           size=(dp(12), line_height(12.5)))
        self.star.bind(pos=self._draw_star, size=self._draw_star)
        self.meta_box = BoxLayout(orientation="horizontal", spacing=dp(5),
                                  size_hint=(None, None),
                                  height=line_height(12.5))
        self.meta_box.add_widget(self.star)
        self.meta_box.add_widget(self.meta)
        self.meta_box.add_widget(self.ticks)
        meta_row = AnchorLayout(anchor_x="right", size_hint_y=None,
                                height=line_height(12.5))
        meta_row.add_widget(self.meta_box)
        self.add_widget(meta_row)
        self.meta_row = meta_row
        if self.big:
            # The time sits on a small pill of the page's surface, so it
            # reads on any ground.
            self.meta_box.padding = [dp(7), 0, dp(7), 0]
            paint_round(self.meta_box, T.surface, radius=dp(8))
        self._draw_star()

    # ---- v12: runs of messages ----------------------------------------------------
    def _radii(self) -> list:
        """[top-left, top-right, bottom-right, bottom-left]: round, with
        the sender's side closed up where the run goes on, and the tail
        (near square) at the bottom of the last."""
        round_, joint, tail = dp(10), dp(4), dp(3)
        top = joint if self.joined_above else round_
        bottom = joint if self.joined_below else tail
        if self.outgoing:
            return [round_, top, bottom, round_]
        return [top, round_, round_, bottom]

    def _sync_ground(self, *_a) -> None:
        cap = max(0.0, min(self.width, self.height) / 2.0)
        radii = [min(r, cap) for r in self._radii()]
        if self._ground is not None:
            self._ground.pos, self._ground.size = self.pos, self.size
            self._ground.radius = radii
        if self._outline is not None:
            self._outline.rounded_rectangle = (
                self.x + .5, self.y + .5, self.width - 1, self.height - 1,
                *radii)

    def meta_key(self) -> tuple:
        """What the time line says: within a run, a line that says the
        same as the next one's is not repeated."""
        return (self.meta.text, self.ticks._count, self.ticks._tint,
                bool(self.msg.get("starred")))

    def set_meta_shown(self, shown: bool) -> None:
        if shown == (self.meta_row.parent is self):
            return
        if shown:
            self.add_widget(self.meta_row, index=0)
        else:
            self.remove_widget(self.meta_row)
        if self._last_width:
            self.layout_for(self._last_width)

    def set_joins(self, above: bool, below: bool) -> None:
        """Whether the message above, and below, are the same person's,
        moments apart. In a group only the first of a run names them."""
        if (above, below) == (self.joined_above, self.joined_below):
            return
        relabel = above != self.joined_above
        self.joined_above, self.joined_below = above, below
        if relabel and self.author is not None:
            if above and self.author.parent is self:
                self.remove_widget(self.author)
            elif not above and self.author.parent is None:
                self.add_widget(self.author, index=len(self.children))
            if self._last_width:
                self.layout_for(self._last_width)
        self._sync_ground()

    # ---- content -------------------------------------------------------------
    @staticmethod
    def _display_text(msg: dict, media) -> str:
        """A photo shows its caption, a voice note nothing — their readable
        `body` is for older clients, previews and exports."""
        if msg.get("kind") == "image" and isinstance(media, dict):
            return media.get("cap", "")
        if msg.get("kind") == "voice" and isinstance(media, dict):
            return ""
        return msg["body"]

    def _set_reactions(self, msg: dict) -> None:
        reactions = msg.get("reactions") or []
        screen, keys = self.screen, self.screen.app.keys
        name_of = None
        if screen.kind == "group":              # who gave them, as faces
            name_of = (lambda a: keys.username if a == keys.address
                       else screen.author_name(a))
        self.reactions.set(reactions, keys.address,
                           lambda e, m=msg: screen.on_reaction_tap(m, e),
                           name_of=name_of, under=T.bg if self.big else
                           T.own if self.outgoing else T.peer)
        row = self._react_row
        if reactions and row.parent is None:
            # Just above the time: the meta row, when present, is last.
            shown = getattr(self, "meta_row", None) is not None and \
                self.meta_row.parent is self
            self.add_widget(row, index=1 if shown else 0)
        elif not reactions and row.parent is not None:
            self.remove_widget(row)

    def _draw_star(self, *_a):
        self.star.canvas.clear()
        if not self.msg.get("starred"):
            self.star.width = 0
            return
        self.star.width = dp(12)
        with self.star.canvas:
            draw_icon("star_filled", (self.star.x + self.star.width / 2), (self.star.y + self.star.height / 2),
                      dp(11), C(T.accent))

    def _stamp_text(self, msg: dict) -> str:
        """The time, plus a nudge on incoming messages still unread (only
        ever left so when auto-read is off), or (v14) on one of yours the
        outbox gave up on after a day."""
        stamp = pretty_time(msg["created_at"])
        if msg["direction"] == "in" and not msg["read"]:
            return "[i][color=%s]tap to mark read[/color][/i]   %s" % (
                T.accent.lstrip("#"), stamp)
        if self.screen.kind != "self" and waits_for_tap(msg) and \
                not message_ext(msg).get("media"):
            return "[color=%s]Not sent · tap to try again[/color]   %s" % (
                T.alert.lstrip("#"), stamp)
        return stamp

    @staticmethod
    def _tick_state(msg: dict, outgoing: bool, ticks_enabled: bool) -> tuple:
        """(ticks, colour, clock), from tick_look. Outgoing ticks come from
        the relay's receipts (in a group: the slowest member's); incoming
        ones from what this phone knows — it holds the message (2), and
        whether you read it (3). Either side turning ticks off caps both
        at one."""
        if outgoing:
            status = msg["status"]
        else:
            status = 3 if msg["read"] else 2
        if not ticks_enabled:
            status = min(status, 1)
        return tick_look(status)

    def update(self, msg: dict, ticks_enabled: bool) -> None:
        """Repaint in place after a status/read/star/media/reaction change."""
        outgoing = msg["direction"] == "out"
        self.msg = msg
        self.meta.text = self._stamp_text(msg)
        if self.screen.kind != "self":
            self.ticks.set_state(*self._tick_state(msg, outgoing,
                                                   ticks_enabled))
        if self.media is not None:
            media = message_ext(msg).get("media")
            if isinstance(media, dict):
                self.media.media = media
            self.media.refresh(msg)
        before = {c.emoji: c.label.text for c in self.reactions.chips}
        self._set_reactions(msg)
        self._draw_star()
        if self._last_width:
            self.layout_for(self._last_width)
        pending = self.screen.take_pending_pop(msg.get("client_msg_id"))
        for chip in self.reactions.chips:
            if chip.emoji == pending or (pending is None and
                                         before.get(chip.emoji) !=
                                         chip.label.text and
                                         chip.emoji not in before):
                chip.animate_in()

    def _body_min_height(self, _w, value: float) -> None:
        """Safety net for desktop's selectable text: if, AT ITS FINAL WIDTH,
        it wants more room than measured, grow rather than clip. Readings
        from before then (a TextInput starts 100px wide) are ignored."""
        if self.body is None or not self._last_width or \
                self.body.width < self._text_w:
            return
        floor = value if value > self._text_h + 0.5 else 0.0
        if abs(floor - self._body_floor) > 0.5:
            self._body_floor = floor
            self.layout_for(self._last_width)

    def layout_for(self, available: float) -> None:
        """Size every part, then the bubble to fit them: the widest part
        decides, capped at 80% of the row."""
        self._last_width = available
        max_w = max(dp(150), available * 0.80 - dp(24))
        parts = []
        widest = dp(56)
        if self.author is not None and self.author.parent is self:
            self.author.size = (min(max_w, self.author.natural_width),
                                self.author.height)
            widest = max(widest, self.author.width)
            parts.append(self.author.height)
        if self.media is not None:
            mw, mh = self.media.natural_size(max_w)
            self.media.size = (mw, mh)
            widest = max(widest, mw)
            parts.append(mh)
        if self.body is not None:
            wrap = self.media.width if isinstance(self.media,
                                                  ImageContent) else max_w
            if isinstance(self.body, SelectableText):
                text_w, text_h = measure_selectable(self.body.text,
                                                    self.body.font_size, wrap)
            else:
                text_w, text_h = measure_text(self.body.text,
                                              self.body.font_size, wrap,
                                              markup=self.body.markup)
            self._text_w, self._text_h = text_w, text_h
            if isinstance(self.body, SelectableText):
                self.body.width = text_w + dp(2)
                self.body.height = max(text_h, self._body_floor)
                self.body._unscroll()
            else:
                self.body.width = text_w
                self.body.text_size = (text_w + 0.5, None)
                self.body.height = text_h
            widest = max(widest, self.body.width)
            parts.append(self.body.height)
        if self.quote is not None:
            widest = max(widest, min(max_w, self.quote.natural_width()))
        if self.card is not None:
            widest = max(widest, self.card.natural_width(max_w))
        if self.fwd is not None:
            widest = max(widest, measure_text("Forwarded", fs(14), dp(300),
                                              italic=True)[0])
        rw, rh = self.reactions.layout_for(max_w)
        self._react_row.height = rh
        widest = max(widest, rw)
        self.meta.texture_update()
        self.meta.size = (self.meta.texture_size[0], line_height(12.5))
        meta_w = self.meta.width + self.ticks.width + self.star.width
        meta_w += dp(5) * (1 + (1 if self.ticks.width else 0))
        meta_w += self.meta_box.padding[0] + self.meta_box.padding[2]
        self.meta_box.width = meta_w
        meta_shown = self.meta_row.parent is self
        if meta_shown:
            widest = max(widest, meta_w)
        if self.quote is not None:
            self.quote.width = widest
            parts.append(self.quote.height)
        if self.fwd is not None:
            self.fwd.width = widest
            parts.append(self.fwd.height)
        if self.card is not None:
            parts.append(self.card.layout_for(widest))
        if self._react_row.parent is not None:
            parts.append(rh)
        if meta_shown:
            parts.append(line_height(12.5))         # the meta row
        pad_l, pad_t, pad_r, pad_b = self.padding
        self.width = widest + pad_l + pad_r
        self.height = (sum(parts) + self.spacing * (len(self.children) - 1)
                       + pad_t + pad_b)

    def link_at(self, wx: float, wy: float) -> Optional[str]:
        """The link in the text under window point (wx, wy), if any."""
        body = self.body
        if body is None or not self.links or not hits(body, wx, wy):
            return None
        x, y = body.parent.to_widget(wx, wy)
        if isinstance(body, SelectableText):
            index = body.index_at(x, y)
            for start, end, url in self.links:
                if start <= index < end:
                    return url
            return None
        # A label's refs are boxes on its texture, top down.
        tw, th = body.texture_size
        tx = x - (body.center_x - tw / 2.0)
        ty = th - (y - (body.center_y - th / 2.0))
        slack = dp(4)                    # a fingertip is wider than a letter
        for ref, zones in body.refs.items():
            for x0, y0, x1, y1 in zones:
                if x0 - slack <= tx <= x1 + slack and \
                        y0 - slack <= ty <= y1 + slack:
                    return self.links[int(ref)][2]
        return None


class BubbleRow(AnchorLayout):
    """A full-width row holding one bubble, and the owner of its touches.

    Long-press (or right-click) selects the message — the app bar switches
    to its actions and the reaction strip rises over it; while anything is
    selected a tap toggles a message in or out instead.
    """

    LONG_PRESS = 0.42                     # seconds
    shift = NumericProperty(0.0)          # v11: slid left, to reply
    #: In a group, theirs share a gutter at the left, where the last
    #: message of each run has its author's disc beside it (v12).
    FACE, FACE_LEFT, FACE_GAP = dp(30), dp(10), dp(6)

    def __init__(self, bubble: MessageBubble, outgoing: bool, screen, **kw):
        kw.setdefault("size_hint_y", None)
        kw.setdefault("height", dp(48))
        kw.setdefault("padding", [dp(12), dp(3), dp(12), dp(3)])
        super().__init__(anchor_x="right" if outgoing else "left",
                         anchor_y="center", **kw)
        self.bubble, self.screen = bubble, screen
        self.msg_id = bubble.msg["id"]
        self.author = bubble.msg.get("author") if not outgoing and \
            getattr(screen, "kind", "") == "group" else None
        self.face = None
        self.face_room = (self.FACE_LEFT + self.FACE + self.FACE_GAP - dp(12)
                          if self.author else 0.0)
        with self.canvas.before:
            self._tint = Color(*T.select)
            self._wash = Rectangle()
        self._tint.a = 0
        self._cue = Canvas()
        self.canvas.after.add(self._cue)
        self.bind(pos=self._sync, size=self._sync,
                  shift=lambda *_a: self._trigger_layout())
        self.add_widget(bubble)
        bubble.bind(height=lambda *_a: self._fit_height())
        self.bind(width=lambda _w, v: bubble.layout_for(v - self.face_room))
        self._press = None
        self._show_face(not bubble.joined_below)

    #: The gap above and below a bubble (v12): wider between runs than it
    #: was (3), narrow inside one, so a run reads as one.
    GAP, RUN_GAP = dp(4), dp(1)

    def _fit_height(self) -> None:
        top = self.RUN_GAP if self.bubble.joined_above else self.GAP
        bottom = self.RUN_GAP if self.bubble.joined_below else self.GAP
        self.padding = [dp(12) + self.face_room, top, dp(12), bottom]
        self.height = self.bubble.height + top + bottom

    def set_joins(self, above: bool, below: bool) -> None:
        self.bubble.set_joins(above, below)
        self._fit_height()
        self._show_face(not below)

    def _show_face(self, show: bool) -> None:
        """The author's disc beside this message: only the last of a run
        has it, so a new message from them below takes it over."""
        if not self.author:
            return
        if show and self.face is None:
            self.face = Avatar(self.author,
                               self.screen.author_name(self.author),
                               diameter=self.FACE)
        if self.face is None:
            return
        if show and self.face.parent is None:
            self.add_widget(self.face)
        elif not show and self.face.parent is self:
            self.remove_widget(self.face)

    def face_at(self, x: float, y: float) -> bool:
        """Whether (x, y) — the row's own coordinates — falls on the disc,
        or near enough beside it to mean it."""
        face = self.face
        return face is not None and face.parent is self and \
            self.x <= x < self.bubble.x and \
            face.y - dp(6) <= y <= face.top + dp(6)

    def _sync(self, *_a):
        self._wash.pos, self._wash.size = self.pos, self.size

    def do_layout(self, *args):
        super().do_layout(*args)
        if self.shift:
            self.bubble.x += self.shift
        if self.face is not None and self.face.parent is self:
            # Level with the bubble's foot, where the run ends.
            self.face.pos = (self.x + self.FACE_LEFT + self.shift,
                             self.bubble.y)
        self._draw_cue()

    def _draw_cue(self) -> None:
        """The reply mark that comes in at the right as the message slides
        left: faint, then whole once letting go would reply."""
        self._cue.clear()
        if self.shift >= 0:
            return
        reach = min(1.0, -self.shift / SWIPE_REPLY)
        cx, cy = self.right - dp(30), self.center_y
        r = dp(15) * (0.6 + 0.4 * reach)
        with self._cue:
            Color(*(C(T.accent)[:3] + [0.12 + 0.3 * reach]))
            Ellipse(pos=(cx - r, cy - r), size=(2 * r, 2 * r))
            draw_icon("reply", cx, cy, dp(16), C(T.accent)[:3] + [reach])

    def settle_shift(self) -> None:
        if not self.shift:
            return
        if motion(1):
            Animation(shift=0.0, d=0.16, t="out_back").start(self)
        else:
            self.shift = 0.0

    def set_selected(self, selected: bool) -> None:
        self._tint.a = T.select[3] if selected else 0

    def on_touch_down(self, touch):
        if not self.collide_point(*touch.pos) or touch.is_mouse_scrolling \
                or swiped(touch):
            return super().on_touch_down(touch)
        if self.screen.selecting:
            self.screen.toggle_selection(self.msg_id)
            return True
        if getattr(touch, "button", "left") == "right":
            if not self._reactors_at(touch.pos):
                self.screen.start_selection(self.msg_id)
            return True
        touch.grab(self)
        touch.ud["fext_row"] = True
        self._press = (touch.uid, touch.pos, Clock.schedule_once(
            lambda _dt: self._long_press(touch), self.LONG_PRESS))
        super().on_touch_down(touch)       # children: quote, play, chips
        return True

    def _long_press(self, touch):
        if self._press and self._press[0] == touch.uid and not swiped(touch):
            pos, self._press = self._press[1], None
            touch.ud["fext_long_press"] = True
            if not self._reactors_at(pos):
                self.screen.start_selection(self.msg_id)

    def _reactors_at(self, pos) -> bool:
        """Held, or right-clicked, on one of its reactions: who gave them
        (v13), in place of selecting the message."""
        chip = self.bubble.reactions.chip_at(*self.to_window(*pos))
        if chip is None:
            return False
        self.screen.show_reactors(self.msg_id, chip.emoji)
        return True

    def on_touch_move(self, touch):
        if self._press and self._press[0] == touch.uid:
            ox, oy = self._press[1]
            if abs(touch.x - ox) > dp(10) or abs(touch.y - oy) > dp(10):
                self._press[2].cancel()
                self._press = None
        return super().on_touch_move(touch)

    def on_touch_up(self, touch):
        if touch.grab_current is self:
            touch.ungrab(self)
            pending, self._press = self._press, None
            if pending:
                pending[2].cancel()
                if touch.ud.get("fext_long_press") or swiped(touch):
                    pass
                elif self.face_at(*touch.pos):
                    self.screen.on_face_tap(self.author)
                else:
                    self.screen.on_bubble_tap(self.msg_id, touch)
            return True
        return super().on_touch_up(touch)


class EventRow(BoxLayout):
    """A line in the margin of a group's history: who joined, who left,
    what it is now called. Italic, centred, not a message."""

    def __init__(self, msg: dict, **kw):
        kw.setdefault("size_hint_y", None)
        kw.setdefault("padding", [dp(40), dp(6), dp(40), dp(6)])
        super().__init__(**kw)
        self.msg = msg
        self.label = InfoLabel(msg["body"], color=T.text_3, italic=True,
                               font_size=fs(15), halign="center")
        self.add_widget(self.label)
        self.label.bind(height=lambda _w, v: setattr(self, "height",
                                                     v + dp(12)))


class DayDivider(BoxLayout):
    """A date set in capitals between hairlines — the rhythm of days."""

    def __init__(self, text: str, **kw):
        kw.setdefault("size_hint_y", None)
        kw.setdefault("height", dp(46))
        kw.setdefault("padding", [dp(28), 0])
        kw.setdefault("spacing", dp(12))
        super().__init__(**kw)
        self.day_text = text
        self.add_widget(Rule(pos_hint={"center_y": .5}))
        caps = CapsLabel(text, size=10.5, color=T.text_3, tracking=0.18,
                         halign="center", size_hint=(None, None),
                         pos_hint={"center_y": .5})
        caps.width = caps.natural_width + dp(2)
        self.add_widget(caps)
        self.add_widget(Rule(pos_hint={"center_y": .5}))


class DayFloat(Widget):
    """The day of the messages at the top of the view, floating over them
    while you scroll (v12), so you know where you are in a long chat."""

    def __init__(self, **kw):
        kw.setdefault("size_hint", (None, None))
        kw.setdefault("size", (dp(80), dp(28)))
        super().__init__(**kw)
        self.caps = CapsLabel("", size=10.5, color=T.text_2, tracking=0.18,
                              halign="center", size_hint=(None, None))
        self.add_widget(self.caps)
        self.opacity = 0
        self.shown = False
        self.bind(pos=self._sync, size=self._sync)

    def _sync(self, *_a) -> None:
        self.canvas.before.clear()
        r = self.height / 2
        with self.canvas.before:
            Color(*C(T.surface_hi))
            SmoothRoundedRectangle(pos=self.pos, size=self.size, radius=[r])
            Color(*C(T.rule_strong))
            SmoothLine(rounded_rectangle=(self.x + .5, self.y + .5,
                                          self.width - 1, self.height - 1,
                                          r - .5), width=1.0)
        self.caps.size = (self.caps.natural_width + dp(2), self.height)
        self.caps.center = self.center

    def show(self, text: str) -> None:
        if text.upper() != self.caps.text:
            self.caps.text = text
            self.width = self.caps.natural_width + dp(30)
            if self.parent is not None:
                # A float layout places a child again when its hints
                # change, not its size: keep it centred.
                self.center_x = self.parent.center_x
            self._sync()
        if not self.shown:
            self.shown = True
            Animation.cancel_all(self, "opacity")
            if motion(1):
                Animation(opacity=1, d=0.12).start(self)
            else:
                self.opacity = 1

    def hide(self, *_a) -> None:
        if not self.shown:
            return
        self.shown = False
        Animation.cancel_all(self, "opacity")
        if motion(1):
            Animation(opacity=0, d=0.25).start(self)
        else:
            self.opacity = 0


class NewMessagesLine(BoxLayout):
    """Where what you have not read yet begins (v12): the count in gold
    capitals between gold hairlines. The chat opens here."""

    def __init__(self, count: int, **kw):
        kw.setdefault("size_hint_y", None)
        kw.setdefault("height", dp(40))
        kw.setdefault("padding", [dp(16), 0])
        kw.setdefault("spacing", dp(12))
        super().__init__(**kw)
        self.add_widget(Rule(color=T.accent, pos_hint={"center_y": .5}))
        text = f"{count} new message{'s' if count != 1 else ''}" \
            if count else "New messages"
        caps = CapsLabel(text, size=10.5, color=T.accent, tracking=0.18,
                         halign="center", size_hint=(None, None),
                         pos_hint={"center_y": .5})
        caps.width = caps.natural_width + dp(2)
        self.add_widget(caps)
        self.add_widget(Rule(color=T.accent, pos_hint={"center_y": .5}))


class JumpToBottomButton(Concealable, ButtonBehavior, Widget):
    """'Back to the latest' — appears when scrolled away from the bottom,
    with a count of what arrived meanwhile (the view is never yanked)."""

    def __init__(self, on_tap=None, **kw):
        kw.setdefault("size_hint", (None, None))
        kw.setdefault("size", (TOUCH, TOUCH))
        super().__init__(**kw)
        self._count = 0
        self.opacity = 0
        self.conceal(True)
        self.bind(pos=self._sync, size=self._sync, state=self._sync)
        if on_tap is not None:
            self.bind(on_release=lambda _w: on_tap())
        self._badge = Label(text="", bold=True, font_size=fs(12),
                            color=C(T.on_alert), size_hint=(None, None),
                            size=(dp(20), dp(20)), opacity=0)
        self.add_widget(self._badge)
        self._sync()

    def _sync(self, *_a):
        self.canvas.before.clear()
        d = dp(42)
        cx, cy = self.x + self.width / 2, self.y + self.height / 2
        with self.canvas.before:
            Color(*C(T.press if self.state == "down" else T.surface_hi))
            SmoothEllipse(pos=(cx - d / 2, cy - d / 2), size=(d, d))
            Color(*C(T.rule_strong))
            SmoothLine(circle=(cx, cy, d / 2 - .5), width=1.0)
            draw_icon("down", cx, cy, d * .5, C(T.text_2), width=dp(.9))
            if self._count > 0:
                Color(*C(T.alert))
                SmoothEllipse(pos=(cx + dp(6), cy + dp(6)),
                              size=(dp(20), dp(20)))
        self._badge.center = (cx + dp(16), cy + dp(16))

    def set_visible(self, visible: bool) -> None:
        target = 1.0 if visible else 0.0
        self.conceal(not visible)
        if abs(self.opacity - target) < 0.01:
            return
        Animation.cancel_all(self, "opacity")
        if motion(1):
            Animation(opacity=target, d=0.15).start(self)
        else:
            self.opacity = target

    def set_count(self, count: int) -> None:
        count = max(0, int(count))
        if count == self._count:
            return
        self._count = count
        self._badge.text = str(min(count, 99)) if count else ""
        self._badge.opacity = 1 if count else 0
        self._sync()


