RECENT_EMOJI_MAX = 24


class EmojiKey(ButtonBehavior, Label):
    def __init__(self, emoji: str, on_pick, **kw):
        if "size" in kw:
            kw.setdefault("size_hint", (None, None))
        super().__init__(text=emoji, font_size=sp(25), color=C(T.text),
                         **kw)
        with self.canvas.before:
            self._press = Color(0, 0, 0, 0)
            self._disc = SmoothEllipse()
        self.bind(pos=self._sync, size=self._sync,
                  state=lambda _w, s: setattr(
                      self._press, "rgba", C(T.press) if s == "down"
                      else (0, 0, 0, 0)),
                  on_release=lambda _w: on_pick(emoji))

    def _sync(self, *_a):
        d = dp(42)
        self._disc.pos = ((self.x + self.width / 2) - d / 2, (self.y + self.height / 2) - d / 2)
        self._disc.size = (d, d)


class EmojiPanel(Concealable, BoxLayout):
    """Emoji, by kind, where the keyboard was: capitals tabs over a grid.
    Picks go into the message being written, or — opened from the
    reaction strip — become a reaction."""

    HEIGHT = dp(292)

    def __init__(self, on_pick: Callable[[str], None], **kw):
        kw.setdefault("orientation", "vertical")
        kw.setdefault("size_hint_y", None)
        kw.setdefault("height", 0)
        super().__init__(**kw)
        self.on_pick = on_pick
        self.opacity = 0
        self.conceal(True)
        paint_round(self, T.surface, radius=0)
        hairline(self, "top")
        recent = [e for e in load_prefs().get("recent_emoji", [])
                  if isinstance(e, str) and sanitize_emoji(e)]
        self._recent = recent[:RECENT_EMOJI_MAX]
        options = ([("Recent", "Recent")] if self._recent else []) + \
            [(name, name) for name, _set in EMOJI_SETS]
        self._sets = dict(EMOJI_SETS)
        tab_scroll = ScrollView(size_hint_y=None, height=TOUCH,
                                do_scroll_y=False, bar_width=0)
        self.tabs = Segmented(options, options[0][0], self._show,
                              size_hint_x=None)
        self.tabs.width = max(dp(84) * len(options), Window.width)
        tab_scroll.add_widget(self.tabs)
        self.add_widget(tab_scroll)
        self.grid_scroll = ScrollView(do_scroll_x=False, bar_width=dp(3))
        self.add_widget(self.grid_scroll)
        self._grids: dict = {}
        self._show(options[0][0])

    def _show(self, name: str) -> None:
        grid = self._grids.get(name)
        if grid is None or name == "Recent":
            items = self._recent if name == "Recent" else self._sets[name]
            grid = GridLayout(cols=7, size_hint=(1, None),
                              padding=[dp(4), dp(4)],
                              row_default_height=TOUCH,
                              row_force_default=True)
            grid.bind(minimum_height=grid.setter("height"),
                      width=self._reflow)
            for emoji in items:
                grid.add_widget(EmojiKey(emoji, self._pick))
            self._grids[name] = grid
        self.grid_scroll.clear_widgets()
        if grid.parent is not None:
            grid.parent.remove_widget(grid)
        self.grid_scroll.add_widget(grid)
        self._reflow(grid, grid.width)
        self.grid_scroll.scroll_y = 1

    @staticmethod
    def _reflow(grid, width) -> None:
        """As many 48dp keys a row as fit, the slack spread between them."""
        cols = max(5, int((width - dp(8)) / TOUCH))
        if grid.cols != cols:
            grid.cols = cols

    def _pick(self, emoji: str) -> None:
        recent = [emoji] + [e for e in self._recent if e != emoji]
        self._recent = recent[:RECENT_EMOJI_MAX]
        save_pref("recent_emoji", self._recent)
        self.on_pick(emoji)

    def set_open(self, on: bool) -> None:
        self.height = self.HEIGHT if on else 0
        self.opacity = 1 if on else 0
        self.conceal(not on)

    @property
    def is_open(self) -> bool:
        return self.height > 0


class ReactionStrip(Concealable, BoxLayout):
    """The quick reactions, floating over the message you held: tap one to
    react (tap one of yours again to take it back; v12: up to three each,
    each ringed); + opens every emoji."""

    def __init__(self, on_pick: Callable[[str], None],
                 on_more: Callable[[], None], **kw):
        kw.setdefault("size_hint", (None, None))
        kw.setdefault("height", dp(54))
        kw.setdefault("padding", [dp(6), dp(3)])
        super().__init__(**kw)
        self._on_pick = on_pick
        self.keys = {}
        self.more_key = IconButton("plus", label="More reactions",
                                   size=(dp(46), dp(48)),
                                   on_release=lambda _w: on_more())
        self.set_choices(QUICK_REACTIONS)
        self.width = dp(46) * (len(QUICK_REACTIONS) + 1) + dp(12)
        with self.canvas.before:
            Color(0, 0, 0, .30 if T.dark else .10)
            self._shadow = RoundedRectangle(radius=[dp(27)])
            Color(*C(T.surface_hi))
            self._bg = SmoothRoundedRectangle(radius=[dp(27)])
            # One ring per reaction of yours that the strip offers. An
            # unused one is made clear, not shrunk: a smooth ellipse sized
            # to nothing goes on drawing its last shape.
            self._mine = []
            for _i in range(MAX_REACTIONS):
                self._mine.append((Color(0, 0, 0, 0), SmoothEllipse()))
        with self.canvas.after:
            Color(*C(T.rule_strong))
            self._edge = SmoothLine(width=1.0)
        self.bind(pos=self._sync, size=self._sync)
        self.opacity = 0
        self.conceal(True)
        self._current: list = []

    def _sync(self, *_a):
        self._shadow.pos = (self.x, self.y - dp(2))
        self._shadow.size = self.size
        self._bg.pos, self._bg.size = self.pos, self.size
        self._edge.rounded_rectangle = (self.x + .5, self.y + .5,
                                        self.width - 1, self.height - 1,
                                        dp(27))
        keys = [self.keys[e] for e in self._current if e in self.keys]
        tint = C(mix(T.accent, T.surface_hi, .70))
        d = dp(40)
        for i, (colour, ring) in enumerate(self._mine):
            if i < len(keys):
                key = keys[i]
                ring.pos = ((key.x + key.width / 2) - d / 2,
                            (key.y + key.height / 2) - d / 2)
                ring.size = (d, d)
                colour.rgba = tint
            else:
                colour.rgba = (0, 0, 0, 0)

    @property
    def current(self) -> list:
        return list(self._current)

    def set_choices(self, emojis) -> None:
        """The reactions offered, in order (v12: yours first)."""
        emojis = list(dict.fromkeys(emojis))[:len(QUICK_REACTIONS)]
        if emojis == list(self.keys):
            return
        self.clear_widgets()
        self.keys = {}
        for emoji in emojis:
            key = EmojiKey(emoji, self._on_pick, size=(dp(46), dp(48)))
            key.font_size = sp(24)
            # The rings follow the keys, which the box lays out after it
            # moves.
            key.bind(pos=self._sync)
            self.keys[emoji] = key
            self.add_widget(key)
        self.add_widget(self.more_key)
        if hasattr(self, "_mine"):
            self._sync()

    def show(self, current) -> None:
        """Raise it, ringing the reactions already given (`current`, a
        list; a single emoji or '' as before)."""
        self._current = [current] if isinstance(current, str) and current \
            else [e for e in (current or ()) if isinstance(e, str)]
        self.conceal(False)
        self._sync()
        Animation.cancel_all(self, "opacity")
        if motion(1):
            self.opacity = 0
            Animation(opacity=1, d=0.14).start(self)
        else:
            self.opacity = 1

    def hide(self) -> None:
        self.conceal(True)
        Animation.cancel_all(self, "opacity")
        self.opacity = 0


def fold(widget, shown: bool, width: float, animate: bool = True) -> None:
    """Show a part of a row, or fold it away: its width runs to nothing
    (its neighbours slide over) as it fades."""
    Animation.cancel_all(widget, "width", "opacity")
    w, o = (width, 1.0) if shown else (0.0, 0.0)
    d = motion(0.18) if animate else 0
    if not d or (abs(widget.width - w) < .5 and abs(widget.opacity - o) < .01):
        widget.width, widget.opacity = w, o
        return
    Animation(width=w, opacity=o, d=d, t="out_cubic").start(widget)


class ComposerInput(BoxLayout):
    """The message field: a pill holding the emoji key, the text and the
    paperclip — and the camera, while nothing is written.

    The text fills the pill's whole height, so a click anywhere on it that
    is not one of its keys puts the cursor in the text.
    """

    KEY = dp(44)

    def __init__(self, hint="Message", on_enter=None, on_emoji=None,
                 on_attach=None, on_camera=None, **kw):
        kw.setdefault("padding", [dp(2), 0, dp(2), 0])
        super().__init__(**kw)
        paint_round(self, T.surface_hi, radius=dp(24))

        def key(icon, label, action):
            return IconButton(icon, label=label, size=(self.KEY, TOUCH),
                              pos_hint={"center_y": .5},
                              on_release=lambda _w: action and action())
        self.emoji_button = key("smile", "Emoji", on_emoji)
        self.input = InkTextInput(
            hint_text=hint, multiline=False, background_normal="",
            background_active="", background_color=(0, 0, 0, 0),
            foreground_color=C(T.text), hint_text_color=C(T.text_3),
            cursor_color=C(T.accent), selection_color=C(T.accent)[:3] + [.3],
            font_size=fs(17), write_tab=False, text_validate_unfocus=False,
            padding=[dp(4), 0, dp(4), 0])
        self.input.bind(size=self._centre_text)
        if on_enter is not None:
            self.input.bind(on_text_validate=lambda _w: on_enter())
        self.attach_button = key("attach", "Attach a photo", on_attach)
        self.camera_button = key("camera", "Take a photo", on_camera)
        for part in (self.emoji_button, self.input, self.attach_button,
                     self.camera_button):
            self.add_widget(part)

    def _centre_text(self, *_a) -> None:
        pad = max(0.0, (self.input.height - self.input.line_height) / 2.0)
        self.input.padding = [dp(4), pad, dp(4), pad]

    def show_camera(self, shown: bool, animate: bool = True) -> None:
        fold(self.camera_button, shown, self.KEY, animate)

    @property
    def text(self) -> str:
        return self.input.text

    @text.setter
    def text(self, value: str) -> None:
        # A single-line TextInput keeps its horizontal scroll across text
        # changes: switching from a chat with a long draft to an empty one
        # left the hint scrolled half out of view.
        self.input.text = value
        self.input.scroll_x = 0
        self.input.cursor = self.input.get_cursor_from_index(len(value))


class SendMicButton(IconButton):
    """The composer's send button — a microphone while nothing is written.
    Hold it to record: let go to send, slide left to delete, slide up to
    lock it hands-free. A tap records hands-free straight away."""

    def __init__(self, screen, *a, **kw):
        super().__init__(*a, **kw)
        self.screen = screen
        self._holding = False

    def set_holding(self, holding: bool) -> None:
        """While held, the microphone turns red and grows under the finger."""
        if holding == self._holding:
            return
        self._holding = holding
        self._bg_hex = T.alert if holding else T.accent
        Animation.cancel_all(self, "icon_scale")
        self.icon_scale = 1.0
        self._redraw()

    def on_touch_down(self, touch):
        if self.collide_point(*touch.pos) and not touch.is_mouse_scrolling \
                and not self.disabled and self.screen.mic_mode() and \
                getattr(touch, "button", "left") == "left":
            touch.grab(self)
            self.screen.hold_begin(touch)
            return True
        return super().on_touch_down(touch)

    def on_touch_move(self, touch):
        if touch.grab_current is self:
            self.screen.hold_move(touch)
            return True
        return super().on_touch_move(touch)

    def on_touch_up(self, touch):
        if touch.grab_current is self:
            touch.ungrab(self)
            self.screen.hold_end(touch)
            return True
        return super().on_touch_up(touch)


class LockPill(Widget):
    """Over the held microphone: a padlock and an arrow up, rising with
    the finger — slide up to it to record hands-free."""

    def __init__(self, **kw):
        kw.setdefault("size_hint", (None, None))
        kw.setdefault("size", (dp(40), dp(76)))
        super().__init__(**kw)
        self._rise = 0.0
        self._host = None
        self._anchor = None
        self.bind(pos=self._paint, size=self._paint)

    def show(self, host, anchor) -> None:
        self._host, self._anchor = host, anchor
        if self.parent is None:
            host.add_widget(self)
        self.set_rise(0.0)
        if motion(1):
            self.opacity = 0
            Animation(opacity=1, d=SHEET_FADE).start(self)

    def hide(self) -> None:
        Animation.cancel_all(self, "opacity")
        if self.parent is not None:
            self.parent.remove_widget(self)

    def set_rise(self, rise: float) -> None:
        self._rise = max(0.0, min(1.0, rise))
        host, anchor = self._host, self._anchor
        if host is None or anchor is None:
            return
        ax, ay = anchor.to_window(anchor.center_x, anchor.top)
        x, y = host.to_widget(ax, ay)
        self.pos = (host.x + x - self.width / 2,
                    host.y + y + dp(10) + self._rise * dp(24))
        self._paint()

    def _paint(self, *_a) -> None:
        self.canvas.clear()
        x, y, w, h = self.x, self.y, self.width, self.height
        with self.canvas:
            Color(*C(T.surface_hi))
            SmoothRoundedRectangle(pos=(x, y), size=(w, h), radius=[w / 2])
            Color(*C(T.rule_strong))
            SmoothLine(rounded_rectangle=(x, y, w, h, w / 2), width=1.0)
            tint = C(T.accent if self._rise > .6 else T.text_2)
            draw_icon("lock", x + w / 2, y + h - dp(22), dp(18), tint)
            draw_icon("chevron_up", x + w / 2, y + dp(20) + self._rise * dp(4),
                      dp(16), C(T.text_3))


class LiveLevels(Widget):
    """The microphone's level while recording: the latest readings as bars
    running in from the right."""

    def __init__(self, **kw):
        super().__init__(**kw)
        self._levels: list = []
        self.bind(pos=self._redraw, size=self._redraw)

    def update(self, levels: list) -> None:
        self._levels = levels
        self._redraw()

    def _redraw(self, *_a) -> None:
        self.canvas.clear()
        step, bar = dp(3.5), dp(1.5)
        bars = max(1, int(self.width / step))
        recent = self._levels[-bars:]
        peak = max([1500] + recent)
        with self.canvas:
            Color(*C(T.accent))
            x = self.right - len(recent) * step
            for level in recent:
                h = max(dp(2), self.height * .7 * min(1.0, .08 + level / peak))
                Rectangle(pos=(x, self.y + (self.height - h) / 2),
                          size=(bar, h))
                x += step


class ConversationScreen(SwipeGestures, Screen):
    """A conversation: its head (or, while messages are held, their
    actions), the messages bottom-anchored over the page, the reaction strip
    over a held message, and the composer — with the emoji panel beneath
    it. Direct chats, groups and notes to self all live here."""

    def __init__(self, app: "FextApp", **kw):
        super().__init__(name="conversation", **kw)
        self.app = app
        # ---- incremental-render bookkeeping ---------------------------------
        self._bubbles: dict = {}          # message id -> MessageBubble
        self._rendered_ids: list = []
        self._rendered_sigs: dict = {}
        self._rendered_peer: Optional[str] = None
        self._rendered_ticks: Optional[bool] = None
        self._last_day: Optional[str] = None
        # The topmost day heading and its day: what a page of older
        # messages joins onto (see prepend_messages).
        self._first_divider = None
        self._first_day: Optional[str] = None
        self._render_gen = 0              # bumped by every full render
        self._newer = 0                   # beyond a window opened further back
        self._strip_for: Optional[int] = None   # reactions raised by a tap
        self._backfill_ev = None
        self._user_scrolling = False
        self._unseen = 0
        self._scroll_trigger = None
        self._stick_to_bottom = True
        self._last_content_h = 0.0
        self.has_older = False
        self._more_button = Btn("Earlier messages", kind="text",
                                size_hint_y=None,
                                on_release=lambda _w:
                                self.app.load_older_messages())
        self.selected: dict = {}          # local id -> message, highlighted
        self._rows: dict = {}             # local id -> BubbleRow
        self._pending_pop: dict = {}      # cid -> emoji to animate in
        self.reply_to: Optional[dict] = None
        self.recorder = None
        self._rec_tick = None
        self.peer: Optional[str] = None
        self.kind = "dm"
        self.group: Optional[dict] = None
        self.peer_name_text = ""
        self._emoji_target: Optional[int] = None   # react via the panel
        self._draft_save = None                    # a pending draft write
        # v11: the preview of a link being written (when previews are on).
        self.link_preview: Optional[dict] = None
        self._preview_url: Optional[str] = None     # fetched, or being
        self._preview_dismissed: Optional[str] = None
        self._preview_ev = None
        self._previews_on = False
        root = BoxLayout(orientation="vertical")
        paint_round(root, T.bg, radius=0)
        self.add_widget(root)

        # ---- app bar: normal mode and highlight (selection) mode -------------
        self.bar = FloatLayout(size_hint_y=None,
                               height=max(dp(62), line_height(19) +
                                          line_height(14) + dp(14)))
        hairline(self.bar, "bottom")
        root.add_widget(self.bar)
        self.normal_bar = BoxLayout(padding=[dp(2), 0, dp(2), 0],
                                    spacing=dp(4), size_hint=(1, 1),
                                    pos_hint={"x": 0, "y": 0})
        self.normal_bar.add_widget(IconButton(
            "back", label="Back", pos_hint={"center_y": .5},
            on_release=lambda _w: self.app.go_back_to_chats()))
        self.peer_avatar_holder = AnchorLayout(size_hint_x=None, width=dp(42))
        self.normal_bar.add_widget(self.peer_avatar_holder)
        titles = TappableBox(on_tap=lambda: self.app.open_chat_info(),
                             padding=[dp(10), dp(8), 0, dp(8)])
        self.peer_name = single_line("", fs(19), T.text, bold=True,
                                     size_hint_y=None, height=line_height(19))
        self.peer_sub = single_line("", fs(14), T.text_3, italic=True,
                                    size_hint_y=None, height=line_height(14))
        titles.add_widget(self.peer_name)
        titles.add_widget(self.peer_sub)
        self.normal_bar.add_widget(titles)
        self.call_button = IconButton(
            "phone", label="Voice call", pos_hint={"center_y": .5},
            on_release=lambda _w: self.app.start_call())
        self.normal_bar.add_widget(self.call_button)
        self.more_button = IconButton(
            "more", label="More", pos_hint={"center_y": .5},
            on_release=lambda w: self.open_menu(w))
        self.normal_bar.add_widget(self.more_button)

        self.select_bar = BoxLayout(padding=[dp(2), 0, dp(2), 0],
                                    size_hint=(1, 1),
                                    pos_hint={"x": 0, "y": 0})
        self.select_bar.add_widget(IconButton(
            "close", label="Cancel selection", pos_hint={"center_y": .5},
            on_release=lambda _w: self.clear_selection()))
        self.select_count = Label(text="1", font_size=fs(20),
                                  color=C(T.text), halign="left",
                                  valign="middle", size_hint_x=None,
                                  width=dp(36))
        self.select_count.bind(size=lambda w, v: setattr(w, "text_size", v))
        self.select_bar.add_widget(self.select_count)
        self.select_bar.add_widget(Widget())
        self.actions: dict = {}
        for name, handler, label in (
                ("reply", self._act_reply, "Reply"),
                ("copy", self._act_copy, "Copy"),
                ("star", self._act_star, "Star"),
                ("forward", self._act_forward, "Forward"),
                ("share", self._act_share, "Share"),
                ("delete", self._act_delete, "Delete")):
            button = IconButton(name, label=label, size=(dp(42), TOUCH),
                                pos_hint={"center_y": .5},
                                on_release=lambda _w, h=handler: h())
            self.actions[name] = button
            self.select_bar.add_widget(button)
        # v11: search in this chat — the head becomes a field, with the
        # matches counted and stepped through, newest first.
        self.searching = False
        self._search_hits: list = []          # message ids, newest first
        self._search_at = -1
        self._search_ev = None
        self.search_bar = BoxLayout(padding=[dp(2), 0, dp(2), 0],
                                    spacing=dp(2), size_hint=(1, 1),
                                    pos_hint={"x": 0, "y": 0})
        self.search_bar.add_widget(IconButton(
            "back", label="Close search", pos_hint={"center_y": .5},
            on_release=lambda _w: self.close_search()))
        self.search_field = Field("Search this chat",
                                  pos_hint={"center_y": .5},
                                  on_enter=lambda: self.search_step(1))
        self.search_field.input.font_size = fs(18)
        self.search_field.input.bind(text=lambda _w, _v: self._search_soon())
        self.search_bar.add_widget(self.search_field)
        self.search_count = Label(text="", font_size=fs(14),
                                  color=C(T.text_3), size_hint_x=None,
                                  width=dp(62), halign="right",
                                  valign="middle")
        self.search_count.bind(size=lambda w, v: setattr(w, "text_size", v))
        self.search_bar.add_widget(self.search_count)
        self.search_up = IconButton(
            "chevron_up", label="Earlier match", size=(dp(40), TOUCH),
            pos_hint={"center_y": .5},
            on_release=lambda _w: self.search_step(1))
        self.search_down = IconButton(
            "chevron_down", label="Later match", size=(dp(40), TOUCH),
            pos_hint={"center_y": .5},
            on_release=lambda _w: self.search_step(-1))
        self.search_bar.add_widget(self.search_up)
        self.search_bar.add_widget(self.search_down)
        self.bar.add_widget(self.normal_bar)

        # ---- messages --------------------------------------------------------
        self.stack = FloatLayout()
        self.scroll = ScrollView(bar_width=dp(3), size_hint=(1, 1),
                                 pos_hint={"x": 0, "y": 0}, do_scroll_x=False)
        self.messages = BoxLayout(orientation="vertical", size_hint_y=None,
                                  padding=[0, dp(10), 0, dp(12)],
                                  spacing=dp(2))
        # Keeps a short conversation resting on the composer instead of up
        # under the app bar — see _sync_filler. Always the FIRST child.
        self._filler = Widget(size_hint_y=None, height=0)
        self._syncing_filler = False
        self.messages.add_widget(self._filler)
        self.messages.bind(minimum_height=self.messages.setter("height"))
        self.messages.bind(height=lambda *_a: self._on_content_height())
        self.messages.bind(minimum_height=lambda *_a: self._sync_filler())
        self.scroll.bind(height=lambda *_a: self._sync_filler())
        self.scroll.add_widget(self.messages)
        self.stack.add_widget(self.scroll)
        self.jump_button = JumpToBottomButton(on_tap=self.jump_to_latest,
                                              pos_hint={"right": 0.97,
                                                        "y": 0.02})
        self.stack.add_widget(self.jump_button)
        self.day_float = DayFloat(pos_hint={"center_x": .5, "top": .985})
        self.stack.add_widget(self.day_float)
        self.strip = ReactionStrip(self._strip_pick, self._strip_more)
        self.stack.add_widget(self.strip)
        self.scroll.bind(scroll_y=lambda *_a: self._on_scrolled())
        self.scroll.bind(scroll_y=lambda *_a: self._place_strip(),
                         size=lambda *_a: self._place_strip())
        self.scroll.bind(
            on_scroll_start=lambda *_a: setattr(self, "_user_scrolling", True),
            on_scroll_stop=lambda *_a: setattr(self, "_user_scrolling", False))
        # v12: the reader takes over from the "New messages" line.
        self.scroll.bind(
            on_scroll_start=lambda *_a: setattr(self, "_stick_to_line", False),
            height=lambda *_a: self._line_soon())
        root.add_widget(self.stack)

        # ---- v11: a link's preview, to go with the message -------------------
        self.preview_bar = ConcealableBox(size_hint_y=None, height=0,
                                          opacity=0,
                                          padding=[dp(16), dp(6), dp(4),
                                                   dp(6)],
                                          spacing=dp(12))
        self.preview_bar.conceal(True)
        hairline(self.preview_bar, "top")
        link_icon = Widget(size_hint_x=None, width=dp(22))
        link_icon.bind(pos=lambda w, *_a: self._paint_bar_icon(
            w, self.preview_bar, "link"), size=lambda w, *_a:
            self._paint_bar_icon(w, self.preview_bar, "link"))
        self.preview_bar.add_widget(link_icon)
        ptexts = BoxLayout(orientation="vertical", padding=[dp(10), dp(2)])
        with ptexts.canvas.before:
            Color(*C(T.accent))
            ptexts._rule = Rectangle()
        ptexts.bind(pos=self._sync_bar_rule, size=self._sync_bar_rule)
        self.preview_site = CapsLabel("", size=10.5, color=T.accent)
        self.preview_title = single_line("", fs(15), T.text_2, italic=True)
        ptexts.add_widget(self.preview_site)
        ptexts.add_widget(self.preview_title)
        self.preview_bar.add_widget(ptexts)
        self.preview_thumb = KivyImage(size_hint=(None, None),
                                       size=(0, dp(40)), allow_stretch=True,
                                       keep_ratio=True, opacity=0,
                                       pos_hint={"center_y": .5})
        self.preview_bar.add_widget(self.preview_thumb)
        self.preview_bar.add_widget(IconButton(
            "close", label="Send without a preview",
            pos_hint={"center_y": .5},
            on_release=lambda _w: self.dismiss_preview()))
        root.add_widget(self.preview_bar)

        # ---- reply preview (while composing a reply) -------------------------
        self.reply_bar = ConcealableBox(size_hint_y=None, height=0,
                                        opacity=0,
                                        padding=[dp(16), dp(6), dp(4), dp(6)],
                                        spacing=dp(12))
        self.reply_bar.conceal(True)
        hairline(self.reply_bar, "top")
        reply_icon = Widget(size_hint_x=None, width=dp(22))
        reply_icon.bind(pos=lambda w, *_a: self._paint_reply_icon(w),
                        size=lambda w, *_a: self._paint_reply_icon(w))
        self.reply_bar.add_widget(reply_icon)
        texts = BoxLayout(orientation="vertical", padding=[dp(10), dp(2)])
        with texts.canvas.before:
            Color(*C(T.accent))
            self._reply_accent = Rectangle()
        texts.bind(pos=lambda w, *_a: self._sync_reply_accent(w),
                   size=lambda w, *_a: self._sync_reply_accent(w))
        self.reply_author = CapsLabel("", size=10.5, color=T.accent)
        self.reply_snip = single_line("", fs(15), T.text_2, italic=True)
        texts.add_widget(self.reply_author)
        texts.add_widget(self.reply_snip)
        self.reply_bar.add_widget(texts)
        self.reply_bar.add_widget(IconButton(
            "close", label="Cancel reply", pos_hint={"center_y": .5},
            on_release=lambda _w: self.cancel_reply()))
        root.add_widget(self.reply_bar)

        # ---- composer --------------------------------------------------------
        # Nothing written: [you] ( ☺  Message   📎 📷 ) [mic]
        # Writing:              ( ☺  the text…      📎 ) [send]
        # The avatar and the camera fold away, and the microphone turns
        # into the send button.
        self._composer_h = max(dp(64), line_height(17) + dp(30))
        self.composer = BoxLayout(size_hint_y=None, height=self._composer_h,
                                  padding=[dp(4), dp(8), dp(4), dp(8)])
        hairline(self.composer, "top")
        self.me_holder = AnchorLayout(size_hint_x=None, width=TOUCH)
        self.entry = ComposerInput(on_enter=self.app.send_current,
                                   on_emoji=self.toggle_emoji,
                                   on_attach=self.pick_image,
                                   on_camera=self.take_photo)
        self.emoji_button = self.entry.emoji_button
        self.attach_button = self.entry.attach_button
        self.camera_button = self.entry.camera_button
        self.action_holder = AnchorLayout(size_hint_x=None, width=dp(56))
        self.action_button = SendMicButton(
            self, "send", bg=T.accent, tint=T.on_accent, label="Send",
            icon_size=dp(23), on_release=lambda _w: self._on_action_button())
        self.action_holder.add_widget(self.action_button)
        self.entry.input.bind(text=lambda *_a: self._on_text_changed(),
                              focus=self._on_entry_focus)
        self.composer_parts = (self.me_holder, self.entry, self.action_holder)
        for part in self.composer_parts:
            self.composer.add_widget(part)
        # Shown instead of the composer when you can no longer write here.
        self.closed_note = InfoLabel("", color=T.text_3, italic=True,
                                     font_size=fs(15), halign="center",
                                     pos_hint={"center_y": .5})
        self.blocked_note = BoxLayout(padding=[dp(18), dp(4), dp(10), dp(4)],
                                      spacing=dp(10))
        self.blocked_text = InfoLabel("", color=T.text_3, italic=True,
                                      font_size=fs(15),
                                      pos_hint={"center_y": .5})
        self.blocked_note.add_widget(self.blocked_text)
        # A note longer than the composer is tall makes room for itself.
        for label in (self.closed_note, self.blocked_text):
            label.bind(height=lambda *_a: self._fit_note())
        unblock = Btn("Unblock", kind="text", size_hint_x=None,
                      pos_hint={"center_y": .5},
                      on_release=lambda _w: self.app.set_blocked(
                          [self.peer], False))
        unblock.width = unblock.natural_width() + dp(8)
        self.blocked_note.add_widget(unblock)
        # v14 (B16): instead of the composer, in a message request.
        self.request_note = BoxLayout(orientation="vertical",
                                      padding=[dp(18), dp(8), dp(18), dp(8)],
                                      spacing=dp(8))
        self.request_text = InfoLabel("", color=T.text_2, italic=True,
                                      font_size=fs(15))
        self.request_text.bind(height=lambda *_a: self._fit_note())
        self.request_note.add_widget(self.request_text)
        answers = BoxLayout(size_hint_y=None, height=TOUCH, spacing=dp(10))
        for title, kind, act in (
                ("Accept", "primary",
                 lambda: self.app.accept_request(self.peer)),
                ("Decline", "quiet",
                 lambda: self.app.decline_request(self.peer)),
                ("Report", "danger",
                 lambda: ReportSheet(self.app, self.peer).open())):
            answers.add_widget(Btn(title, kind=kind,
                                   on_release=lambda _w, a=act: a()))
        self.request_note.add_widget(answers)
        # What the composer becomes while recording: discard, the time and
        # the microphone's level, send.
        self.rec_cancel = IconButton(
            "delete", tint=T.alert, label="Discard recording",
            pos_hint={"center_y": .5},
            on_release=lambda _w: self.cancel_recording())
        self.rec_dot = Widget(size_hint_x=None, width=dp(18))
        self.rec_dot.bind(pos=self._paint_rec_dot, size=self._paint_rec_dot)
        self.rec_label = Label(text="", font_size=fs(16), color=C(T.text),
                               halign="left", valign="middle",
                               size_hint_x=None, width=dp(58))
        self.rec_label.bind(size=lambda w, v: setattr(w, "text_size", v))
        self.rec_levels = LiveLevels()
        self.rec_send = IconButton(
            "send", bg=T.accent, tint=T.on_accent, label="Send recording",
            icon_size=dp(23), pos_hint={"center_y": .5},
            on_release=lambda _w: self.finish_recording())
        # Holding: what sliding does, and (over the microphone) the lock.
        self.rec_hint = Label(text="‹  Slide to cancel", font_size=fs(15),
                              italic=True, color=C(T.text_3),
                              halign="center", valign="middle")
        self.rec_hint.bind(size=lambda w, v: setattr(w, "text_size", v))
        self.rec_pause = IconButton("pause", label="Pause recording",
                                    pos_hint={"center_y": .5},
                                    on_release=lambda _w:
                                    self.toggle_pause())
        self.lock_pill = LockPill()
        self._hold: Optional[dict] = None
        self._rec_locked = False
        root.add_widget(self.composer)
        self.emoji_panel = EmojiPanel(self._emoji_picked)
        root.add_widget(self.emoji_panel)
        self._sync_composer(animate=False)

    # ---- header --------------------------------------------------------------
    def set_peer(self, peer: str, contact: dict, unread_count: int,
                 kind: str = "dm", group: Optional[dict] = None) -> None:
        self._previews_on = link_previews_enabled()
        if peer != self.peer:
            self.close_search()
            self.clear_selection()
            self.cancel_reply()
            self.cancel_preview()
            self.cancel_recording()
            self.close_emoji()
            self.keep_draft()
            # v11: drafts live in the identity's database, so unsent text
            # survives the app being closed or the phone restarting.
            store = self.app.store
            self.peer = peer          # before the text, so it is its draft
            self.entry.text = store.draft(peer) if store is not None else ""
            self._sync_composer(animate=False)
        self._refresh_me()
        self.peer, self.kind, self.group = peer, kind, group
        if kind == "self":
            name = "Saved messages"
        elif kind == "group":
            name = (group or {}).get("name") or "Group"
        else:
            name = contact.get("username") or short_addr(peer, 14)
        self.peer_name_text = name
        self.peer_avatar_holder.clear_widgets()
        disc = AvatarButton(peer, name, diameter=dp(38), kind=kind,
                            size=(dp(42), TOUCH), pos_hint={"center_y": .5})
        disc.bind(on_release=lambda _w: self.app.open_chat_info())
        self.peer_avatar_holder.add_widget(disc)
        # Calls are between two people: the button is there for a direct
        # chat only (a hidden one would still take touches) — and (v14) not
        # in a message request, which is answered first.
        has_call = self.call_button.parent is not None
        callable_ = kind == "dm" and contact.get("accepted", 1)
        if callable_ and not has_call:
            self.normal_bar.add_widget(self.call_button,
                                       index=self.normal_bar.children.index(
                                           self.more_button) + 1)
        elif not callable_ and has_call:
            self.normal_bar.remove_widget(self.call_button)
        self.peer_name.text = name
        bits = []
        if kind == "self":
            bits.append("kept on this device")
        elif kind == "group":
            members = (group or {}).get("members") or []
            me = self.app.keys.address
            names = ["you"] + [self.author_name(m["a"]) for m in members
                               if m["a"] != me]
            bits.append(", ".join(names) if len(names) <= 4
                        else f"{len(members)} members")
            if self.app.store is not None and \
                    self.app.store.mute_state(peer)[0]:
                bits.append("muted")
        else:
            bits.append(short_addr(peer, 12))
            if self.app.store is not None and \
                    self.app.store.mute_state(peer)[0]:
                bits.append("muted")
        if unread_count and kind != "group" and not contact.get("auto_read",
                                                                1):
            bits.append(f"{unread_count} unread")
        if kind == "dm" and contact.get("verified"):
            bits.insert(0, "verified")
        timer = self.app.store.chat_timer(peer)[0] \
            if self.app.store is not None and kind != "self" else 0
        if timer:               # first: it is cut short before the address
            bits.insert(1 if bits and bits[0] == "verified" else 0,
                        f"disappearing: {timer_label(timer).lower()}")
        self.peer_sub.text = " · ".join(bits)
        self._sync_closed()

    def _sync_closed(self) -> None:
        """A group you left (or were removed from, or not yet joined) is
        read-only: the composer gives way to a note saying why. So is a
        contact you blocked, with the way to unblock them."""
        note = ""
        if self.kind == "group":
            state = (self.group or {}).get("state")
            note = {"left": "You left this group.",
                    "removed": "You are no longer a member of this group.",
                    "pending": "This group's invitation has not arrived "
                               "yet."}.get(state, "")
        blocked = self.kind == "dm" and self.peer is not None and \
            self.app.store is not None and self.app.store.is_blocked(self.peer)
        # v14: someone new, not yet accepted — answered here, not written to.
        request = not blocked and self.kind == "dm" and \
            self.peer is not None and self.app.store is not None and \
            self.app.store.is_request(self.peer)
        part = self.blocked_note if blocked else \
            self.request_note if request else self.closed_note
        for other in (self.blocked_note, self.request_note, self.closed_note):
            if other is not part and other.parent is not None:
                self.composer.remove_widget(other)
        closed = bool(note) or blocked or request
        showing = part.parent is not None
        if request:
            self.request_text.text = self._request_text()
        if blocked:
            held = self.app.store.held_count(self.peer)
            self.blocked_text.text = (
                f"Blocked. {held} message{'s' if held != 1 else ''} held, "
                f"unopened, until you unblock them." if held else
                "Blocked. What they send is held, unopened, until you "
                "unblock them.")
        if closed and not showing:
            self.close_emoji()
            self.cancel_recording()
            self.composer.clear_widgets()
            if part is self.closed_note:
                self.closed_note.text = note
            self.composer.add_widget(part)
        elif closed and part is self.closed_note:
            self.closed_note.text = note
        elif not closed and (showing or not self.composer.children):
            self.composer.clear_widgets()
            for part in self.composer_parts:
                self.composer.add_widget(part)
            self._sync_composer(animate=False)
        self._fit_note()
        self.more_button.disabled = False

    def _fit_note(self) -> None:
        label = self.blocked_text if self.blocked_note.parent is not None \
            else self.closed_note if self.closed_note.parent is not None \
            else None
        pad = self.composer.padding[1] + self.composer.padding[3] + dp(8)
        if self.request_note.parent is not None:
            note = self.request_note
            self.composer.height = self.request_text.height + TOUCH + \
                note.spacing + note.padding[1] + note.padding[3] + pad
            return
        self.composer.height = max(self._composer_h, label.height + pad) \
            if label is not None else self._composer_h

    def _request_text(self) -> str:
        """Who wrote first, what you share with them, and what they see."""
        store = self.app.store
        name = (store.get_contact(self.peer) or {}).get("username") or \
            short_addr(self.peer, 12)
        groups = store.shared_groups(self.peer)
        both = "" if not groups else \
            f" You are both in {groups[0]}." if len(groups) == 1 else \
            f" You are both in {groups[0]} and {len(groups) - 1} more."
        return (f"{name} wants to message you.{both} Until you accept, they "
                f"see one tick and no read receipts.")

    # ---- bubbles -------------------------------------------------------------
    def render(self, messages: list, ticks_enabled: bool,
               on_tap_unread: Callable, peer: Optional[str] = None) -> None:
        """Incremental render: new messages append, changed ones repaint in
        place, nothing changed costs nothing. A full rebuild only when the
        list's shape changes in a way appending cannot express (another
        chat, history paged in, rows deleted or imported)."""
        signatures = {m["id"]: self._signature(m) for m in messages}
        ids = [m["id"] for m in messages]
        rebuild = (peer != self._rendered_peer
                   or ticks_enabled != self._rendered_ticks
                   or not self._rendered_ids
                   or len(ids) < len(self._rendered_ids)
                   or ids[:len(self._rendered_ids)] != self._rendered_ids)
        if rebuild:
            self._full_render(messages, ticks_enabled, on_tap_unread, peer)
            return
        repainted = False
        for msg in messages:
            mid = msg["id"]
            previous = self._rendered_sigs.get(mid)
            if previous is None or previous == signatures[mid]:
                continue
            bubble = self._bubbles.get(mid)
            if bubble is not None:
                bubble.update(msg, ticks_enabled)
                repainted = True
                if mid in self.selected:
                    self.selected[mid] = msg
        was_at_bottom = self.at_bottom()
        appended = 0
        sent_by_me = False
        for msg in messages[len(self._rendered_ids):]:
            self._append_bubble(msg, ticks_enabled, on_tap_unread)
            appended += 1
            if msg["direction"] == "out":
                sent_by_me = True
        if repainted and not appended:
            self._join_rows()          # ticks moved: time lines join or part
        self._rendered_ids = ids
        self._rendered_sigs = signatures
        if appended:
            if sent_by_me or was_at_bottom:
                self.scroll_to_bottom()
            else:
                self.note_new_messages(appended)
        self._place_strip()

    #: v12: the first message not yet read when the chat was opened, and
    #: how many there were; the "New messages" line goes above it.
    unread_from: Optional[int] = None
    unread_count = 0
    _new_line = None

    def mark_new_from(self, message_id: Optional[int], count: int) -> None:
        self.unread_from, self.unread_count = message_id, count

    #: While the chat opens at its line, the line is kept at the top as
    #: the page settles (bubbles taking their size, history joining on
    #: above) — until the reader scrolls, or the chat is followed to its end.
    _stick_to_line = False
    _line_ev = None

    def _line_soon(self) -> None:
        """Place the line on the next frame, once the rows have moved."""
        if self._stick_to_line and self._line_ev is None:
            def go(_dt):
                self._line_ev = None
                if self._stick_to_line:
                    self._place_line()
            self._line_ev = Clock.schedule_once(go)

    def _place_line(self) -> None:
        """The "New messages" line at the top, what follows below it — or
        the end of the chat, when all of that fits."""
        line = self._new_line
        view = self.scroll.height
        if line is None or line.parent is None:
            self._stick_to_line = False
            return
        if view <= 1:
            return                         # not laid out yet: placed when it is
        span = self.messages.height - view
        below = line.top - self.messages.y + dp(8)
        target = 0.0 if span <= 0 or below <= view else \
            max(0.0, min(1.0, (below - view) / span))
        if abs(self.scroll.scroll_y - target) > 1e-4:
            self.scroll.scroll_y = target
        self._sync_jump_button()

    def _full_render(self, messages: list, ticks_enabled: bool,
                     on_tap_unread: Callable, peer: Optional[str]) -> None:
        self.cancel_backfill()
        self.close_strip()
        self._render_gen += 1
        self._new_line = None
        self.messages.clear_widgets()
        self.messages.add_widget(self._filler)
        self._bubbles.clear()
        self._rows.clear()
        self._last_day = None
        self._first_divider, self._first_day = None, None
        if not messages:
            self.messages.add_widget(self._empty_state())
        if self._more_button.parent is not None:
            self._more_button.parent.remove_widget(self._more_button)
        if self.has_older:
            self.messages.add_widget(self._more_button)
        for msg in messages:
            self._append_bubble(msg, ticks_enabled, on_tap_unread,
                                join=False)
        self._join_rows()
        self._rendered_ids = [m["id"] for m in messages]
        self._rendered_sigs = {m["id"]: self._signature(m)
                               for m in messages}
        self._rendered_peer = peer
        self._rendered_ticks = ticks_enabled
        self._unseen = 0
        if self._new_line is not None:
            # Open where the unread begin (v12), and stay there as it settles.
            self._stick_to_bottom = False
            self._stick_to_line = True
            self._line_soon()
        else:
            self._stick_to_line = False
            self.scroll_to_bottom(animate=False)

    @staticmethod
    def _signature(msg: dict) -> tuple:
        """Everything that, if it changes, means a bubble must repaint —
        (v14) a day passing on a message the relay never took, too."""
        return (msg["status"], msg["read"], msg["body"], msg.get("starred"),
                msg.get("media_state"), msg.get("media_path"), msg.get("ext"),
                tuple(msg.get("reactions") or ()), waits_for_tap(msg))

    def _widgets_for(self, msg: dict, ticks_enabled: bool,
                     prev_day: Optional[str]) -> tuple:
        """The widgets one message adds, top to bottom (a day heading when
        its day differs from `prev_day`), and its day."""
        out = []
        day = str(msg.get("created_at", ""))[:10]
        if day and day != prev_day:
            out.append(DayDivider(self._day_text(day)))
        if msg.get("kind") == "event":
            out.append(EventRow(msg))
            return out, day or prev_day
        if msg["id"] == self.unread_from and self._new_line is None:
            self._new_line = NewMessagesLine(self.unread_count)
            # Placed again whenever the layout moves it, while it leads.
            self._new_line.bind(pos=lambda *_a: self._line_soon())
            out.append(self._new_line)
        outgoing = msg["direction"] == "out"
        bubble = MessageBubble(msg, ticks_enabled, self)
        self._bubbles[msg["id"]] = bubble
        row = BubbleRow(bubble, outgoing, self)
        row.set_selected(msg["id"] in self.selected)
        self._rows[msg["id"]] = row
        row._fit_height()
        out.append(row)
        pending = self.take_pending_pop(msg.get("client_msg_id"))
        if pending:
            chip = bubble.reactions.chip_for(pending)
            if chip is not None:
                chip.animate_in()
        return out, day or prev_day

    def _append_bubble(self, msg: dict, ticks_enabled: bool,
                       on_tap_unread: Callable, join: bool = True) -> None:
        widgets, self._last_day = self._widgets_for(msg, ticks_enabled,
                                                    self._last_day)
        for widget in widgets:
            if self._first_divider is None and isinstance(widget, DayDivider):
                self._first_divider = widget
                self._first_day = self._last_day
            self.messages.add_widget(widget)
        if join:
            self._join_rows(tail=2)

    #: Messages of one person this close together form a run (v12).
    RUN_SECONDS = 180

    @classmethod
    def same_run(cls, a: Optional[dict], b: Optional[dict]) -> bool:
        """Whether `b`, just below `a`, continues `a`'s run: the same
        person, the same day, at most RUN_SECONDS later."""
        if a is None or b is None or "event" in (a.get("kind"),
                                                 b.get("kind")):
            return False
        if a["direction"] != b["direction"] or \
                (a.get("author") or "") != (b.get("author") or ""):
            return False
        ta, tb = str(a.get("created_at", "")), str(b.get("created_at", ""))
        if ta[:10] != tb[:10]:
            return False
        try:
            gap = (datetime.fromisoformat(tb) -
                   datetime.fromisoformat(ta)).total_seconds()
        except (TypeError, ValueError):
            return False
        return 0 <= gap <= cls.RUN_SECONDS

    def _join_rows(self, tail: int = 0) -> None:
        """Close up the runs among the messages drawn: each row knows if
        the one above and the one below are part of its run. With `tail`,
        only the last rows (a message just arrived below them)."""
        rows = [w for w in reversed(self.messages.children)
                if isinstance(w, (BubbleRow, EventRow, DayDivider,
                                  NewMessagesLine))]
        for i, widget in enumerate(rows):
            if not isinstance(widget, BubbleRow) or \
                    (tail and i < len(rows) - tail):
                continue
            above = rows[i - 1] if i > 0 else None
            below = rows[i + 1] if i + 1 < len(rows) else None
            joined_below = isinstance(below, BubbleRow) and \
                self.same_run(widget.bubble.msg, below.bubble.msg)
            widget.set_joins(
                isinstance(above, BubbleRow) and
                self.same_run(above.bubble.msg, widget.bubble.msg),
                joined_below)
            # One time line for what was said in the same minute, unless
            # the ticks or a star tell the two apart.
            widget.bubble.set_meta_shown(
                not joined_below or
                widget.bubble.meta_key() != below.bubble.meta_key())

    def prepend_messages(self, older: list, ticks_enabled: bool) -> None:
        """Older messages above those shown (oldest first in `older`),
        without moving the view: a page of history joins on at the top,
        dropping the heading of a day that it continues."""
        if not older:
            return
        built, day = [], None
        for msg in older:
            widgets, day = self._widgets_for(msg, ticks_enabled, day)
            built.extend(widgets)
        if self._first_divider is not None and day == self._first_day and \
                self._first_divider.parent is self.messages:
            self.messages.remove_widget(self._first_divider)
        self._first_divider = built[0] if isinstance(built[0], DayDivider) \
            else self._first_divider
        self._first_day = str(older[0].get("created_at", ""))[:10] or \
            self._first_day
        # children run newest-first; the filler (and the button for earlier
        # messages) sit at the end, above everything.
        top = len(self.messages.children) - 1
        if self._more_button.parent is self.messages:
            top -= 1
        for widget in built:
            self.messages.add_widget(widget, index=top)
        self._join_rows()
        self._rendered_ids = [m["id"] for m in older] + self._rendered_ids
        self._rendered_sigs.update({m["id"]: self._signature(m) for m in older})
        if self.content_height() <= self.scroll.height:
            self._stick_to_bottom = True

    def set_newer(self, count: int) -> None:
        """Messages newer than the window shown (0 when it is live): the
        jump button carries them, and leads back to the end."""
        self._newer = count
        if count:
            self._unseen = count
        self._sync_jump_button()

    def focus_message(self, message_id: int) -> bool:
        """Scroll to a message on screen and flash it; False if it is not
        in the window drawn."""
        row = self._rows.get(message_id)
        if row is None:
            return False
        self.cancel_pending_scroll()
        self.scroll.scroll_to(row, padding=dp(80), animate=bool(motion(1)))
        row.set_selected(True)
        Clock.schedule_once(
            lambda _dt: row.set_selected(message_id in self.selected), 1.1)
        return True

    def set_has_older(self, has_older: bool) -> None:
        """Show or drop the 'Earlier messages' button at the top."""
        self.has_older = has_older
        showing = self._more_button.parent is self.messages
        if has_older and not showing:
            self.messages.add_widget(self._more_button,
                                     index=len(self.messages.children) - 1)
        elif not has_older and showing:
            self.messages.remove_widget(self._more_button)

    def run_backfill(self, pages: list, ticks_enabled: bool,
                     on_page: Optional[Callable] = None,
                     on_done: Optional[Callable] = None) -> None:
        """Prepend `pages` (each a chronological list, newest page first)
        one per frame, pausing while a finger is scrolling. Abandoned if the
        chat is re-rendered meanwhile. `on_page(page)` follows each one."""
        self.cancel_backfill()
        gen = self._render_gen

        def step(_dt):
            self._backfill_ev = None
            if gen != self._render_gen:
                return
            if self._user_scrolling:
                self._backfill_ev = Clock.schedule_once(step, 0.08)
                return
            if pages:
                page = pages.pop(0)
                self.prepend_messages(page, ticks_enabled)
                if on_page is not None:
                    on_page(page)
            if pages:
                self._backfill_ev = Clock.schedule_once(step, 0)
            elif on_done is not None:
                on_done()
        self._backfill_ev = Clock.schedule_once(step, 0)

    def cancel_backfill(self) -> None:
        if self._backfill_ev is not None:
            self._backfill_ev.cancel()
            self._backfill_ev = None

    # =========================================================================
    #  Reactions
    # =========================================================================
    def take_pending_pop(self, cid: Optional[str]) -> Optional[str]:
        return self._pending_pop.pop(cid, None) if cid else None

    def note_reaction(self, cid: str, reactor: str, emoji: str) -> None:
        """A reaction changed: make it pop, now if its chip is on screen,
        or as soon as it is drawn."""
        if not emoji:
            return
        for bubble in self._bubbles.values():
            if bubble.msg.get("client_msg_id") == cid:
                chip = bubble.reactions.chip_for(emoji)
                if chip is not None:
                    chip.animate_in()
                    return
        self._pending_pop[cid] = emoji

    def quick_reactions(self) -> list:
        """The strip's reactions: the ones you give most, then the usual
        ones, six in all (v12)."""
        store = self.app.store
        mine = store.favourite_reactions(self.app.keys.address) \
            if store is not None else []
        return list(dict.fromkeys(mine + list(QUICK_REACTIONS)))[
            :len(QUICK_REACTIONS)]

    def on_reaction_tap(self, msg: dict, emoji: str) -> None:
        if self.selecting:
            return
        self.app.react(msg["id"], emoji)

    def show_reactors(self, msg_id: int, emoji: str = "") -> None:
        """Who gave a message's reactions (v13), those of `emoji` first
        listed when it has company."""
        bubble = self._bubbles.get(msg_id)
        if bubble is None or not bubble.msg.get("reactions"):
            return
        self.close_strip()
        ReactorsSheet(self, bubble.msg, emoji).open()

    def _reactable(self, msg: dict) -> bool:
        return bool(msg.get("client_msg_id")) and msg.get("kind") != "event" \
            and self.closed_note.parent is None

    def _strip_target(self) -> Optional[int]:
        """The message the strip is over: one held, or one tapped."""
        if len(self.selected) == 1:
            return next(iter(self.selected))
        if not self.selected and self._strip_for in self._bubbles:
            return self._strip_for
        return None

    def _strip_pick(self, emoji: str) -> None:
        target = self._strip_target()
        self.clear_selection()
        self.close_strip()
        if target is not None:
            self.app.react(target, emoji)

    def _strip_more(self) -> None:
        target = self._strip_target()
        if target is None:
            return
        self._emoji_target = target
        self.clear_selection()
        self.close_strip()
        self.open_emoji()

    def _place_strip(self, *_a) -> None:
        """Float the strip just above the held (or tapped) message, inside
        the view."""
        target = self._strip_target()
        if self.strip.concealed or target is None:
            return
        row = self._rows.get(target)
        if row is None:
            return
        bubble = row.bubble
        bx, by = bubble.to_window(bubble.x, bubble.top)
        x, y = self.stack.to_widget(bx, by)
        sx = min(max(dp(8), x + bubble.width / 2 - self.strip.width / 2),
                 self.stack.width - self.strip.width - dp(8))
        sy = y + dp(6)
        top = self.stack.top - self.strip.height - dp(6)
        if sy > top:                          # no room above: sit below it
            bx, by = bubble.to_window(bubble.x, bubble.y)
            sy = self.stack.to_widget(bx, by)[1] - self.strip.height - dp(6)
        self.strip.pos = (self.stack.x + sx,
                          max(self.stack.y + dp(6), min(sy, top)))

    # =========================================================================
    #  Highlight (selection) mode
    # =========================================================================
    @property
    def selecting(self) -> bool:
        return bool(self.selected)

    def start_selection(self, msg_id: int) -> None:
        if msg_id not in self.selected:
            self.toggle_selection(msg_id)

    def toggle_selection(self, msg_id: int) -> None:
        bubble = self._bubbles.get(msg_id)
        if bubble is None:
            return
        if msg_id in self.selected:
            del self.selected[msg_id]
            if isinstance(bubble.body, SelectableText):
                bubble.body.cancel_selection()
        else:
            self.selected[msg_id] = bubble.msg
        row = self._rows.get(msg_id)
        if row is not None:
            row.set_selected(msg_id in self.selected)
        self._sync_selection()

    def clear_selection(self) -> None:
        for msg_id in list(self.selected):
            row = self._rows.get(msg_id)
            if row is not None:
                row.set_selected(False)
            bubble = self._bubbles.get(msg_id)
            if bubble is not None and isinstance(bubble.body, SelectableText):
                bubble.body.cancel_selection()
        self.selected.clear()
        self._sync_selection()

    def _sync_selection(self) -> None:
        """Swap the app bar, enable only the actions that apply, and raise
        the reaction strip over a single held message."""
        on = bool(self.selected)
        if on:
            self._strip_for = None
        self._show_head(self.select_bar if on else self.search_bar
                        if self.searching else self.normal_bar)
        msgs = list(self.selected.values())
        if len(msgs) == 1 and self._reactable(msgs[0]):
            self.strip.set_choices(self.quick_reactions())
            self.strip.show(self.app.store.reactions_of(
                msgs[0]["peer"], msgs[0]["client_msg_id"],
                self.app.keys.address) if self.app.store else [])
            self._place_strip()
        else:
            self.strip.hide()
            self._strip_for = None
        if not on:
            return
        self.select_count.text = str(len(msgs))
        has_text = any(self._text_of(m) for m in msgs)
        self.actions["reply"].disabled = len(msgs) != 1 or \
            self.closed_note.parent is not None
        self.actions["copy"].disabled = not has_text
        self.actions["star"].set_icon(
            "star_filled" if all(m.get("starred") for m in msgs) else "star")
        self.actions["share"].disabled = not (has_text or any(
            m.get("kind") == "image" and m.get("media_path") for m in msgs))
        self.actions["forward"].disabled = any(
            m.get("kind") in ("image", "voice") and not
            ((message_ext(m).get("media") or {}).get("blob") or
             m.get("media_path")) for m in msgs)

    def _show_head(self, bar) -> None:
        """Exactly one of the head's three bars: normal, held messages'
        actions, or search."""
        if bar.parent is self.bar:
            return
        for other in (self.normal_bar, self.select_bar, self.search_bar):
            if other.parent is self.bar:
                self.bar.remove_widget(other)
        self.bar.add_widget(bar)

    # ---- v11: swipes ------------------------------------------------------------------
    def swipe_kind(self, touch, dx: float) -> Optional[str]:
        """In the messages: to the right goes back to the chats; to the
        left on a message replies to it (never from its waveform)."""
        if self.selecting or self.recorder is not None:
            return None
        wx, wy = window_pos(self, *touch.opos)
        if not hits(self.stack, wx, wy):
            return None
        if dx > 0:
            return "back"
        row = self._row_at(wx, wy)
        if row is None or self.composer_closed():
            return None
        media = row.bubble.media
        if isinstance(media, VoiceContent) and hits(media.wave, wx, wy):
            return None
        self._swipe_row = row
        return "reply"

    def _row_at(self, wx: float, wy: float) -> Optional["BubbleRow"]:
        for row in self._rows.values():
            if hits(row, wx, wy):
                return row
        return None

    def composer_closed(self) -> bool:
        """You cannot write here: a group you are not in, a blocked
        contact."""
        return self.closed_note.parent is not None or \
            self.blocked_note.parent is not None

    def reply_swipe_begin(self, touch) -> bool:
        self.close_strip()
        return getattr(self, "_swipe_row", None) is not None

    def reply_swipe_follow(self, dx: float) -> None:
        row = self._swipe_row
        if row is None:
            return
        pull = min(0.0, dx)
        # Freely to the reply mark, then stiffly beyond it.
        if pull < -SWIPE_REPLY:
            pull = -SWIPE_REPLY + (pull + SWIPE_REPLY) * 0.25
        row.shift = max(pull, -SWIPE_REPLY * 1.6)

    def reply_swipe_end(self, dx: float) -> None:
        row, self._swipe_row = self._swipe_row, None
        if row is None:
            return
        row.settle_shift()
        if dx <= -SWIPE_REPLY:
            bubble = self._bubbles.get(row.msg_id)
            if bubble is not None:
                self.set_reply(bubble.msg)

    # ---- v11: search in this chat ----------------------------------------------------
    def open_search(self) -> None:
        if self.peer is None or self.app.store is None:
            return
        self.clear_selection()
        self.close_strip()
        self.searching = True
        self._show_head(self.search_bar)
        self.search_field.text = ""
        self._search_hits, self._search_at = [], -1
        self._sync_search_count()
        Clock.schedule_once(lambda _dt: setattr(self.search_field.input,
                                                "focus", True), 0.05)

    def close_search(self) -> None:
        if not self.searching:
            return
        self.searching = False
        if self._search_ev is not None:
            self._search_ev.cancel()
            self._search_ev = None
        self.search_field.input.focus = False
        self._search_hits, self._search_at = [], -1
        self._show_head(self.select_bar if self.selected
                        else self.normal_bar)

    def _search_soon(self) -> None:
        if not self.searching:
            return
        if self._search_ev is not None:
            self._search_ev.cancel()
        self._search_ev = Clock.schedule_once(lambda _dt: self._run_search(),
                                              0.25)

    def _run_search(self) -> None:
        self._search_ev = None
        store, peer = self.app.store, self.peer
        query = self.search_field.text.strip()
        if store is None or peer is None or not query:
            self._search_hits, self._search_at = [], -1
            self._sync_search_count()
            return
        hits = store.search_messages(query, limit=999, peer=peer)
        self._search_hits = [h["id"] for h in hits]
        self._search_at = -1
        self.search_step(1)

    def search_step(self, step: int) -> None:
        """To the next match: `step` 1 goes back in time, -1 forward."""
        if not self._search_hits:
            self._sync_search_count()
            return
        at = max(0, min(len(self._search_hits) - 1, self._search_at + step))
        self._search_at = at
        self._sync_search_count()
        self.app.open_conversation_at(self.peer, self._search_hits[at])

    def _sync_search_count(self) -> None:
        hits, at = self._search_hits, self._search_at
        query = self.search_field.text.strip()
        if not query:
            self.search_count.text = ""
        elif not hits:
            self.search_count.text = "none"
        else:
            self.search_count.text = f"{at + 1} of {len(hits)}"
        self.search_up.disabled = not hits or at >= len(hits) - 1
        self.search_down.disabled = not hits or at <= 0

    @staticmethod
    def _text_of(msg: dict) -> str:
        kind = msg.get("kind") or "text"
        if kind == "image":
            return (message_ext(msg).get("media") or {}).get("cap", "")
        if kind == "voice":
            return ""
        return msg.get("body", "")

    def _ordered(self) -> list:
        return [self.selected[i] for i in sorted(self.selected)]

    # ---- the six actions -------------------------------------------------------
    def _act_reply(self) -> None:
        if len(self.selected) == 1:
            msg = next(iter(self.selected.values()))
            self.clear_selection()
            self.set_reply(msg)

    def _act_copy(self) -> None:
        msgs = self._ordered()
        if len(msgs) == 1:
            bubble = self._bubbles.get(msgs[0]["id"])
            part = (bubble.body.selection_text if bubble is not None and
                    isinstance(bubble.body, SelectableText) else "")
            text = part or self._text_of(msgs[0])
            links = links_in(text) if not part else []
            if links:
                # v11: the text, or one of its links (to see where it leads,
                # open it, or copy it alone).
                self.clear_selection()
                items = [("copy", "Copy the text",
                          lambda: self.app.copy_text(text))]
                items += [("link", escape_markup(link_host(url)),
                           lambda u=url: self.app.open_link(u))
                          for url in links[:4]]
                MenuSheet(items, title="Copy").open()
                return
        else:
            text = "\n".join(
                f"[{pretty_time(m['created_at'])}] "
                f"{self.author_name(self._author_of(m))}: {self._text_of(m)}"
                for m in msgs if self._text_of(m))
        self.clear_selection()
        if text:
            self.app.copy_text(text)

    def _act_star(self) -> None:
        msgs = self._ordered()
        star = not all(m.get("starred") for m in msgs)
        ids = [m["id"] for m in msgs]
        self.clear_selection()
        self.app.star_messages(ids, star)
        self.app._set_status("Starred" if star else "Removed from starred",
                             T.ok)

    def _act_forward(self) -> None:
        ForwardModal(self.app, [m["id"] for m in self._ordered()],
                     on_done=self.clear_selection).open()

    def _act_share(self) -> None:
        ids = [m["id"] for m in self._ordered()]
        self.clear_selection()
        self.app.share_messages(ids)

    def _act_delete(self) -> None:
        DeleteModal(self.app, self._ordered(),
                    on_done=self.clear_selection).open()

    # ---- names and replies ---------------------------------------------------
    def _author_of(self, msg: dict) -> str:
        if msg["direction"] == "out":
            return self.app.keys.address
        return msg.get("author") or msg["peer"]

    def author_name(self, address: Optional[str],
                    outgoing_bubble: bool = False) -> str:
        """Who someone is, as this phone knows them: You, the contact's
        name, their name in a group, or their address."""
        if not address:
            return "Message"
        if address == self.app.keys.address:
            return "You"
        if address == self.peer and self.kind == "dm":
            return self.peer_name_text or short_addr(address, 12)
        store = self.app.store
        contact = store.get_contact(address) if store else None
        if contact and contact.get("username"):
            return contact["username"]
        for member in (self.group or {}).get("members") or []:
            if member.get("a") == address and member.get("u"):
                return member["u"]
        return short_addr(address, 10)

    def set_reply(self, msg: dict) -> None:
        kind = msg.get("kind") or "text"
        snip = self._text_of(msg) or {"image": "Photo",
                                      "voice": "Voice message"}.get(kind, "")
        reply = {"snip": snip[:120], "from": self._author_of(msg),
                 "kind": kind}
        if msg.get("client_msg_id"):
            reply["cid"] = msg["client_msg_id"]
        self.reply_to = reply
        self.reply_author.text = self.author_name(reply["from"])
        self.reply_snip.text = snip
        self.reply_bar.height, self.reply_bar.opacity = max(
            dp(56), self.reply_author.height + line_height(15) + dp(14)), 1
        self.reply_bar.conceal(False)
        self.entry.input.focus = True

    def take_reply(self) -> Optional[dict]:
        reply = self.reply_to
        self.cancel_reply()
        return reply

    def cancel_reply(self) -> None:
        self.reply_to = None
        self.reply_bar.height, self.reply_bar.opacity = 0, 0
        self.reply_bar.conceal(True)

    def jump_to_cid(self, cid: Optional[str]) -> None:
        """Tap on a quote: scroll to the quoted message and flash it."""
        if self.selecting or not cid:
            return
        for mid, bubble in self._bubbles.items():
            if bubble.msg.get("client_msg_id") == cid:
                row = self._rows.get(mid)
                if row is None:
                    return
                self._stick_to_bottom = False
                self.scroll.scroll_to(row, padding=dp(60),
                                      animate=bool(motion(1)))
                row.set_selected(True)
                Clock.schedule_once(
                    lambda _dt: row.set_selected(mid in self.selected), 0.9)
                return
        row = self.app.store.message_by_cid(self.peer, cid) \
            if self.peer else None
        if row is not None:
            self.app.open_conversation_at(self.peer, row["id"])
        else:
            self.app._set_status("That message is no longer on this device",
                                 T.text_3)

    # ---- taps ------------------------------------------------------------------
    def open_message_info(self, msg: dict) -> "MessageInfoSheet":
        sheet = MessageInfoSheet(self, msg)
        sheet.open()
        return sheet

    def on_face_tap(self, address: Optional[str]) -> None:
        """The disc beside a member's messages (v12): the menu their row on
        the group's page opens, without leaving the chat."""
        if not address or self.selecting:
            return
        self.close_strip()
        name = self.author_name(address)
        MenuSheet(person_items(self.app, address, name), title=name).open()

    def on_bubble_tap(self, msg_id: int, touch=None) -> None:
        """A tap on a message marks it read, and raises the reactions over
        it (v9.1.2) — unless it landed on something with a tap of its own:
        a photo, a voice note, a quote, a link or its preview, a reaction.
        Tap it again, or anywhere else, to put them away."""
        bubble = self._bubbles.get(msg_id)
        if bubble is None:
            return
        msg = bubble.msg
        if msg["direction"] == "in" and not msg["read"]:
            self.app._mark_single_read(msg["id"], msg.get("server_id"))
        if self.kind != "self" and waits_for_tap(msg) and \
                not message_ext(msg).get("media"):
            self.app.retry_message(msg["id"])           # v14 (B15)
            self.app._set_status("Trying again…", COL_TEXT_DIM)
            return
        row = self._rows.get(msg_id)
        if touch is not None and row is not None:
            # The row's handler passed its own view of the touch on.
            wx, wy = window_pos(row, *touch.pos)
            meta = bubble.meta_row
            if self.kind == "group" and bubble.outgoing and \
                    meta.parent is bubble and meta.width > 0 and \
                    meta.collide_point(*meta.to_widget(wx, wy)):
                # v12: the time and ticks of yours in a group: who has it.
                self.close_strip()
                self.open_message_info(msg)
                return
            for part in (bubble.media, bubble.quote, bubble.card,
                         bubble.reactions):
                if part is not None and part.width > 0 and part.height > 0 \
                        and part.collide_point(*part.to_widget(wx, wy)):
                    return
            url = bubble.link_at(wx, wy)
            if url:
                self.close_strip()
                self.app.open_link(url)
                return
        if self._strip_for == msg_id:
            self.close_strip()
        elif self._reactable(msg):
            self._strip_for = msg_id
            self.strip.set_choices(self.quick_reactions())
            self.strip.show(self.app.store.reactions_of(
                msg["peer"], msg["client_msg_id"], self.app.keys.address)
                if self.app.store else [])
            self._place_strip()

    def on_link_tap(self, url: str) -> None:
        if not self.selecting:
            self.close_strip()
            self.app.open_link(url)

    def close_strip(self) -> None:
        """Put away reactions raised by a tap (not those of a held one)."""
        if self._strip_for is not None:
            self._strip_for = None
            if not self.selected:
                self.strip.hide()

    def on_touch_up(self, touch):
        handled = super().on_touch_up(touch)
        # A tap off the messages (or a scroll) puts tap-raised reactions away.
        if self._strip_for is not None and not touch.ud.get("fext_row") and \
                not self.strip.collide_point(*self.strip.to_widget(
                    *window_pos(self, *touch.pos))):
            self.close_strip()
        return handled

    def on_media_tap(self, msg: dict) -> None:
        if self.selecting:
            return
        msg = self.app.store.message(msg["id"]) or msg
        state = msg.get("media_state") or ""
        path = msg.get("media_path")
        outgoing = msg["direction"] == "out"
        if state == "expired":
            self.app.request_resend(msg["id"])
        elif state == "failed" or (outgoing and state == "waiting"):
            (self.app.retry_media if outgoing else self.app.fetch_media)(
                msg["id"])
        elif state == "pending" and not outgoing:
            self.app.download_on_tap(msg)
        elif path and Path(path).is_file():
            if msg.get("kind") == "image":
                ImageViewer(path).open()
            elif msg.get("kind") == "voice":
                try:
                    self.app.voice.toggle(path)
                except Exception:
                    log.exception("could not play voice note")
                    self.app._set_status("Couldn't play that voice message",
                                         T.alert)
                self.refresh_voice_buttons()

    def seek_voice(self, msg: dict, fraction: float) -> None:
        """A drag or tap on a voice note's waveform: play it from there."""
        if self.selecting:
            return
        path = msg.get("media_path")
        try:
            self.app.voice.seek(path, fraction)
        except Exception:
            log.exception("could not play voice note")
            self.app._set_status("Couldn't play that voice message", T.alert)
        self.refresh_voice_buttons()

    def refresh_voice_buttons(self) -> None:
        for bubble in self._bubbles.values():
            if isinstance(bubble.media, VoiceContent):
                bubble.media.refresh(bubble.msg)

    def on_voice_progress(self, path: str, fraction: float) -> None:
        for bubble in self._bubbles.values():
            if isinstance(bubble.media, VoiceContent) and \
                    bubble.msg.get("media_path") == path:
                bubble.media.wave.set_progress(fraction)

    def on_voice_stop(self, path: str) -> None:
        self.on_voice_progress(path, 0.0)
        self.refresh_voice_buttons()

    # ---- the ⋮ menu ------------------------------------------------------------
    def open_menu(self, _anchor=None) -> None:
        if self.peer is None or self.app.store is None:
            return
        peer, app = self.peer, self.app
        items = [("search", "Search in this chat", self.open_search)]
        if self.app.store.unread_for(peer):
            items.append(("check", "Mark all as read",
                          lambda: app.mark_peer_read(peer)))
        if self.kind == "group":
            gid = gid_of(peer)
            items.append(("group", "Group info", app.open_chat_info))
            items.append(("star", "Starred messages",
                          lambda: StarredModal(app, peer).open()))
            muted = app.store.mute_state(peer)[0]
            items.append(("bell" if muted else "bell_off",
                          "Unmute notifications" if muted else
                          "Mute notifications…",
                          lambda: app.toggle_notify(peer)))
            items.append(("clock", "Disappearing messages…",
                          lambda: app.choose_timer(peer)))
            items.append(("share", "Export or import",
                          lambda: ChatHistorySheet(app, peer).open()))
            if (self.group or {}).get("state") == "active":
                items.append(("leave", "Leave group",
                              lambda: app.confirm_leave_group(gid), True))
        elif self.kind == "self":
            items.append(("star", "Starred notes",
                          lambda: StarredModal(app, peer).open()))
            items.append(("share", "Export or import",
                          lambda: ChatHistorySheet(app, peer).open()))
        else:
            items.append(("info", "Chat info", app.open_chat_info))
            items.append(("star", "Starred messages",
                          lambda: StarredModal(app, peer).open()))
            muted = app.store.mute_state(peer)[0]
            items.append(("bell" if muted else "bell_off",
                          "Unmute notifications" if muted else
                          "Mute notifications…",
                          lambda: app.toggle_notify(peer)))
            items.append(("clock", "Disappearing messages…",
                          lambda: app.choose_timer(peer)))
            items.append(("lock", "Verify…", lambda: app.open_verify(peer)))
            items.append(("share", "Export or import",
                          lambda: ChatHistorySheet(app, peer).open()))
        MenuSheet(items).open()

    # ---- emoji -----------------------------------------------------------------
    def toggle_emoji(self) -> None:
        if self.emoji_panel.is_open:
            self.close_emoji()
            self.entry.input.focus = True
        else:
            self._emoji_target = None
            self.open_emoji()

    def open_emoji(self) -> None:
        self.entry.input.focus = False
        self.emoji_panel.set_open(True)
        self.emoji_button.set_icon("keyboard")
        self.emoji_button.label = "Keyboard"

    def close_emoji(self) -> None:
        if self.emoji_panel.is_open:
            self.emoji_panel.set_open(False)
        self._emoji_target = None
        self.emoji_button.set_icon("smile")
        self.emoji_button.label = "Emoji"

    def _emoji_picked(self, emoji: str) -> None:
        if self._emoji_target is not None:
            target, self._emoji_target = self._emoji_target, None
            self.close_emoji()
            self.app.react(target, emoji)
            return
        self.entry.input.insert_text(emoji)

    def _on_text_changed(self) -> None:
        self._sync_composer()
        self._preview_soon()
        if self._draft_save is not None:
            self._draft_save.cancel()
        self._draft_save = Clock.schedule_once(lambda _dt: self.keep_draft(),
                                               1.2)

    def keep_draft(self) -> None:
        """Write what is in the composer as this chat's draft (or clear it)."""
        if self._draft_save is not None:
            self._draft_save.cancel()
            self._draft_save = None
        store = self.app.store
        if self.peer is None or store is None:
            return
        text = self.entry.text
        if text.strip() != store.draft(self.peer).strip() or \
                (not text.strip() and store.draft(self.peer)):
            store.set_draft(self.peer, text)
            self.app.refresh_sidebar()

    def _on_entry_focus(self, _w, focused: bool) -> None:
        if focused and self.emoji_panel.is_open and IS_MOBILE:
            self.close_emoji()

    # ---- v11: a link's preview, while writing -------------------------------
    # Only with previews turned on in Settings: a moment after a link is
    # written this device fetches its preview, shown over the composer to
    # send with the message, or to be put away (✕) and not sent.
    def _preview_soon(self) -> None:
        if not self._previews_on:
            return
        if self._preview_ev is not None:
            self._preview_ev.cancel()
        self._preview_ev = Clock.schedule_once(
            lambda _dt: self._preview_check(), 0.8)

    def _preview_check(self) -> None:
        self._preview_ev = None
        links = links_in(self.entry.text)
        if not links:
            self.cancel_preview()
            return
        url = links[0]
        if url in (self._preview_url, self._preview_dismissed):
            return
        self._preview_url, self.link_preview = url, None
        self._show_preview_bar(link_host(url), "Fetching a preview…", None)
        threading.Thread(target=self._fetch_preview, args=(url, self.peer),
                         daemon=True).start()

    def _fetch_preview(self, url: str, peer: Optional[str]) -> None:
        try:
            preview = fetch_link_preview(url)
        except Exception:
            log.exception("could not fetch a link preview")
            preview = None
        Clock.schedule_once(
            lambda _dt: self._preview_arrived(url, peer, preview))

    def _preview_arrived(self, url: str, peer: Optional[str],
                         preview: Optional[dict]) -> None:
        if url != self._preview_url or peer != self.peer:
            return                                  # the text moved on
        if preview is None:
            self._hide_preview_bar()        # none to be had: sent without
            return
        self.link_preview = preview
        self._show_preview_bar(preview.get("s") or link_host(url),
                               preview["t"], preview.get("i"))

    def dismiss_preview(self) -> None:
        self._preview_dismissed = self._preview_url
        self.link_preview = None
        self._hide_preview_bar()

    def cancel_preview(self) -> None:
        if self._preview_ev is not None:
            self._preview_ev.cancel()
            self._preview_ev = None
        self._preview_url = self._preview_dismissed = None
        self.link_preview = None
        self._hide_preview_bar()

    def take_preview(self, body: str) -> Optional[dict]:
        """The preview to send with `body` (it must be of a link in it)."""
        preview = self.link_preview
        self.cancel_preview()
        if preview and preview.get("u") in links_in(body):
            return preview
        return None

    def _show_preview_bar(self, site: str, title: str,
                          thumb: Optional[str]) -> None:
        self.preview_site.text = site
        self.preview_title.text = title
        texture = texture_from_b64(thumb) if thumb else None
        self.preview_thumb.texture = texture
        self.preview_thumb.opacity = 1 if texture is not None else 0
        self.preview_thumb.width = dp(40) if texture is not None else 0
        self.preview_bar.height = max(dp(56), self.preview_site.height +
                                      line_height(15) + dp(14))
        self.preview_bar.opacity = 1
        self.preview_bar.conceal(False)

    def _hide_preview_bar(self) -> None:
        self.preview_bar.height, self.preview_bar.opacity = 0, 0
        self.preview_bar.conceal(True)

    def _paint_bar_icon(self, widget, bar, name: str) -> None:
        widget.canvas.clear()
        with widget.canvas:
            draw_icon(name, widget.x + widget.width / 2,
                      bar.y + bar.height / 2, dp(20), C(T.accent))

    @staticmethod
    def _sync_bar_rule(widget, *_a) -> None:
        widget._rule.pos = (widget.x, widget.y + dp(3))
        widget._rule.size = (dp(2), max(0, widget.height - dp(6)))

    # ---- composer: photo, voice, send ------------------------------------------
    def _paint_reply_icon(self, widget) -> None:
        widget.canvas.clear()
        with widget.canvas:
            draw_icon("reply", (widget.x + widget.width / 2), (self.reply_bar.y + self.reply_bar.height / 2),
                      dp(20), C(T.accent))

    def _sync_reply_accent(self, widget) -> None:
        self._reply_accent.pos = (widget.x, widget.y + dp(3))
        self._reply_accent.size = (dp(2), max(0, widget.height - dp(6)))

    _can_record: Optional[bool] = None

    def _voice_possible(self) -> bool:
        if IS_ANDROID:
            return True
        if ConversationScreen._can_record is None:
            ConversationScreen._can_record = desktop_recording_available()
        return ConversationScreen._can_record

    def _refresh_me(self) -> None:
        """The disc of the identity you are writing as, left of the field."""
        keys = self.app.keys
        mine = (keys.address, keys.username, keys.label) \
            if keys.has_identity else None
        if mine == getattr(self, "_me_shown", False):
            return
        self._me_shown = mine
        self.me_holder.clear_widgets()
        if mine is None:
            return
        name = keys.username or keys.label
        me = AvatarButton(keys.address, name, diameter=dp(34),
                          pos_hint={"center_x": .5, "center_y": .5})
        me.label = f"Writing as {'@' + keys.username if keys.username else name}"
        me.bind(on_release=lambda _w: IdentitySheet(self.app).open())
        self.me_holder.add_widget(me)

    def _sync_composer(self, animate: bool = True) -> None:
        """Fit the composer to what is in it (see its layout above)."""
        quiet = not self.entry.input.text.strip()
        fold(self.me_holder, quiet, TOUCH, animate)
        self.entry.show_camera(quiet, animate)
        voice = quiet and self._voice_possible()
        icon = "mic" if voice else "send"
        if animate:
            self.action_button.morph(icon)
        else:
            self.action_button.show_icon(icon)
        self.action_button.label = "Record a voice message" if voice \
            else "Send"

    def _on_action_button(self) -> None:
        if self.recorder is not None:          # already recording
            return
        if self.entry.input.text.strip() or not self._voice_possible():
            self.app.send_current()
        else:
            self.start_recording()

    def _media_refused(self, what: str) -> bool:
        if self.kind != "self" and not self.app.media_available():
            self.app._set_status(f"{what} need the v9 relay — this one can't "
                                 "carry them yet", T.accent)
            return True
        return False

    def pick_image(self) -> None:
        if self._media_refused("Photos and voice messages"):
            return
        if IS_ANDROID:
            try:
                android_pick_image(lambda path: self._picked(path, True))
            except Exception:
                log.exception("photo picker failed")
                self.app._set_status("Couldn't open the photo picker",
                                     T.alert)
        else:
            ImageChooserModal(lambda path: self._picked(path, False)).open()

    def take_photo(self) -> None:
        if self._media_refused("Photos"):
            return
        if IS_ANDROID:
            try:
                android_take_photo(lambda path: self._picked(path, True))
            except Exception:
                log.exception("camera failed")
                self.app._set_status("Couldn't open the camera", T.alert)
        else:
            open_desktop_camera(lambda path: self._picked(path, True),
                                on_choose=self.pick_image)

    def _picked(self, path: str, temporary: bool = False) -> None:
        """A photo to send. `temporary`: a copy this app made (a picked or
        camera photo), deleted once it is sent or set aside."""
        AttachPreviewModal(self.app, path, temporary=temporary).open()

    # ---- recording: hold, slide, lock ----------------------------------------
    HOLD_TAP = 0.35        # a press shorter than this is a tap: hands-free
    CANCEL_SLIDE = dp(110)  # this far left, and the recording is deleted
    LOCK_SLIDE = dp(80)    # this far up, and it carries on hands-free

    def mic_mode(self) -> bool:
        """Is the action button the microphone (nothing written)?"""
        return not self.entry.input.text.strip() and self._voice_possible() \
            and self.recorder is None

    def hold_begin(self, touch) -> None:
        self._hold = {"t0": time.monotonic(), "x0": touch.x, "y0": touch.y}
        self.start_recording(held=True)
        if self.recorder is None:          # refused, or asking permission
            self._hold = None

    def hold_move(self, touch) -> None:
        hold = self._hold
        if hold is None or self.recorder is None or self._rec_locked:
            return
        dx, dy = touch.x - hold["x0"], touch.y - hold["y0"]
        if -dx >= self.CANCEL_SLIDE:
            self._hold = None
            self.cancel_recording()
            self.app._set_status("Recording deleted", T.text_3)
            return
        if dy >= self.LOCK_SLIDE:
            self._hold = None
            self.lock_recording()
            return
        # follow the finger: the hint slides away left, the lock rises
        left = max(0.0, -dx) / self.CANCEL_SLIDE
        self.rec_hint.opacity = 1 - 0.7 * left
        self.rec_hint.padding = [0, 0, min(dp(60), max(0.0, -dx) * 0.6), 0]
        self.lock_pill.set_rise(max(0.0, dy) / self.LOCK_SLIDE)

    def hold_end(self, touch) -> None:
        hold, self._hold = self._hold, None
        if hold is None or self.recorder is None or self._rec_locked:
            return
        if time.monotonic() - hold["t0"] < self.HOLD_TAP:
            self.lock_recording()          # a tap: record hands-free
        else:
            self.finish_recording()        # let go: send it

    def lock_recording(self) -> None:
        """Hands-free: delete · the time and level · pause · send."""
        if self.recorder is None:
            return
        self._rec_locked = True
        self._show_rec_ui()

    def toggle_pause(self) -> None:
        recorder = self.recorder
        if recorder is None or not getattr(recorder, "can_pause", False):
            return
        if getattr(recorder, "paused", False):
            recorder.resume()
        else:
            recorder.pause()
        self._sync_pause()

    def _sync_pause(self) -> None:
        paused = bool(getattr(self.recorder, "paused", False))
        self.rec_pause.set_icon("mic" if paused else "pause")
        self.rec_pause.label = "Carry on recording" if paused \
            else "Pause recording"
        Animation.cancel_all(self.rec_dot, "opacity")
        self.rec_dot.opacity = .35 if paused else 1
        if motion(1) and not paused:
            pulse = Animation(opacity=.25, d=.6, t="in_out_sine") + \
                Animation(opacity=1, d=.6, t="in_out_sine")
            pulse.repeat = True
            pulse.start(self.rec_dot)

    def _show_rec_ui(self) -> None:
        """The composer while recording: held (the time and level, the hint,
        the microphone under the finger, the lock over it) or hands-free."""
        self.close_emoji()
        self.composer.clear_widgets()
        if self._rec_locked:
            parts = [self.rec_cancel, self.rec_dot, self.rec_label,
                     self.rec_levels]
            if getattr(self.recorder, "can_pause", False):
                parts.append(self.rec_pause)
            parts.append(self.rec_send)
            self.lock_pill.hide()
        else:
            self.rec_hint.opacity, self.rec_hint.padding = 1, [0, 0, 0, 0]
            parts = [Widget(size_hint_x=None, width=dp(12)), self.rec_dot,
                     self.rec_label, self.rec_hint, self.action_holder]
            self.lock_pill.show(self.stack, self.action_holder)
        for part in parts:
            self.composer.add_widget(part)
        if not self._rec_locked:
            self.action_button.show_icon("mic")
        self.action_button.set_holding(not self._rec_locked)
        self._sync_pause()

    def start_recording(self, held: bool = False) -> None:
        if self._media_refused("Voice messages"):
            return
        if IS_ANDROID and not android_has_permission(
                "android.permission.RECORD_AUDIO"):
            android_request_permissions(
                ["android.permission.RECORD_AUDIO"],
                lambda _p, grants: run_on_ui(
                    self._after_mic_permission, bool(grants) and all(grants)))
            return
        try:
            self.recorder = VoiceRecorder() if IS_ANDROID else PcmRecorder()
        except Exception as exc:
            log.warning("could not start recording: %s", exc)
            self.recorder = None
            self.app._set_status("Couldn't start recording — is a "
                                 "microphone connected?", T.alert)
            return
        self._rec_locked = not held
        self._show_rec_ui()
        self._rec_tick = Clock.schedule_interval(self._update_rec_label, 0.1)
        self._update_rec_label(0)

    def _after_mic_permission(self, granted: bool) -> None:
        if granted:
            self.start_recording()
        else:
            self.app._set_status("Voice messages need the microphone "
                                 "permission", T.accent)

    def _paint_rec_dot(self, dot, *_a) -> None:
        dot.canvas.clear()
        r = dp(5)
        with dot.canvas:
            Color(*C(T.alert))
            SmoothEllipse(pos=(dot.x + dot.width / 2 - r,
                               dot.y + dot.height / 2 - r),
                          size=(2 * r, 2 * r))

    def _update_rec_label(self, _dt) -> None:
        recorder = self.recorder
        if recorder is None:
            return
        if getattr(recorder, "failed", False) and recorder.elapsed_ms == 0:
            self.cancel_recording()
            self.app._set_status("No sound came from the microphone",
                                 T.alert)
            return
        sec = recorder.elapsed_ms // 1000
        self.rec_label.text = f"{sec // 60}:{sec % 60:02d}"
        self.rec_levels.update(list(recorder.levels))
        if sec >= getattr(recorder, "max_seconds", MAX_VOICE_SECONDS):
            self.finish_recording()

    def _end_recording_ui(self) -> None:
        if self._rec_tick is not None:
            self._rec_tick.cancel()
            self._rec_tick = None
        Animation.cancel_all(self.rec_dot, "opacity")
        self._hold, self._rec_locked = None, False
        self.lock_pill.hide()
        self.action_button.set_holding(False)
        self.composer.clear_widgets()
        for part in self.composer_parts:
            self.composer.add_widget(part)
        self._sync_composer(animate=False)

    def finish_recording(self) -> None:
        recorder, self.recorder = self.recorder, None
        if recorder is None:
            return
        self._end_recording_ui()
        try:
            path, duration, wave = recorder.stop()
        except Exception:
            log.exception("recording failed")
            self.app._set_status("Recording failed", T.alert)
            return
        if duration < 700:
            discard_media_file(path)
            self.app._set_status("That was too short to send", T.text_3)
            return
        self.app.send_voice(path, duration, wave)

    def cancel_recording(self) -> None:
        recorder, self.recorder = self.recorder, None
        if recorder is None:
            return
        self._end_recording_ui()
        recorder.cancel()

    # ---- bottom alignment ----------------------------------------------------
    def content_height(self) -> float:
        """Height of the real messages, without the bottom-align filler."""
        return self.messages.minimum_height - self._filler.height

    def _sync_filler(self) -> None:
        """Pin a short conversation to the BOTTOM of the viewport.

        Kivy lays a ScrollView's content out from the TOP when it is shorter
        than the viewport, and with always_overscroll the same branch runs
        for ANY scroll_y above zero — so one stray touch lifted a two-line
        chat up under the app bar. Padding the top until the content is at
        least viewport-tall makes that case impossible; a chat that really
        overflows is untouched (the filler collapses to zero).
        """
        if self._syncing_filler:
            return
        self._syncing_filler = True
        try:
            want = max(0.0, self.scroll.height - self.content_height())
            if abs(self._filler.height - want) > 0.5:
                self._filler.height = want
        finally:
            self._syncing_filler = False

    # ---- scroll position -----------------------------------------------------
    BOTTOM_EPSILON = 0.02

    def at_bottom(self) -> bool:
        """True when the newest message is on screen. A conversation that
        does not fill the viewport always is."""
        if self.content_height() <= self.scroll.height:
            return True
        return self.scroll.scroll_y <= self.BOTTOM_EPSILON

    def scroll_to_bottom(self, animate: bool = True) -> None:
        """Bring the newest message into view, once, on the frame after
        layout — one pending settle at a time."""
        self._stick_to_bottom = True
        self._stick_to_line = False

        def _apply(_dt):
            self._scroll_trigger = None
            Animation.cancel_all(self.scroll, "scroll_y")
            if not animate or not motion(1) or \
                    self.content_height() <= self.scroll.height:
                self.scroll.scroll_y = 0
            else:
                Animation(scroll_y=0, d=0.22, t="out_quad").start(self.scroll)
            self._unseen = 0
            self._sync_jump_button()

        if self._scroll_trigger is not None:
            self._scroll_trigger.cancel()
        self._scroll_trigger = Clock.schedule_once(_apply, 0.02)

    def jump_to_latest(self) -> None:
        self._unseen = 0
        if self.reading_back():
            self.app.reopen_live()
            return
        self.scroll_to_bottom(animate=True)

    def _on_content_height(self) -> None:
        """Following the conversation: stay pinned to the newest message.
        Reading history: hold the reading position as the content grows."""
        old_h, new_h = self._last_content_h, self.messages.height
        self._last_content_h = new_h
        view = self.scroll.height
        if self._stick_to_line:
            self._line_soon()
            return
        if self._stick_to_bottom:
            if self.scroll.scroll_y != 0:
                self.scroll.scroll_y = 0
            return
        old_span, new_span = old_h - view, new_h - view
        if old_span > 0 and new_span > 0 and abs(new_h - old_h) > 0.5:
            offset_px = self.scroll.scroll_y * old_span
            self.scroll.scroll_y = max(0.0, min(1.0, offset_px / new_span))

    def reading_back(self) -> bool:
        """Is a window short of the conversation's end showing?"""
        return getattr(self.app, "_chat_ceiling", None) is not None

    #: How long the floating day stays once scrolling stops (v12).
    DAY_FLOAT_HOLD = 1.4

    def float_day(self) -> None:
        """The day of the topmost message in view, floating over the top of
        the chat — unless that day's own divider is showing there."""
        if self.content_height() <= self.scroll.height:
            self.day_float.hide()
            return
        # The rows' places are the content's own (the view slides over it):
        # the top of what is in view, in those terms.
        top = self.scroll.scroll_y * max(
            0.0, self.messages.height - self.scroll.height) + \
            self.scroll.height
        day, first = None, None
        for widget in reversed(self.messages.children):
            if isinstance(widget, DayDivider):
                day = widget.day_text
            if widget.y < top - dp(2) and isinstance(
                    widget, (DayDivider, BubbleRow, EventRow,
                             NewMessagesLine)):
                first = widget
                break
        if first is None or day is None or (
                isinstance(first, DayDivider) and
                first.top > top - dp(40)):
            self.day_float.hide()
            return
        self.day_float.show(day)
        Clock.unschedule(self.day_float.hide)
        Clock.schedule_once(self.day_float.hide, self.DAY_FLOAT_HOLD)

    def _on_scrolled(self) -> None:
        if getattr(self, "_user_scrolling", False) or self.day_float.shown:
            self.float_day()
        if self.reading_back():                     # a window further back
            self._stick_to_bottom = False
            self._sync_jump_button()
            if self.scroll.scroll_y <= self.BOTTOM_EPSILON and \
                    self.content_height() > self.scroll.height:
                self.app.load_newer_messages()
            return
        if self.at_bottom():
            self._unseen = 0
            self._stick_to_bottom = True
        else:
            self._stick_to_bottom = False
        self._sync_jump_button()
        if self.has_older and self._backfill_ev is None and \
                self.scroll.scroll_y >= 0.98 and \
                self.content_height() > self.scroll.height:
            self.app.load_older_messages()

    def cancel_pending_scroll(self) -> None:
        """Hand scroll control back to the user: the queued settle, any
        easing, and the damped overscroll's residual momentum."""
        if self._scroll_trigger is not None:
            self._scroll_trigger.cancel()
            self._scroll_trigger = None
        Animation.cancel_all(self.scroll, "scroll_y")
        self._stick_to_bottom = False
        self._stick_to_line = False
        effect = getattr(self.scroll, "effect_y", None)
        if effect is not None:
            try:
                effect.velocity = 0
                effect.stop(effect.value)
            except Exception:
                pass

    def _sync_jump_button(self) -> None:
        self.jump_button.set_count(self._unseen)
        self.jump_button.set_visible(not self.at_bottom() or
                                     self._unseen > 0 or self._newer > 0)

    def note_new_messages(self, count: int) -> None:
        """Announce arrivals while reading history — without moving."""
        if count > 0:
            self._unseen += count
        self._stick_to_bottom = False
        self._sync_jump_button()

    @staticmethod
    def _day_text(day: str) -> str:
        try:
            date = datetime.fromisoformat(day).date()
        except ValueError:
            return day
        delta = (datetime.now().date() - date).days
        if delta == 0:
            return "Today"
        if delta == 1:
            return "Yesterday"
        if 1 < delta < 7:
            return date.strftime("%A")
        if date.year == datetime.now().year:
            return f"{date.day} {date.strftime('%B')}"
        return f"{date.day} {date.strftime('%B %Y')}"

    def _empty_state(self) -> BoxLayout:
        if self.kind == "self":
            text = ("Saved messages. Whatever you write, forward or "
                    "photograph here stays on this device and goes nowhere.")
        elif self.kind == "group":
            text = ("The beginning of the group. Each message is sealed "
                    "separately for every member before it leaves.")
        else:
            text = ("The beginning of your correspondence. Messages are "
                    "sealed on this device before they leave it.")
        box = BoxLayout(orientation="vertical", size_hint_y=None,
                        padding=[dp(36), dp(28), dp(36), dp(8)],
                        spacing=dp(10))
        box.bind(minimum_height=box.setter("height"))
        box.add_widget(InfoLabel(FLEURON, color=T.accent, font_size=fs(26),
                                 halign="center"))
        box.add_widget(InfoLabel(text, color=T.text_3, italic=True,
                                 font_size=fs(15.5), halign="center"))
        return box


# =============================================================================
#  Info, groups, settings
# =============================================================================
class PageScreen(SwipeGestures, Screen):
    """A titled page: app bar with back, and a scrolling column."""

    def __init__(self, app: "FextApp", name: str, title: str,
                 on_back: Callable, **kw):
        super().__init__(name=name, **kw)
        self.app = app
        root = BoxLayout(orientation="vertical")
        paint_round(root, T.bg, radius=0)
        self.add_widget(root)
        self.appbar = AppBar(title, on_back=on_back)
        root.add_widget(self.appbar)
        self.scroll = ScrollView(bar_width=dp(3), do_scroll_x=False)
        self.body = BoxLayout(orientation="vertical", size_hint_y=None,
                              padding=[0, 0, 0, dp(28)])
        self.body.bind(minimum_height=self.body.setter("height"))
        self.scroll.add_widget(self.body)
        root.add_widget(self.scroll)
        self.root_box = root

    def paragraph(self, text: str, italic: bool = False) -> InfoLabel:
        label = InfoLabel(text, color=T.text_3, font_size=fs(15),
                          italic=italic, padding=[dp(20), dp(8)])
        self.body.add_widget(label)
        return label

    def swipe_kind(self, touch, dx: float) -> Optional[str]:
        """Anywhere on a page, a swipe to the right goes back."""
        return "back" if dx > 0 else None

    def _timer_row(self, peer: str, can_set: bool = True) -> "ListRow":
        """Disappearing messages: off, or how long — tap to change."""
        seconds = self.app.store.chat_timer(peer)[0]
        value = (timer_label(seconds) + " after reading") if seconds \
            else "Off"
        if not can_set:
            value += " · set by the group's admin"
        return ListRow("clock", "Disappearing messages", value,
                       chevron=can_set,
                       on_tap=(lambda: self.app.choose_timer(peer))
                       if can_set else None)

    def _mute_row(self, peer: str) -> "ListRow":
        """Notifications: on, or muted until when — tap to change."""
        muted, until = self.app.store.mute_state(peer)
        return ListRow("bell_off" if muted else "bell", "Notifications",
                       mute_label(until) if muted else
                       "On · muting keeps messages coming, quietly",
                       chevron=True,
                       on_tap=lambda: self.app.choose_mute([peer]))

    def hero(self, seed: str, name: str, kind: str, sub: str = "",
             on_sub: Optional[Callable] = None, on_name=None,
             on_avatar: Optional[Callable] = None,
             editable: bool = False) -> None:
        """The big disc, the name, and a line beneath (tap to copy). With
        `on_avatar` the disc is a button; `editable` marks it with a camera,
        for a picture that can be changed."""
        head = BoxLayout(orientation="vertical", size_hint_y=None,
                         padding=[dp(20), dp(26), dp(20), dp(16)],
                         spacing=dp(8))
        head.bind(minimum_height=head.setter("height"))
        holder = AnchorLayout(size_hint_y=None, height=dp(96))
        if on_avatar is not None:
            self.hero_disc = AvatarButton(seed, name, diameter=dp(92),
                                          kind=kind, size=(dp(96), dp(96)))
            self.hero_disc.bind(on_release=lambda _w: on_avatar())
            if editable:
                self.hero_disc.bind(pos=self._badge, size=self._badge)
                self._badge(self.hero_disc)
        else:
            self.hero_disc = Avatar(seed, name, diameter=dp(92), kind=kind)
        holder.add_widget(self.hero_disc)
        head.add_widget(holder)
        title = InfoLabel(name, font_size=fs(25), halign="center")
        if on_name is not None:
            box = TappableBox(on_tap=on_name, size_hint_y=None,
                              padding=[0, dp(6)])
            box.bind(minimum_height=lambda w, v: setattr(
                w, "height", max(TOUCH, v)))
            box.add_widget(title)
            head.add_widget(box)
        else:
            head.add_widget(title)
        if sub:
            line = TappableBox(on_tap=on_sub, size_hint_y=None, height=TOUCH)
            label = single_line(sub, fs(15), T.text_3, italic=True,
                                halign="center")
            line.add_widget(label)
            if on_sub is not None:
                line.bind(state=lambda _w, s: setattr(
                    label, "color", C(T.accent if s == "down" else T.text_3)))
            head.add_widget(line)
        self.body.add_widget(head)
        self.body.add_widget(Rule())

    @staticmethod
    def _badge(disc, *_a) -> None:
        """A small gold disc with a camera, on the picture's lower right."""
        disc.canvas.after.clear()
        radius, gap = dp(15), dp(2.5)
        cx = disc.center_x + dp(46) * .7
        cy = disc.center_y - dp(46) * .7
        with disc.canvas.after:
            Color(*C(T.bg))
            SmoothEllipse(pos=(cx - radius - gap, cy - radius - gap),
                          size=(2 * (radius + gap), 2 * (radius + gap)))
            Color(*C(T.accent))
            SmoothEllipse(pos=(cx - radius, cy - radius),
                          size=(2 * radius, 2 * radius))
            draw_icon("camera", cx, cy, radius * 1.15, C(T.on_accent))


class ChatInfoScreen(PageScreen):
    """A direct chat's (or notes to self's) page: who this is, and the
    switches for it — notifications, ticks, auto-read — starred messages
    and export. A group's page is GroupInfoScreen."""

    def __init__(self, app: "FextApp", **kw):
        super().__init__(app, "info", "About this chat",
                         lambda: app.close_chat_info(), **kw)
        self.peer: Optional[str] = None

    def _pq_row(self, peer: str) -> "ListRow":
        """v15: which way this chat is sealed post-quantum. Our messages are
        once we hold their key; theirs once they have shown they hold ours.
        Each side's key reaches the other in its next message."""
        ours = self.app.store.pq_key(peer) is not None
        theirs = self.app.store.pq_mine(peer) == self.app.keys.pq_kid
        hint = ("On, both ways" if ours and theirs else
                "On for yours · theirs after your next message" if ours else
                "On for theirs · yours after their next message" if theirs
                else "Off · on once you have both written from Ferritext 15")
        return ListRow("key", "Post-quantum encryption", hint)

    def show(self, peer: str) -> None:
        self.peer = peer
        store = self.app.store
        self.body.clear_widgets()
        kind = self.app.conversation_kind(peer)
        if kind == "self":
            self.appbar.title.text = "Saved messages"
            self.hero(peer, "Saved messages", "self",
                      "Kept on this device only")
            starred = len(store.starred(peer))
            self.body.add_widget(rows_card([
                ListRow("star", "Starred notes",
                        f"{starred} note{'s' if starred != 1 else ''}",
                        chevron=True,
                        on_tap=lambda: StarredModal(self.app, peer).open()),
                ListRow("share", "Export or import",
                        "Plaintext copies, kept on this device",
                        chevron=True,
                        on_tap=lambda: ChatHistorySheet(self.app,
                                                        peer).open())]))
            self.paragraph("Nothing written here is sent anywhere. Photos "
                           "and voice messages stay on this phone too; "
                           "forwarding one to a chat sends it then.",
                           italic=True)
            return
        self.appbar.title.text = "About this chat"
        contact = store.get_contact(peer) or {}
        name = contact.get("username") or short_addr(peer, 14)
        self.hero(peer, name, "dm", short_addr(peer, 22),
                  on_sub=lambda: self.app.copy_text(peer),
                  on_avatar=lambda: self.app.view_picture(peer))
        self.body.add_widget(SectionHead("This chat"))
        self.body.add_widget(rows_card([
            ListRow("phone", "Voice call", "Sealed end to end, like the "
                    "messages", on_tap=lambda: self.app.start_call(peer)),
            self._mute_row(peer),
            self._timer_row(peer),
            ListRow("lock", "Verify " + name,
                    ("Verified — you compared codes" if contact.get(
                        "verified") else
                     "Not verified · compare a code in person, or on a call"),
                    chevron=True, on_tap=lambda: self.app.open_verify(peer)),
            self._pq_row(peer),
            ListRow("check", "Delivery and read ticks",
                    "Off on either side caps both at one tick",
                    control=ToggleSwitch(contact.get("ticks_enabled", 1),
                                         lambda on: self.app.set_ticks(peer,
                                                                       on))),
            ListRow("info", "Mark as read automatically",
                    "When off, tap a message to mark it read",
                    control=ToggleSwitch(contact.get("auto_read", 1),
                                         lambda on: self.app.set_auto_read(
                                             peer, on))),
        ]))
        starred = len(store.starred(peer))
        self.body.add_widget(SectionHead("Kept here"))
        self.body.add_widget(rows_card([
            ListRow("star", "Starred messages",
                    f"{starred} message{'s' if starred != 1 else ''}",
                    chevron=True,
                    on_tap=lambda: StarredModal(self.app, peer).open()),
            ListRow("share", "Export or import",
                    "Plaintext copies, kept on this device", chevron=True,
                    on_tap=lambda: ChatHistorySheet(self.app, peer).open()),
        ]))
        held = store.held_count(peer) if store.is_blocked(peer) else 0
        if held:
            self.paragraph(f"Blocked. {held} message{'s are' if held != 1 else ' is'} "
                           f"kept here unopened, to arrive if you unblock "
                           f"them.", italic=True)
        caps = contact.get("caps", 0) & LocalStore.CAP_V9
        self.paragraph(
            "Sealed end to end. " +
            ("They run Ferritext 9 or later: replies, photos, voice "
             "messages, reactions and delete-for-both all reach them."
             if caps else
             "Replies, photos, voice messages, reactions and "
             "delete-for-both reach them fully once they run Ferritext 9."),
            italic=True)


class NewGroupScreen(PageScreen):
    """Name a group and choose who is in it."""

    def __init__(self, app: "FextApp", **kw):
        super().__init__(app, "new_group", "New group",
                         lambda: app.go_back_to_chats(), **kw)
        self.rows: list = []

    def show(self) -> None:
        self.body.clear_widgets()
        box = BoxLayout(orientation="vertical", size_hint_y=None,
                        padding=[dp(20), dp(18), dp(20), dp(6)])
        box.bind(minimum_height=box.setter("height"))
        self.name_field = Field(hint="What is it called?", label="Group name",
                                on_enter=lambda: None)
        self.name_field.input.bind(text=lambda *_a: self._sync())
        box.add_widget(self.name_field)
        self.body.add_widget(box)
        self.count = SectionHead("Members")
        self.body.add_widget(self.count)
        contacts = self.app.store.contacts() if self.app.store else []
        self.rows = [ContactPickRow(c, on_change=lambda _r: self._sync())
                     for c in contacts]
        if self.rows:
            self.body.add_widget(rows_card(self.rows, inset=dp(74)))
        else:
            self.paragraph("Add contacts first — a group is made of people "
                           "you already know.", italic=True)
        holder = BoxLayout(size_hint_y=None, height=TOUCH + dp(36),
                           padding=[dp(20), dp(18), dp(20), dp(0)])
        self.create = Btn("Create group", on_release=lambda _w: self._go())
        holder.add_widget(self.create)
        self.body.add_widget(holder)
        self.status = self.paragraph("", italic=True)
        self._sync()

    def _sync(self) -> None:
        n = sum(1 for r in self.rows if r.picked)
        room = MAX_GROUP_MEMBERS - 1
        self.count.caps.text = f"Members · {n} of up to {room}"
        self.create.disabled = not (self.name_field.text.strip() and
                                    1 <= n <= room)

    def _go(self) -> None:
        members = [r.address for r in self.rows if r.picked]
        peer = self.app.create_group(self.name_field.text, members)
        if peer is None:
            self.status.text = "Choose a name and at least one member."
            return
        self.app.open_conversation(peer)


def person_items(app: "FextApp", address: str, name: str) -> list:
    """What a menu offers for someone in a group: a message, or, for
    someone known only from the group, adding them to your contacts."""
    contact = app.store.get_contact(address)
    if contact and contact.get("listed", 1):
        return [("send", f"Message {name}",
                 lambda: app.open_conversation(address))]
    return [("person_add", f"Add {name} to your contacts",
             lambda: app.list_contact(address))]


class GroupInfoScreen(PageScreen):
    """A group's page: its name (the admin may change it), its members
    (the admin may add and remove them), notifications, starred messages,
    and leaving."""

    def __init__(self, app: "FextApp", **kw):
        super().__init__(app, "group_info", "Group",
                         lambda: app.close_chat_info(), **kw)
        self.gid: Optional[str] = None

    def show(self, gid: str) -> None:
        self.gid = gid
        app, store = self.app, self.app.store
        group = store.group(gid) or {"name": "Group", "members": [],
                                     "admin": "", "state": "pending"}
        me = app.keys.address
        admin = group.get("admin") == me and group.get("state") == "active"
        peer = group_peer(gid)
        self.body.clear_widgets()
        members = group.get("members") or []
        self.hero(peer, group.get("name") or "Group", "group",
                  f"{len(members)} member{'s' if len(members) != 1 else ''}",
                  on_name=(lambda: self._rename(group)) if admin else None,
                  on_avatar=(lambda: app.picture_menu(gid)) if admin else
                  (lambda: app.view_picture(peer)), editable=admin)
        state = group.get("state")
        if state != "active":
            self.paragraph({"left": "You left this group. Its history stays "
                                    "here, read-only.",
                            "removed": "You were removed from this group. "
                                       "Its history stays here, read-only.",
                            "pending": "Messages arrived for this group "
                                       "before its invitation; they will "
                                       "join it when that arrives."
                            }.get(state, ""), italic=True)
        self.body.add_widget(SectionHead("This group"))
        rows = [self._mute_row(peer), self._timer_row(
            peer, can_set=group.get("admin") == me)]
        if admin:
            rows.append(ListRow("edit", "Rename the group",
                                group.get("name") or "", chevron=True,
                                on_tap=lambda: self._rename(group)))
            rows.append(ListRow("camera", "Group photo",
                                "Every member sees it", chevron=True,
                                on_tap=lambda: app.picture_menu(gid)))
        starred = len(store.starred(peer))
        rows.append(ListRow("star", "Starred messages",
                            f"{starred} message{'s' if starred != 1 else ''}",
                            chevron=True,
                            on_tap=lambda: StarredModal(app, peer).open()))
        self.body.add_widget(rows_card(rows))
        head = SectionHead(f"Members · {len(members)}")
        self.body.add_widget(head)
        member_rows = []
        if admin and len(members) < MAX_GROUP_MEMBERS:
            member_rows.append(ListRow("person_add", "Add members",
                                       "From your contacts",
                                       on_tap=lambda: AddMembersSheet(
                                           app, gid).open()))
        for m in sorted(members, key=lambda m: (m["a"] != me,
                                                m["a"] != group.get("admin"),
                                                (m.get("u") or "").lower())):
            address = m["a"]
            name = "You" if address == me else \
                app.conversation_screen.author_name(address) \
                if app.conversation_screen.peer == peer else \
                (store.get_contact(address) or {}).get("username") or \
                m.get("u") or short_addr(address, 12)
            tags = BoxLayout(size_hint=(None, None), height=dp(20),
                             spacing=dp(8))
            width = 0
            if address == group.get("admin"):
                tag = caps_tag("Admin")
                tags.add_widget(tag)
                width += tag.width
            tags.width = width
            tap = None
            if admin and address != me:
                tap = (lambda a=address, n=name: self._member_menu(a, n))
            elif address != me:
                tap = (lambda a=address, n=name: self._member_menu(a, n,
                                                                   False))
            member_rows.append(PersonRow(address, name,
                                         short_addr(address, 18), on_tap=tap,
                                         trailing=tags if width else None,
                                         initial_from=m.get("u") or name))
        self.body.add_widget(rows_card(member_rows, inset=dp(76)))
        if state == "active":
            self.body.add_widget(Rule())
            self.body.add_widget(rows_card([ListRow(
                "leave", "Leave group", "Your copy of its history stays",
                danger=True,
                on_tap=lambda: app.confirm_leave_group(gid))]))
        self.paragraph("Each message is sealed separately for every member "
                       "and signed by its author, so no one — the relay "
                       "included — can forge or read it. Groups hold up to "
                       f"{MAX_GROUP_MEMBERS} people.", italic=True)

    def _rename(self, group: dict) -> None:
        gid = group["gid"]
        TextPromptSheet("Rename group", "Group name", group.get("name", ""),
                        "Every member sees the new name.",
                        lambda name: self._renamed(gid, name),
                        limit=MAX_GROUP_NAME).open()

    def _renamed(self, gid: str, name: str) -> bool:
        self.app.rename_group(gid, name)
        self.show(gid)
        return True

    def _member_menu(self, address: str, name: str, admin: bool = True):
        items = person_items(self.app, address, name)
        if admin:
            items.append(("delete", f"Remove {name} from the group",
                          lambda: self._remove(address), True))
        MenuSheet(items, title=name).open()

    def _remove(self, address: str) -> None:
        if self.app.remove_group_member(self.gid, address):
            self.show(self.gid)


class MessageInfoSheet(Sheet):
    """Where a message of yours in a group has got to (v12): who has read
    it, who has it, who it is on its way to."""

    TIERS = ((3, "Read by"), (2, "Delivered to"), (1, "On its way to"),
             (0, "Not sent yet to"))

    def __init__(self, screen, msg: dict) -> None:
        text = single_line_text(message_text(msg) or {
            "image": "Photo", "voice": "Voice message"}.get(
                msg.get("kind"), "Message"), 60)
        super().__init__("Message info", subtitle=f"\u201c{text}\u201d")
        store = screen.app.store
        sends = store.group_sends(msg["id"]) if store is not None else []
        self.counts = {}
        for tier, heading in self.TIERS:
            people = [r["member"] for r in sends
                      if min(3, int(r.get("status") or 0)) == tier]
            self.counts[tier] = len(people)
            if not people:
                continue
            self.add(CapsLabel(f"{heading} \u00b7 {len(people)}", size=10.5,
                               color=T.accent))
            self.add(rows_card([PersonRow(m, screen.author_name(m),
                                          short_addr(m, 18))
                                for m in people], inset=dp(76)))
        if sends and not self.counts.get(3):
            self.add(InfoLabel("Someone who has turned read receipts off "
                               "shows here as delivered, at most.",
                               color=T.text_3, italic=True))


class AddMembersSheet(Sheet):
    """The admin adds contacts to a group."""

    def __init__(self, app: "FextApp", gid: str) -> None:
        super().__init__("Add members")
        self.app, self.gid = app, gid
        self.card.padding = [0, dp(8), 0, dp(18)]
        self.title_label.padding = [dp(22), 0]
        group = app.store.group(gid) or {"members": []}
        have = {m["a"] for m in group["members"]}
        self.room = MAX_GROUP_MEMBERS - len(have)
        self.rows = [ContactPickRow(c, on_change=lambda _r: self._sync())
                     for c in app.store.contacts() if c["address"] not in have]
        if self.rows:
            self.add(rows_card(self.rows, inset=dp(74)))
        else:
            self.add(InfoLabel("Everyone in your contacts is already here.",
                               color=T.text_3, italic=True, font_size=fs(15),
                               padding=[dp(22), 0]))
        holder = BoxLayout(size_hint_y=None, height=TOUCH,
                           padding=[dp(22), 0])
        self.button = Btn("Add", on_release=lambda _w: self._go())
        holder.add_widget(self.button)
        self.add(holder)
        self._sync()

    def _sync(self) -> None:
        n = sum(1 for r in self.rows if r.picked)
        self.button.disabled = not 1 <= n <= self.room
        self.button.text = "Add" if n <= 1 else f"Add {n} people"

    def _go(self) -> None:
        picked = [r.address for r in self.rows if r.picked]
        self.dismiss()
        if self.app.add_group_members(self.gid, picked):
            self.app.group_info_screen.show(self.gid)


class SettingsScreen(PageScreen):
    """Settings: how the app looks and moves, notifications, and the way to
    this identity's profile and keys."""

    def __init__(self, app: "FextApp", **kw):
        super().__init__(app, "settings", "Settings",
                         lambda: app.close_settings(), **kw)

    def show(self) -> None:
        self.body.clear_widgets()
        app = self.app
        self.body.add_widget(SectionHead("Appearance"))
        sys_dark = system_prefers_dark()
        # What each choice shows in its icon (StateIcon).
        theme_at = {"light": 0.0, "system": 0.5, "dark": 1.0}
        size_at = {k: i / (len(TEXT_SCALES) - 1)
                   for i, (k, _l, _s) in enumerate(TEXT_SCALES)}

        def chose(what, glyph_of, value, at):
            app.set_appearance(**{what: value})
            glyph_of().go(at)
        theme = self._picker("theme", "Theme", Segmented(
            THEME_CHOICES, APPEARANCE.mode,
            lambda v: chose("theme", lambda: theme.row.glyph, v,
                            theme_at[v])), theme_at[APPEARANCE.mode])
        theme.add_widget(InfoLabel(
            "System follows your phone's setting" +
            ("" if sys_dark is None else
             f" (now {'dark' if sys_dark else 'light'})") + ".",
            color=T.text_3, italic=True, font_size=fs(14.5)))
        current = next((k for k, _l, s in TEXT_SCALES
                        if abs(s - APPEARANCE.scale) < .01), "default")
        size = self._picker("text_size", "Text size", Segmented(
            [(k, label) for k, label, _s in TEXT_SCALES], current,
            lambda v: chose("text_size", lambda: size.row.glyph, v,
                            size_at[v])), size_at[current])
        size.add_widget(InfoLabel(
            "“See you at nine?” — this size, 14:05 👍",
            font_size=fs(17), padding=[0, dp(6)]))
        self.body.add_widget(rows_card([theme.row, size.row]))
        self.body.add_widget(Rule(inset=dp(60)))
        black = ListRow(
            "moon", "Black background",
            "The dark theme on a black page: deeper at night, and it saves "
            "battery on OLED screens. Off: a warm dark grey",
            control=ToggleSwitch(APPEARANCE.black, lambda on: chose(
                "black", lambda: black.glyph, on, float(on))),
            state=float(APPEARANCE.black))
        motion = ListRow(
            "motion", "Reduce motion",
            "Pages cross-fade instead of sliding; sheets, reactions and "
            "scrolling move without animation",
            control=ToggleSwitch(APPEARANCE.reduce_motion, lambda on: chose(
                "reduce_motion", lambda: motion.glyph, on, float(on))),
            state=float(APPEARANCE.reduce_motion))
        self.body.add_widget(rows_card([black, motion]))
        self.body.add_widget(SectionHead("Notifications"))
        if IS_ANDROID or os.environ.get("FEXT_SHOW_ANDROID_SETTINGS"):
            rows = [ListRow(
                "bell", "Receive messages while closed",
                "A small service keeps listening after Android closes the "
                "app; Android shows it as running. Off saves battery — you "
                "are then only notified while Ferritext is open.",
                control=ToggleSwitch(background_delivery_enabled(),
                                     self._on_delivery))]
            if not android_full_screen_allowed():
                rows.append(ListRow(
                    "phone", "Let calls ring over the lock screen",
                    "Android asks you to allow it: until then a call rings "
                    "as a notification only", chevron=True,
                    on_tap=android_open_full_screen_settings))
            self.body.add_widget(rows_card(rows))
        else:
            self.body.add_widget(rows_card([ListRow(
                "bell", "Notifications on this computer",
                "The system's own, while Ferritext's window is not in "
                "front; muted chats stay quiet",
                control=ToggleSwitch(desktop_notifications_enabled(),
                                     lambda on: save_pref(
                                         "desktop_notifications", bool(on))))]))
        self.body.add_widget(InfoLabel(
            "A muted chat still receives everything and shows it here; only "
            "its notifications stop. Mute one for 12 hours, 3 days, or until "
            "you turn it back on, from its page or by holding it in the list.",
            color=T.text_3, italic=True, font_size=fs(14.5),
            padding=[dp(20), dp(4)]))
        if not IS_MOBILE:
            self.body.add_widget(SectionHead("Calls and voice notes"))
            rows = []
            for kind, title in (("input", "Microphone"), ("output",
                                                          "Speaker")):
                rows.append(ListRow(
                    "mic" if kind == "input" else "speaker", title,
                    chosen_device(kind) or "The system's own", chevron=True,
                    on_tap=lambda k=kind: self._choose_device(k)))
            self.body.add_widget(rows_card(rows))
            echo = use_system_echo_cancel()
            self.body.add_widget(InfoLabel(
                ("Echo is cancelled by your system (" + echo + ")."
                 if echo else
                 "Echo cancelling comes from your computer or headset: with "
                 "headphones, a headset, or a speakerphone that cancels echo "
                 "itself, the other side never hears themselves. On Linux, "
                 "PulseAudio's or PipeWire's echo-cancel module is used "
                 "whenever it is on.") +
                ("" if _has_sounddevice() else
                 " Install sounddevice to choose the devices here."),
                color=T.text_3, italic=True, font_size=fs(14.5),
                padding=[dp(20), dp(4)]))
        self.body.add_widget(SectionHead("Privacy"))
        self.body.add_widget(rows_card([ListRow(
            "link", "Link previews",
            "When you write a link, this device fetches its title and "
            "picture from the site (which sees the request) and sends them "
            "with the message. Off: nothing is fetched, and previews others "
            "send are not shown.",
            control=ToggleSwitch(link_previews_enabled(),
                                 self._on_previews)),
            ListRow("block", "Blocked",
                    self._blocked_hint(), chevron=True,
                    on_tap=lambda: self._open_blocked())]))
        self.body.add_widget(SectionHead("Downloads"))

        def pref(key):
            return ToggleSwitch(download_pref(key),
                                lambda on, k=key: save_pref(k, bool(on)))
        rows = [ListRow(
            "group", "Photos in large groups on tap",
            f"In groups of more than {LARGE_GROUP}, a photo downloads when "
            f"you tap it; its small preview shows at once",
            control=pref("dl_large_groups_tap"))]
        if IS_ANDROID or os.environ.get("FEXT_SHOW_ANDROID_SETTINGS"):
            rows = [ListRow(
                "image", "Photos on mobile data",
                "Off: while not on Wi-Fi, photos wait for a tap",
                control=pref("dl_photos_metered")), ListRow(
                "mic", "Voice messages on mobile data",
                "Off: while not on Wi-Fi, they wait for a tap",
                control=pref("dl_voice_metered"))] + rows + [ListRow(
                "download", "Ask before using mobile data",
                "When you tap to download while not on Wi-Fi",
                control=pref("ask_metered"))]
        self.body.add_widget(rows_card(rows))
        self.body.add_widget(SectionHead("Backup"))
        self.body.add_widget(rows_card([
            ListRow("archive", "Back up to a file",
                    "Your identities and chats, sealed with a passphrase",
                    chevron=True, on_tap=lambda: BackupSheet(app).open()),
            ListRow("unarchive", "Restore from a backup",
                    "Adds the identities in a backup to this device",
                    chevron=True, on_tap=lambda: RestoreSheet(app).open())]))
        if app.keys.has_identity:
            self.body.add_widget(SectionHead("Identity"))
            self.body.add_widget(rows_card([ListRow(
                "key", "Profile and keys",
                "Your name, address, QR codes and private key",
                chevron=True, on_tap=app.open_profile)]))
        self.body.add_widget(SectionHead("About"))
        self.body.add_widget(rows_card([ListRow(
            "info", f"{APP_NAME} {APP_VERSION}", "Version, relay and type",
            chevron=True, on_tap=lambda: AboutSheet(app).open())]))

    @staticmethod
    def _picker(icon: str, title: str, control: Widget,
                state: float) -> BoxLayout:
        """A setting chosen from a few, laid out as a row is: its icon in
        the rows' column, showing the choice (StateIcon), its heading and
        choices where their titles go. Returns the column to add to;
        `.row` is the whole, `.row.glyph` the icon."""
        row = BoxLayout(size_hint_y=None, spacing=dp(16),
                        padding=[dp(20), dp(10), dp(16), dp(8)])
        mark = AnchorLayout(anchor_y="top", size_hint_x=None, width=dp(24))
        glyph = StateIcon(icon, state, T.text_2)
        mark.add_widget(glyph)
        row.add_widget(mark)
        col = BoxLayout(orientation="vertical", size_hint_y=None,
                        spacing=dp(4))
        col.bind(minimum_height=col.setter("height"))
        col.add_widget(CapsLabel(title, size=10.5, color=T.text_3))
        col.add_widget(control)
        row.add_widget(col)
        col.bind(height=lambda *_a: setattr(row, "height", col.height +
                                            dp(18)))
        row.icon, row.glyph, col.row = icon, glyph, row
        return col

    def _blocked_hint(self) -> str:
        n = len(self.app.store.blocked_contacts()) if self.app.store else 0
        return f"{n} {'person' if n == 1 else 'people'} — and how to " \
               f"unblock them" if n else "No one is blocked"

    def _open_blocked(self) -> None:
        sheet = BlockedSheet(self.app)
        sheet.bind(on_dismiss=lambda *_a: self.show())
        sheet.open()

    def _on_delivery(self, on: bool) -> None:
        save_pref("background_delivery", bool(on))
        self.app._sync_background_service()

    def _on_previews(self, on: bool) -> None:
        save_pref("link_previews", bool(on))
        screen = self.app.conversation_screen
        screen._previews_on = bool(on)
        screen._rendered_peer = None    # its bubbles show or hide them anew
        if not on:
            screen.cancel_preview()

    def _choose_device(self, kind: str) -> None:
        names = sound_devices(kind)
        if not names:
            self.app._set_status("Choosing devices needs the sounddevice "
                                 "package", T.accent)
            return
        now = chosen_device(kind)

        def pick(name):
            save_pref(f"sound_{kind}", name or "")
            self.show()
        items = [("check" if now is None else "speaker", "The system's own",
                  lambda: pick(None))]
        items += [("check" if name == now else
                   ("mic" if kind == "input" else "speaker"), name,
                   lambda n=name: pick(n)) for name in names[:20]]
        MenuSheet(items, title="Microphone" if kind == "input"
                  else "Speaker").open()

class ProfileScreen(PageScreen):
    """Your profile: the identity you are writing as — its disc, name and
    username — and its keys: the address and public bundle (to share, as
    text or QR), the private key (never to share), and removing it."""

    def __init__(self, app: "FextApp", **kw):
        super().__init__(app, "profile", "My profile",
                         lambda: app.close_profile(), **kw)
        self._revealed = False

    def show(self) -> None:
        self.body.clear_widgets()
        self._revealed = False
        keys, app = self.app.keys, self.app
        if not keys.has_identity:
            return
        self.hero(keys.address, keys.label or keys.username or "?", "dm",
                  sub=f"@{keys.username or 'not registered'}",
                  on_name=lambda: RenameIdentityModal(app,
                                                      keys.address).open(),
                  on_avatar=lambda: app.picture_menu(), editable=True)
        self.body.add_widget(SectionHead("Photo"))
        self.body.add_widget(rows_card([ListRow(
            "camera", "Change the profile photo" if
            PICTURES.path(keys.address) else "Set a profile photo",
            "The people you write to see it", chevron=True,
            on_tap=lambda: app.picture_menu())]))
        self._identity()
        self.body.add_widget(SectionHead("This device"))
        self.body.add_widget(rows_card([ListRow(
            "delete", "Remove this identity",
            "Its key, chats and settings leave this device", danger=True,
            on_tap=lambda: RemoveIdentityModal(app, keys.address).open())]))

    def _qr(self, data: str, side=dp(184)) -> AnchorLayout:
        holder = AnchorLayout(size_hint_y=None, height=side + dp(20))
        plate = AnchorLayout(size_hint=(None, None),
                             size=(side + dp(16), side + dp(16)))
        paint_round(plate, T.plate, radius=dp(6))
        img = KivyImage(size_hint=(None, None), size=(side, side),
                        allow_stretch=True)
        img.texture = qr_texture(data)
        plate.add_widget(img)
        holder.add_widget(plate)
        return holder

    def _identity(self) -> None:
        keys, app = self.app.keys, self.app
        if not keys.has_identity:
            return
        self.body.add_widget(SectionHead("Address"))
        self.body.add_widget(rows_card([
            ListRow("copy", "Copy address", keys.address,
                    on_tap=lambda: app.copy_text(keys.address)),
        ] + ([ListRow("share", "Open the key folder", str(DATA_DIR),
                      on_tap=lambda: open_folder_in_explorer(DATA_DIR))]
             if not IS_MOBILE else [])))
        self.body.add_widget(self._qr(keys.address))
        self.body.add_widget(InfoLabel(
            "Scan for the address alone", color=T.text_3, italic=True,
            font_size=fs(14), halign="center"))
        self.paragraph(
            "The address is the HASH160 of your public key in Base58Check "
            "(version 0x24), as Bitcoin builds one. Its “Fec” prefix is the "
            "network's proof of work.", italic=True)
        bundle = json.dumps(keys.public_bundle(), indent=2)
        self.body.add_widget(SectionHead("Public bundle · safe to share"))
        self.body.add_widget(rows_card([ListRow(
            "copy", "Copy the public bundle", "Username, address and key",
            on_tap=lambda: app.copy_text(bundle))]))
        self.body.add_widget(self._qr(json.dumps(keys.public_bundle(),
                                                 separators=(",", ":")),
                                      side=dp(200)))
        self.body.add_widget(SectionHead("Private key · never share it"))
        self.private_label = InfoLabel(
            "Hidden", color=T.alert, font_size=fs(14), italic=True,
            padding=[dp(20), dp(4)])
        self.reveal_row = ListRow(
            "key", "Reveal the private key", "As raw hex and as WIF",
            on_tap=self._toggle_private)
        self.body.add_widget(rows_card([
            self.reveal_row,
            ListRow("copy", "Copy WIF", "Imports into Ferrite Core",
                    on_tap=self._copy_wif)]))
        self.body.add_widget(self.private_label)

    def _toggle_private(self) -> None:
        self._revealed = not self._revealed
        self.private_label.text = (self.app.keys.private_export()
                                   if self._revealed else "Hidden")
        self.private_label.italic = not self._revealed
        self.reveal_row.title.text = ("Hide the private key" if
                                      self._revealed else
                                      "Reveal the private key")

    def _copy_wif(self) -> None:
        data = json.loads(self.app.keys.private_export())
        Clipboard.copy(data["private_key_wif"])
        self.app._set_status("Private key copied — keep it safe", T.accent)



class SettingsModal:
    """Pre-9.1 entry point: Settings is a page now."""

    def __init__(self, app: "FextApp") -> None:
        self.app = app

    def open(self) -> None:
        self.app.open_settings()


class SplashOverlay(FloatLayout):
    """The loading screen: the mark above the wordmark — on white, or in a
    dark theme on the theme's own ground, the mark on its white plate.

    It covers the first paint (the screens being built, the identity read
    off disk, the transport probe going out) and then fades. It is a widget
    in the tree, not a ModalView, so the first-run sheet cannot show
    through it; _post_build waits for the fade.
    """

    FADE = 0.1          # seconds of fade-out
    HOLD = 0.9          # minimum time on screen, so it never merely blinks

    def __init__(self, **kw):
        super().__init__(**kw)
        # White, as specified — the ground of the launcher icon and the
        # platform presplash, so the three hand over seamlessly. In a dark
        # theme the platform presplash is black too (res/values-night and
        # res/drawable-night), so a phone at night is never lit up white.
        dark = T.dark
        self.ground = T.bg if dark else "#FFFFFF"
        paint_round(self, self.ground, radius=0)
        column = BoxLayout(orientation="vertical", spacing=dp(18),
                           size_hint=(None, None), width=dp(280),
                           pos_hint={"center_x": 0.5, "center_y": 0.5})
        column.bind(minimum_height=column.setter("height"))
        logo = LOGO_FILE_DARK if dark and LOGO_FILE_DARK.exists() \
            else LOGO_FILE
        self.logo = None
        if logo.exists():
            self.logo = KivyImage(source=str(logo), allow_stretch=True,
                                  keep_ratio=True, size_hint_y=None,
                                  height=dp(180))
            column.add_widget(self.logo)
        # As tall as its two lines: a fixed height a pixel short of them
        # made Kivy drop "Messenger" without a word.
        wordmark = Label(
            text="Ferrite Text\nMessenger", halign="center", valign="top",
            font_size=sp(26), color=C(T.text if dark else "#1B1915"),
            line_height=1.1, size_hint_y=None)
        wordmark.bind(width=lambda w, v: setattr(w, "text_size", (v, None)),
                      texture_size=lambda w, v: setattr(w, "height", v[1]))
        column.add_widget(wordmark)
        byline = Label(text="by koh-gt", italic=True, font_size=sp(15),
                       color=C(T.text_3 if dark else "#6F685C"),
                       size_hint_y=None, height=dp(24))
        column.add_widget(byline)
        self.add_widget(column)


class MessagingMixin:
    """Everything that turns a message into envelopes on the relay.

    Shared, unchanged, by the app and the background service (HeadlessApp):
    a re-upload asked for while the app is closed, or the group state an
    admin must publish when someone leaves, goes out through the very same
    code. Needs `keys`, `crypto`, `api`, `store` and `ui_queue`.

    A conversation key (`peer`) is one of:
      * an address               a direct chat
      * GROUP_PREFIX + gid       a group: one envelope per other member
      * our own address          notes to self: stored here, sent nowhere
    """

    def conversation_kind(self, peer: Optional[str]) -> str:
        if not peer:
            return "none"
        if peer.startswith(GROUP_PREFIX):
            return "group"
        if peer == self.keys.address:
            return "self"
        return "dm"

    def group_recipients(self, gid: str) -> list:
        """[(address, public key), …] of the OTHER members, if we are in."""
        group = self.store.group(gid) if self.store else None
        if group is None or group["state"] != "active":
            return []
        return [(m["a"], m["k"]) for m in group["members"]
                if m["a"] != self.keys.address]

    def _send_worker(self, local_id: Optional[int], peer: str, peer_pub: str,
                     body: str, client_msg_id: str, x: Optional[dict] = None,
                     group: Optional[str] = None) -> bool:
        """SIGN → ENCRYPT → SEND one envelope to one address (`peer`), then
        record the relay's receipt (1/3).

        `group` set: this is one member's copy of group message `local_id`,
        recorded per member. `local_id` None: a control, nothing recorded.

        Every failure here has to end at the UI: a message must never sit at
        0/3 with no reason given anywhere.
        """
        sealed = self._seal_copy(peer, peer_pub, body, client_msg_id, x)
        if sealed is None:
            return False
        envelope, fragment = sealed
        try:
            result = self.api.send_message(peer, envelope, client_msg_id)
        except (requests.RequestException, ApiClient.ApiError,
                ValueError) as exc:
            self._not_sent(peer, local_id, str(exc), fragment)
            return False
        except Exception as exc:                     # never lose the thread
            log.exception("unexpected error sending to %s", peer)
            self._not_sent(peer, local_id, f"unexpected: {exc}", fragment)
            return False
        if local_id is None:                         # a control: no row
            return True
        return self._record_copy(local_id, peer, group,
                                 result.get("server_id"), fragment)

    def _flow_names(self, peer: str) -> tuple:
        """(us, them) as the message-flow log names them."""
        contact = self.store.get_contact(peer) or {}
        return (MessageFlowLog.who(self.keys.address, self.keys.username),
                MessageFlowLog.who(peer, contact.get("username")))

    def _seal_copy(self, peer: str, peer_pub: str, body: str,
                   client_msg_id: str, x: Optional[dict]):
        """SIGN → ENCRYPT one copy for `peer`: (envelope, log fragment), or
        None once the user has been told why not."""
        if x is not None:
            # v9.1.2: what this app can do, and which version of our picture
            # is current — older releases verify these and ignore them.
            x = dict(x, ft=FEATURES)
            pv = self.store.picture_version(self.keys.address)
            if pv:
                x["pv"] = pv
            # v15: our post-quantum key's id, and the key itself until they
            # have shown they hold it (signed with the rest of the block).
            x["pq"] = self.keys.pq_kid
            if self.store.pq_mine(peer) != x["pq"]:
                x["pqe"] = b64e(self.keys.pq_public)
        try:
            envelope, _sent_at = self.crypto.build_envelope(
                body, peer_pub, x=x, recipient=peer, cid=client_msg_id,
                pq=self.store.pq_key(peer))
        except Exception as exc:
            log.exception("could not build envelope for %s", peer)
            MessageFlowLog.failed(*self._flow_names(peer),
                                  f"encryption failed: {exc}")
            self.ui_queue.put(("status", f"Could not encrypt: {exc}",
                               COL_DANGER))
            return None
        return envelope, MessageFlowLog.fragment(envelope)

    def _not_sent(self, peer: str, local_id: Optional[int], why: str,
                  fragment: str = "") -> None:
        """A copy the relay did not take. A message waits, with its clock,
        for the outbox to send it when the relay answers (v14, B15); a
        control is lost, so that is said plainly."""
        MessageFlowLog.failed(*self._flow_names(peer), why, fragment)
        if local_id is None:
            self.ui_queue.put(("status", f"Send failed: {why}", COL_DANGER))
        else:
            self.ui_queue.put(("status", "Not sent yet · it goes by itself "
                               "when the relay answers", COL_TICK_GOLD))

    def _record_copy(self, local_id: int, peer: str, group: Optional[str],
                     server_id, fragment: str) -> bool:
        """The relay took one copy of message `local_id` (1/3): note it."""
        me, them = self._flow_names(peer)
        recorded = (self.store.group_send_sent(local_id, peer, server_id)
                    if group else self.store.mark_sent(local_id, server_id))
        if not recorded:
            # The relay HAS the message; we merely failed to write that
            # down. Say so rather than leaving a grey tick and no reason.
            MessageFlowLog.failed(
                me, them, f"relay accepted it as #{server_id} but the local "
                          f"store could not record that", fragment)
            self.ui_queue.put(
                ("status", "Sent, but this device could not record it — "
                 "the tick may be wrong", COL_DANGER))
            return False
        MessageFlowLog.tick(1, server_id, me, them, fragment)
        self.ui_queue.put(("message_stored",
                           group_peer(group) if group else peer))
        return True

    def _send_group_many(self, local_id: Optional[int], gid: str,
                         members: list, body: str, cid: str,
                         x: dict) -> bool:
        """v14 (B1): one group message, or control, to `members` [(address,
        public key)] in as few requests as the relay allows, instead of one
        each. True only if every copy reached the relay; the others wait in
        the outbox like any message that could not go."""
        sealed = []
        for address, pub in members:
            copy = self._seal_copy(address, pub, body, cid, x)
            if copy is not None:
                sealed.append((address,) + copy)
        ok = len(sealed) == len(members)
        for start in range(0, len(sealed), SEND_MANY_MAX):
            chunk = sealed[start:start + SEND_MANY_MAX]
            try:
                results = self.api.send_many(
                    [{"recipient": address, "envelope": envelope,
                      "client_msg_id": cid}
                     for address, envelope, _f in chunk])
            except (requests.RequestException, ApiClient.ApiError,
                    ValueError) as exc:
                for address, _e, fragment in chunk:
                    self._not_sent(address, local_id, str(exc), fragment)
                ok = False
                continue
            for (address, _e, fragment), result in zip(chunk, results):
                if not isinstance(result, dict):
                    result = {"error": {"message": "no answer"}}
                error = result.get("error")
                if error or not result.get("server_id"):
                    self._not_sent(address, local_id,
                                   (error or {}).get("message",
                                                     "not stored"), fragment)
                    ok = False
                elif local_id is not None:
                    ok = self._record_copy(local_id, address, gid,
                                           result["server_id"],
                                           fragment) and ok
        return ok

    def _send_copies(self, local_id: Optional[int], peer: str, body: str,
                     cid: str, x: dict, only: Optional[set] = None) -> bool:
        """Deliver one message (or control) to every recipient of a
        conversation — in a group, `only` those members, when given (the
        outbox: the members still without their copy). True only if every
        copy reached the relay."""
        kind = self.conversation_kind(peer)
        if kind == "self":
            return True
        if kind == "dm":
            contact = self.store.get_contact(peer)
            if contact is None:
                return False
            if local_id is not None:
                self._send_picture_if_due(contact)
            return self._send_worker(local_id, peer, contact["public_key"],
                                     body, cid, x)
        gid = gid_of(peer)
        group = self.store.group(gid) if gid else None
        if group is None:
            return False
        admin = group["admin"] == self.keys.address
        if x.get("k") == "ctl":
            x = dict(x, ctl=dict(x["ctl"], grp=gid))
        else:
            x = dict(x, grp={"id": gid, "v": group["version"]})
            gpv = self.store.picture_version(peer) if admin else 0
            if gpv:
                x["grp"]["pv"] = gpv      # the group picture, from its admin
        members = [(a, k) for a, k in self.group_recipients(gid)
                   if only is None or a in only]
        if local_id is not None:
            for address, _pub in members:
                contact = self.store.get_contact(address)
                if contact is not None:
                    self._send_picture_if_due(contact)
                    if admin:
                        self._send_group_picture_if_due(gid, contact)
        if len(members) > 1 and self.api.features().get("send_many"):
            return self._send_group_many(local_id, gid, members, body, cid, x)
        ok = True
        for address, pub in members:
            ok = self._send_worker(local_id, address, pub, body, cid, x,
                                   group=gid if local_id else None) and ok
        return ok

    def send_text(self, peer: str, body: str, reply: Optional[dict] = None,
                  forwarded: bool = False, preview: Optional[dict] = None
                  ) -> Optional[int]:
        """Queue a text message. Returns its local id (None if impossible).

        Every v9 message carries a signed extension block, even a plain one:
        it is what binds the message to its recipient (see build_envelope)
        and how the other side learns this device understands replies,
        media and delete-for-both.
        """
        ext = {}
        if reply:
            ext["reply"] = reply
        if forwarded:
            ext["fwd"] = 1
        if preview and preview.get("u") in links_in(body):
            preview = dict(preview)
            if len(body.encode("utf-8")) > 12000:
                preview.pop("i", None)     # a long text leaves it no room
            ext["lp"] = preview
        return self._queue_message(peer, body, dict(ext, k="text"), "text",
                                   ext)

    def _queue_message(self, peer: str, body: str, x: dict, kind: str,
                       ext: Optional[dict], media_path: Optional[str] = None,
                       media_state: str = "",
                       on_local_row: Optional[Callable] = None
                       ) -> Optional[int]:
        """Record an outgoing message at 0/3 and send it in the background.

        Notes to self are recorded and go nowhere. A group message records
        one delivery row per member, then goes out to each of them.
        """
        if self.store is None:
            return None
        conv = self.conversation_kind(peer)
        recipients = None
        if conv == "dm":
            contact = self.store.get_contact(peer)
            if contact is None:
                self._set_status("Unknown contact", COL_DANGER)
                return None
            if not contact.get("accepted", 1):
                self.store.set_accepted(peer)   # writing to them accepts
            label = contact.get("username")
        elif conv == "group":
            recipients = [a for a, _k in self.group_recipients(gid_of(peer))]
            if not recipients:
                self._set_status("You are no longer a member of this group",
                                 COL_TICK_GOLD)
                return None
            label = (self.store.group(gid_of(peer)) or {}).get("name")
        else:
            label = "saved messages"
        client_msg_id = uuid.uuid4().hex
        # v11: in a chat with disappearing messages, each one says how long
        # it lasts, and this copy goes that long after sending.
        ttl = self.store.chat_timer(peer)[0] if conv != "self" else 0
        if ttl:
            x = dict(x, ttl=ttl)
        # 0/3 immediately: the grey tick means "not yet on the server".
        local_id = self.store.add_out(peer, body, now_iso(), client_msg_id,
                                      kind=kind, ext=ext or None,
                                      media_path=media_path,
                                      media_state=media_state,
                                      recipients=recipients, ttl=ttl)
        MessageFlowLog.tick(
            0, None, MessageFlowLog.who(self.keys.address, self.keys.username),
            label or MessageFlowLog.who(peer),
            f"[local id {local_id}, client_msg_id {client_msg_id[:8]}…]")
        if on_local_row is not None:
            on_local_row(local_id, client_msg_id)
        self._after_local_row(peer)
        if media_state != "uploading" and conv != "self":
            threading.Thread(
                target=self._send_row,
                args=(local_id, peer, body, client_msg_id, x),
                daemon=True).start()
        return local_id

    # ---- v14: the outbox (B15) -------------------------------------------------
    # A message the relay has not taken stays on this phone at 0/3, drawn
    # with a clock, and goes by itself the next time the relay answers: the
    # sync worker calls flush_outbox when it connects, and every OUTBOX_EVERY
    # seconds while it stays connected. After OUTBOX_DAY it waits for a tap
    # ("Not sent · tap to try again", retry_message). Sending twice is safe
    # either way: a receiving app keeps one copy per client id.
    def _sends(self) -> tuple:
        """(lock, set of local ids being sent right now)."""
        if getattr(self, "_in_flight", None) is None:
            self._in_flight_lock = threading.Lock()
            self._in_flight = set()
        return self._in_flight_lock, self._in_flight

    def _send_row(self, local_id: int, peer: str, body: str, cid: str,
                  x: dict, only: Optional[set] = None) -> bool:
        """_send_copies for one stored message, unless it is already on its
        way (the first try and the outbox can meet)."""
        lock, busy = self._sends()
        with lock:
            if local_id in busy:
                return False
            busy.add(local_id)
        try:
            return self._send_copies(local_id, peer, body, cid, x, only=only)
        finally:
            with lock:
                busy.discard(local_id)

    def flush_outbox(self, include_old: bool = False,
                     only_id: Optional[int] = None) -> int:
        """Send what is still on this phone, oldest first: messages the
        relay never took, and in a group the members still without a copy;
        a photo or voice note is uploaded first if it never was. Returns how
        many messages went. `include_old`: those past OUTBOX_DAY too."""
        if self.store is None or self.api is None:
            return 0
        cutoff = 0.0 if include_old else time.time() - OUTBOX_DAY
        sent = 0
        for row in self.store.outbox(cutoff):
            if only_id is not None and row["id"] != only_id:
                continue
            if self.conversation_kind(row["peer"]) == "self":
                continue
            ext = json.loads(row.get("ext") or "{}")
            media = ext.get("media")
            if row["kind"] in MEDIA_MIME and isinstance(media, dict) and \
                    not media.get("blob"):
                if self._upload_media(row["id"], row["peer"], row["body"],
                                      row["client_msg_id"]):
                    sent += 1
                continue
            x = dict(ext, k="media" if row["kind"] in MEDIA_MIME else "text")
            if row.get("ttl"):
                x["ttl"] = row["ttl"]
            only = None
            if row["members"] is not None:
                # Owed copies, to those still in the group.
                only = set(row["members"]) & {
                    a for a, _k in self.group_recipients(gid_of(row["peer"]))}
                if not only:
                    continue
            if self._send_row(row["id"], row["peer"], row["body"],
                              row["client_msg_id"], x, only=only):
                sent += 1
        if sent:
            flow_log.info("📤   the outbox sent %d message(s)", sent)
        return sent

    def retry_message(self, local_id: int) -> None:
        """A tap on "Not sent · tap to try again": send it now, whatever
        its age."""
        threading.Thread(target=self.flush_outbox,
                         kwargs={"include_old": True, "only_id": local_id},
                         daemon=True).start()

    def _upload_media(self, local_id: int, peer: str, body: str, cid: str,
                      data: Optional[bytes] = None) -> bool:
        """Seal, upload and send the photo or voice note of message
        `local_id`, from the copy kept on this phone. True once it is sent.

        v14: the upload says how many people will fetch it (B2). A relay
        that is full (B10) or out of reach leaves it 'waiting', with its
        clock, for the outbox; only a file no relay can take is 'failed'.
        It carries the chat's timer, as a text does."""
        lock, busy = self._sends()
        with lock:
            if local_id in busy:
                return False
            busy.add(local_id)
        try:
            row = self.store.message(local_id)
            if row is None:
                return False
            if row.get("media_state") != "uploading":
                self.store.set_media(local_id, state="uploading")
                self.ui_queue.put(("message_stored", peer))
            ext = json.loads(row.get("ext") or "{}")
            try:
                if data is None:
                    data = Path(row.get("media_path") or "").read_bytes()
            except OSError:
                self.store.set_media(local_id, state="failed")
                self.ui_queue.put(("message_stored", peer))
                self.ui_queue.put(("status", "The original file is gone",
                                   COL_DANGER))
                return False
            gid = gid_of(peer)
            expect = len(self.group_recipients(gid)) if gid else 1
            try:
                blob, key, sha = seal_media(data)
                blob_id = self.api.upload_blob(blob, expect=expect).get(
                    "blob", "")
                if not _TOKEN_RE.match(blob_id or ""):
                    raise ValueError("relay returned no media id")
            except (requests.RequestException, ApiClient.ApiError,
                    ValueError) as exc:
                log.warning("media upload not done: %s", exc)
                status = getattr(exc, "status", 0)
                self.store.set_media(local_id, state="failed"
                                     if status == 413 else "waiting")
                self.ui_queue.put(("message_stored", peer))
                self.ui_queue.put(("status", {
                    413: "That's too large for this relay",
                    429: "The relay's room for your media is full · it "
                         "goes by itself when there is space",
                    507: "The relay's room for media is full · it goes by "
                         "itself when there is space",
                }.get(status, "Not sent yet · it goes by itself when the "
                              "relay answers"),
                    COL_DANGER if status == 413 else COL_TICK_GOLD))
                return False
            ext["media"] = dict(ext.get("media") or {}, blob=blob_id,
                                key=key, sha=sha)
            self.store.set_media(local_id, state="ready", ext=ext)
        finally:
            with lock:
                busy.discard(local_id)
        x = dict(ext, k="media")
        if row.get("ttl"):
            x["ttl"] = row["ttl"]
        ok = self._send_row(local_id, peer, body, cid, x)
        self.ui_queue.put(("message_stored", peer))
        return ok

    def _after_local_row(self, peer: str) -> None:
        """A message was just recorded here; the app repaints (FextApp)."""
        self.ui_queue.put(("message_stored", peer))

    # ---- v11: telling the user, from the sync thread ---------------------------
    def notify_incoming(self, peer: str, body: str, kind: str,
                        author: Optional[str] = None) -> None:
        """A new message (sync thread). A muted chat stays quiet — it still
        shows everything when it is opened. FextApp also stays quiet about
        the chat on screen, and notifies a computer its own way."""
        if self.store is None:
            return
        name, preview, muted = notification_text(self.store, peer, body,
                                                 kind, author)
        if muted:
            return
        if IS_ANDROID:
            android_message_notification(self, peer, name, preview[:160])

    def call_signal_arrived(self, sender: str, sig: dict) -> None:
        """A call's message (sync thread). Nothing is on screen here: keep
        an offer for the app, ring through a notification, and log a call
        that was given up on as missed. FextApp sends signals to its call
        screen instead when it is showing, or a call is on."""
        _service_call_signal(self, sender, sig)

    def run_commands(self, worker=None) -> int:
        """Act on what was done to a notification (Android): NotifyReceiver
        writes one small file per action — a reply, mark as read, decline —
        and whichever worker runs takes it by renaming it. Another
        identity's waits for that identity, a day at most."""
        try:
            names = sorted(p.name for p in COMMANDS_DIR.iterdir()
                           if p.suffix == ".json")
        except OSError:
            return 0
        done = 0
        for name in names:
            path = COMMANDS_DIR / name
            try:
                cmd = json.loads(path.read_text("utf-8"))
            except (OSError, ValueError):
                cmd = None
            if not isinstance(cmd, dict):
                try:
                    path.unlink()
                except OSError:
                    pass
                continue
            owner = cmd.get("me")
            if owner and owner != self.keys.address:
                at = float(cmd.get("at") or 0) / 1000.0
                if time.time() - at > 86400:
                    try:
                        path.unlink()
                    except OSError:
                        pass
                continue
            claim = COMMANDS_DIR / f"{name}.{os.getpid()}.run"
            try:
                path.rename(claim)
            except OSError:
                continue                    # another worker took it
            try:
                self._run_command(cmd, worker)
                done += 1
            except Exception:
                log.exception("a notification action failed: %r",
                              cmd.get("op"))
            finally:
                try:
                    claim.unlink()
                except OSError:
                    pass
        return done

    def _run_command(self, cmd: dict, worker=None) -> None:
        op, peer = cmd.get("op"), cmd.get("peer")
        if not isinstance(peer, str) or not peer or self.store is None:
            return
        known = (self.store.group(gid_of(peer)) is not None
                 if peer.startswith(GROUP_PREFIX)
                 else self.store.get_contact(peer) is not None)
        if not known:
            return
        if op == "reply":
            text = sanitize_text(str(cmd.get("text") or ""))
            if text and not self.store.is_blocked(peer):
                self.send_text(peer, text)
                flow_log.info("↩   reply from a notification to %s",
                              MessageFlowLog.who(peer))
            self._read_quietly(peer, worker)
        elif op == "read":
            self._read_quietly(peer, worker)
        elif op == "decline":
            self._decline_quietly(peer, str(cmd.get("call") or ""))

    def _read_quietly(self, peer: str, worker=None) -> None:
        """Mark a chat read without its screen: the receipts go, and its
        disappearing messages start their time."""
        unread = self.store.unread_for(peer)
        if unread:
            self.store.mark_read_local([local_id for local_id, _ in unread])
            server_ids = [sid for _, sid in unread if sid]
            if server_ids and worker is not None:
                threading.Thread(target=worker.send_read_receipts,
                                 args=(server_ids,), daemon=True).start()
            self.ui_queue.put(("message_stored", peer))
        if IS_ANDROID:
            android_clear_notification(peer)

    def _decline_quietly(self, peer: str, call_id: str) -> None:
        """Decline a call from its notification: tell the caller, forget
        the offer kept for the app, and say so in the chat."""
        if not _CALL_ID_RE.match(call_id):
            return
        self._declined_calls.add(call_id)
        path = DATA_DIR / f"call_offer_{self.keys.address}.json"
        try:
            pending = json.loads(path.read_text("utf-8"))
            if (pending.get("sig") or {}).get("id") == call_id:
                path.unlink()
        except (OSError, ValueError):
            pass
        if IS_ANDROID:
            android_cancel_call_notification()
        threading.Thread(target=self._send_control_to, args=(
            peer, {"op": "end", "id": call_id, "why": "declined"},
            "Voice call"), daemon=True).start()
        self.store.add_event(peer, "Declined call")
        self.ui_queue.put(("message_stored", peer))

    def _send_control(self, peer: str, op: dict, fallback: str) -> bool:
        """Send a control to a whole conversation, synchronously (call from
        a worker thread). `fallback` is the body: what a pre-v9 client
        shows, since it cannot act on the instruction."""
        return self._send_copies(None, peer, fallback, uuid.uuid4().hex,
                                 {"k": "ctl", "ctl": op})

    def _send_control_to(self, address: str, op: dict, fallback: str,
                         pub: Optional[str] = None) -> bool:
        """A control for ONE person, whatever conversation it concerns (in a
        group: asking the author of a photo to send it again)."""
        if pub is None:
            contact = self.store.get_contact(address)
            if contact is None:
                return False
            pub = contact["public_key"]
        return self._send_worker(None, address, pub, fallback,
                                 uuid.uuid4().hex, {"k": "ctl", "ctl": op})

    # ---- v9.1.2: pictures ------------------------------------------------------
    # Sent only to apps that have said they keep pictures (x.ft), so nobody
    # is sent forty kilobytes to throw away; and only to people we write to:
    # a picture goes out with the first message after it changes, or when it
    # is changed, or when someone's app finds its copy is out of date.
    def _picture_payload(self, peer: str) -> Optional[dict]:
        """{"v", "d"} for the picture held under `peer` (ours: our address;
        a group's: its conversation key), or None if there never was one."""
        row = self.store.picture(peer)
        if row is None:
            return None
        data = ""
        if row.get("path"):
            try:
                data = b64e(Path(row["path"]).read_bytes())
            except OSError:
                log.warning("picture file for %s is missing", peer[:12])
                return None
        return {"v": int(row["version"]), "d": data}

    def _send_own_picture(self, contact: dict) -> bool:
        payload = self._picture_payload(self.keys.address)
        if payload is None:
            return False
        ok = self._send_control_to(contact["address"], dict(payload, op="pic"),
                                   "Updated their profile photo",
                                   pub=contact["public_key"])
        if ok:
            self.store.set_picture_sent(contact["address"], payload["v"])
        return ok

    def _send_group_picture(self, gid: str, contact: dict) -> bool:
        payload = self._picture_payload(group_peer(gid))
        if payload is None:
            return False
        ok = self._send_control_to(contact["address"],
                                   dict(payload, op="gpic", grp=gid),
                                   "Updated the group photo",
                                   pub=contact["public_key"])
        if ok:
            self.store.set_picture_sent(f"{gid}/{contact['address']}",
                                        payload["v"])
        return ok

    def _picture_wanted_by(self, contact: Optional[dict]) -> bool:
        return bool(contact) and \
            bool(contact.get("caps", 0) & LocalStore.CAP_PIC) and \
            contact["address"] != self.keys.address and \
            not self.store.is_blocked(contact["address"])

    def _send_picture_if_due(self, contact: dict) -> bool:
        """Before a message: our picture, if their app keeps pictures and
        has not been sent the current version. True if it was sent."""
        if not self._picture_wanted_by(contact):
            return False
        version = self.store.picture_version(self.keys.address)
        if version and self.store.picture_sent(contact["address"]) < version:
            return self._send_own_picture(contact)
        return False

    def _send_group_picture_if_due(self, gid: str, contact: dict) -> bool:
        if not self._picture_wanted_by(contact):
            return False
        version = self.store.picture_version(group_peer(gid))
        if version and self.store.picture_sent(
                f"{gid}/{contact['address']}") < version:
            return self._send_group_picture(gid, contact)
        return False

    def broadcast_picture(self, gid: Optional[str] = None) -> int:
        """A picture changed — ours, or (as its admin) a group's: send it to
        everyone concerned whose app keeps pictures. Blocking; run it on a
        worker thread. Paced, to stay inside the relay's rate limit.
        Returns how many were sent."""
        sent = 0
        if gid is None:
            people = self.store.contacts_with_caps(LocalStore.CAP_PIC)
        else:
            group = self.store.group(gid)
            if group is None or group["admin"] != self.keys.address or \
                    group["state"] != "active":
                return 0
            people = [c for c in (self.store.get_contact(m["a"])
                                  for m in group["members"]) if c]
        for contact in people:
            if (self._send_picture_if_due(contact) if gid is None else
                    self._send_group_picture_if_due(gid, contact)):
                sent += 1
                time.sleep(0.3)
        return sent

    def _picture_memo(self, name: str) -> dict:
        memo = getattr(self, name, None)
        if memo is None:
            memo = {}
            setattr(self, name, memo)
        return memo

    def ask_for_picture(self, address: str, gid: Optional[str],
                        version: int) -> bool:
        """Their message says a newer picture exists than the one this
        device holds (ours was lost, or theirs never arrived): ask for it.
        At most once in half an hour for the same version. Blocking."""
        asked = self._picture_memo("_pictures_asked")
        key = (address, gid)
        before = asked.get(key)
        if before and before[0] >= version and \
                time.monotonic() - before[1] < 1800:
            return False
        if self.store.is_blocked(address) and gid is None:
            return False
        asked[key] = (version, time.monotonic())
        op = {"op": "picreq"}
        if gid:
            op["grp"] = gid
        return self._send_control_to(address, op, "Asked for a profile photo")

    def answer_picture_request(self, requester: str,
                               gid: Optional[str]) -> bool:
        """They asked for our picture (or, as its admin, the group's):
        send the current one, whatever they were sent before. At most once
        in ten minutes each. Blocking."""
        answered = self._picture_memo("_pictures_answered")
        key = (requester, gid)
        if time.monotonic() - answered.get(key, -1e9) < 600:
            return False
        contact = self.store.get_contact(requester)
        if contact is None or (gid is None and
                               self.store.is_blocked(requester)):
            return False
        answered[key] = time.monotonic()
        if gid is None:
            return self._send_own_picture(contact)
        group = self.store.group(gid)
        if group is None or group["admin"] != self.keys.address or \
                requester not in {m["a"] for m in group["members"]}:
            return False
        return self._send_group_picture(gid, contact)

    def _group_state(self, gid: str) -> Optional[dict]:
        group = self.store.group(gid)
        if group is None:
            return None
        return {"id": gid, "name": group["name"], "v": group["version"],
                "admin": group["admin"], "members": group["members"]}

    def _publish_group_state(self, gid: str, also=(), fallback: str = "",
                             bump: bool = True) -> bool:
        """As the admin: bump the version and send the group's state to every
        member (and to `also`: people just removed, so they learn it)."""
        group = self.store.group(gid)
        if group is None or group["admin"] != self.keys.address:
            return False
        state = self._group_state(gid)
        if bump:
            state["v"] += 1
            self.store.save_group(state, group["state"])
        body = fallback or f"Group \u201c{state['name']}\u201d updated"
        ok = True
        targets = [(m["a"], m["k"]) for m in state["members"]
                   if m["a"] != self.keys.address] + list(also)
        for address, pub in targets:
            ok = self._send_control_to(address, {"op": "group", "g": state},
                                       body, pub=pub) and ok
        # Someone just added has not seen the group's picture yet.
        if self.store.picture_version(group_peer(gid)):
            for member in state["members"]:
                contact = self.store.get_contact(member["a"])
                if contact is not None:
                    self._send_group_picture_if_due(gid, contact)
        return ok

    # ---- v15: messages sealed to an earlier post-quantum key -------------------
    def _reseals(self) -> tuple:
        """(lock, {peer: message ids to ask them for again}, the (peer,
        message id) pairs already sent again)."""
        if getattr(self, "_reseal_wanted", None) is None:
            self._reseal_lock = threading.Lock()
            self._reseal_wanted, self._resealed = {}, set()
        return self._reseal_lock, self._reseal_wanted, self._resealed

    def ask_reseal(self, peer: str, cid: str) -> None:
        """Ask `peer` to send message `cid` again: it was sealed to our key
        from an earlier install. What arrives within two seconds goes in one
        request, which carries our key with it (as every message does until
        they hold it)."""
        lock, wanted, _done = self._reseals()
        with lock:
            first = peer not in wanted
            wanted.setdefault(peer, set()).add(cid)
        if first:
            timer = threading.Timer(2.0, self._send_reseal, args=(peer,))
            timer.daemon = True
            timer.start()

    def _send_reseal(self, peer: str) -> None:
        lock, wanted, _done = self._reseals()
        with lock:
            cids = sorted(wanted.pop(peer, ()))[:RESEAL_MAX]
        contact = self.store.get_contact(peer) if self.store else None
        pub = contact["public_key"] if contact else None
        if pub is None:
            # A new install may not know them yet: the relay's directory
            # says, and the address (a hash of the key) proves it.
            try:
                pub = self.api.lookup(address=peer).get("public_key")
                if address_from_pub_bytes(bytes.fromhex(pub)) != peer:
                    raise ValueError("directory key does not match")
            except (requests.RequestException, ApiClient.ApiError,
                    ValueError, TypeError, AttributeError) as exc:
                log.warning("cannot ask %s to reseal: %s", peer[:12], exc)
                return
        self._send_control_to(peer, {"op": "reseal", "cids": cids},
                              "Please send your last messages again", pub=pub)

    def reseal(self, peer: str, cids: list) -> None:
        """`peer` could not open these messages: send each again, the same
        message under the same id, sealed to the key their request brought.
        Only messages that were sent to them, only recent ones, and each
        once: a request cannot make this phone send a message twice."""
        lock, _wanted, done = self._reseals()
        with lock:
            cids = [c for c in cids if (peer, c) not in done]
            done.update((peer, c) for c in cids)

        def work():
            for cid in cids:
                row = self.store.outgoing_by_cid(cid)
                try:
                    written = datetime.fromisoformat(
                        row["created_at"]).timestamp()
                except (TypeError, ValueError):
                    continue          # also when there is no such message
                if time.time() - written > RESEAL_WINDOW:
                    continue
                gid = gid_of(row["peer"])
                if gid is None and row["peer"] != peer:
                    continue
                if gid is not None and peer not in {
                        r["member"] for r in self.store.group_sends(row["id"])}:
                    continue
                ext = json.loads(row.get("ext") or "{}")
                x = dict(ext, k="media" if row["kind"] in MEDIA_MIME
                         else "text")
                if row.get("ttl"):
                    x["ttl"] = row["ttl"]
                self._send_row(row["id"], row["peer"], row["body"], cid, x,
                               only={peer} if gid else None)
        threading.Thread(target=work, daemon=True).start()

    def _on_resend_request(self, peer: str, cid: str,
                           gid: Optional[str] = None) -> None:
        """They asked for a file the relay no longer has: upload our copy
        again and point THEIR existing message at it (no duplicate). In a
        group only the person who asked is sent the new reference."""
        conversation = group_peer(gid) if gid else peer
        row = self.store.message_by_cid(conversation, cid, "out")
        if not row or not row.get("media_path") or \
                not Path(row["media_path"]).is_file():
            log.info("resend requested for %s but no local copy remains", cid)
            return
        ext = json.loads(row.get("ext") or "{}")

        def work():
            try:
                data = Path(row["media_path"]).read_bytes()
                blob, key, sha = seal_media(data)
                # For the one person who asked (v14, B2).
                blob_id = self.api.upload_blob(blob, expect=1).get("blob", "")
                if not _TOKEN_RE.match(blob_id or ""):
                    raise ValueError("relay returned no media id")
            except (OSError, ValueError, requests.RequestException,
                    ApiClient.ApiError) as exc:
                log.warning("re-upload for %s failed: %s", cid, exc)
                return
            media = dict(ext.get("media") or {}, blob=blob_id, key=key,
                         sha=sha)
            ext["media"] = media
            self.store.set_media(row["id"], ext=ext)
            op = {"op": "remedia", "cid": cid, "media": media}
            if gid:
                op["grp"] = gid
            self._send_control_to(peer, op, row["body"])
        threading.Thread(target=work, daemon=True).start()


class FextApp(MessagingMixin, App):
    """Owns the identity lifecycle, the two screens and the UI-queue pump.

    Threading contract (unchanged from v2): ALL network + crypto work happens
    off the UI thread. Workers never touch widgets directly — they post to
    `ui_queue`, which is drained on the Kivy main thread by `_drain_ui_queue`
    (the Clock analogue of the old tkinter `after()` loop).
    """

    def __init__(self, **kw) -> None:
        super().__init__(**kw)
        self.title = f"{APP_NAME} {APP_VERSION} — end-to-end encrypted " \
                     f"messenger"
        self.keys = IdentityManager()
        self.crypto: Optional[CryptoEngine] = None
        self.api: Optional[ApiClient] = None
        self.store: Optional[LocalStore] = None
        self.worker: Optional[SyncWorker] = None
        self.ui_queue: "queue.Queue" = queue.Queue()
        self.current_peer: Optional[str] = None
        self._pending_status = ("Starting…", T.text_3)
        self._chat_anchor: Optional[int] = None  # oldest id shown in the chat
        # Newest id shown, when the window stops short of the end (opened
        # at a found or quoted message); None while it follows the chat.
        self._chat_ceiling: Optional[int] = None
        self._dirty_chat = False               # coalesced refresh flags
        self._dirty_list = False
        self.foreground = True                 # drives reconnect aggressiveness
        self._register_modal: Optional[RegisterModal] = None
        self.splash: Optional["SplashOverlay"] = None
        # v11: calls declined from their notification, so an offer still
        # queued for the screen does not ring again; and a call to answer
        # the moment it rings here (Answer pressed on its notification).
        self._declined_calls: set = set()
        self._answer_on_ring: Optional[str] = None
        self._watchdog: Optional[threading.Thread] = None

    # ---- lifecycle -----------------------------------------------------------
    def build(self):
        apply_theme(APPEARANCE.resolve())
        self._theme_name = T.name
        Window.clearcolor = C(T.bg)
        if IS_MOBILE:
            # Without this the soft keyboard covers the composer you are
            # typing into; 'below_target' pans just enough to keep it seen.
            Window.softinput_mode = "below_target"
        else:
            # Phone-shaped by default on desktop so the layout is exercised
            # the way it will be on a handset; still freely resizable.
            Window.size = (dp(420), dp(820))
            # The mark, not Kivy's, on the title bar, taskbar and dock.
            if DESKTOP_ICON.is_file():
                self.icon = str(DESKTOP_ICON)
        self.manager = ScreenManager(transition=NoTransition())
        self.voice = VoicePlayer()
        self._build_screens()
        Window.bind(on_keyboard=self._on_keyboard)     # Android back button
        if not IS_MOBILE:
            # Bound after the text fields' own keyboard, so heard first:
            # shortcuts, and an image pasted into a chat (v11).
            Window.bind(on_key_down=self._on_key_down)
            Window.bind(on_drop_file=self._on_drop_file)
        Clock.schedule_interval(self._drain_ui_queue, 0.15)
        Clock.schedule_interval(self._watch_system_theme, 4.0)
        self._bind_notification_taps()
        android_style_system_bars()
        # The loading screen sits over the whole app until it fades, so the
        # root is something that can stack widgets; the rest of the app
        # talks to self.manager.
        root = FloatLayout()
        root.add_widget(self.manager)
        # Layers above the screens (the menu, a call) go into `layers`.
        self.layers = root
        self.drawer: Optional[NavDrawer] = None
        self.splash = SplashOverlay()
        root.add_widget(self.splash)
        Clock.schedule_once(lambda _dt: self._probe_transport(), 0.05)
        Clock.schedule_once(self._dismiss_splash, SplashOverlay.HOLD)
        return root

    def _build_screens(self) -> None:
        """Every screen, built in the current theme and text size."""
        self.chats_screen = ChatsScreen(self)
        self.conversation_screen = ConversationScreen(self)
        self.chat_info_screen = ChatInfoScreen(self)
        self.group_info_screen = GroupInfoScreen(self)
        self.new_group_screen = NewGroupScreen(self)
        self.settings_screen = SettingsScreen(self)
        self.profile_screen = ProfileScreen(self)
        for screen in (self.chats_screen, self.conversation_screen,
                       self.chat_info_screen, self.group_info_screen,
                       self.new_group_screen, self.settings_screen,
                       self.profile_screen):
            self.manager.add_widget(screen)
        self.voice.on_progress = self.conversation_screen.on_voice_progress
        self.voice.on_stop = self.conversation_screen.on_voice_stop

    def back_target(self) -> Optional[tuple]:
        """(the page beneath, what going back does) for the page showing —
        what a swipe back reveals and then does (v11). None: the chats."""
        current = self.manager.current
        if current == "conversation":
            return "chats", self.go_back_to_chats
        if current in ("info", "group_info"):
            return "conversation", self.close_chat_info
        if current == "settings":
            back = getattr(self, "_settings_from", "chats")
            if back not in self.manager.screen_names or back == "settings":
                back = "chats"
            return back, self.close_settings
        if current == "profile":
            back = getattr(self, "_profile_from", "chats")
            if back not in self.manager.screen_names or back == "profile":
                back = "chats"
            return back, self.close_profile
        if current == "new_group":
            return "chats", self.go_back_to_chats
        return None

    def navigate_instantly(self, action: Callable) -> None:
        """Run a back action without its transition: a swipe has already
        moved the page."""
        self._instant_nav = True
        try:
            action()
        finally:
            self._instant_nav = False

    def repaint_list_if_stale(self) -> None:
        if getattr(self, "_list_stale", False) and self.store is not None:
            self._list_stale = False
            self.chats_screen.refresh_list(
                self.store.conversations(me=self.keys.address))

    def drawer_drag_begin(self) -> bool:
        if not self.keys.has_identity:
            return False
        if self.drawer is None or self.drawer.theme != T.name:
            self.drawer = NavDrawer(self)
        if self.drawer.is_open:
            return False
        self.drawer.open(drag=True)
        return True

    def drawer_drag(self, dx: float) -> None:
        if self.drawer is not None and self.drawer.is_open:
            self.drawer.progress = max(0.0, min(
                1.0, dx / max(1.0, self.drawer.panel_width())))

    def drawer_drag_end(self, dx: float, speed: float) -> None:
        drawer = self.drawer
        if drawer is None or not drawer.is_open:
            return
        if drawer.progress > 0.4 or (speed > dp(800) and dx > dp(40)):
            drawer.settle_open()
        else:
            drawer.close()

    def _navigate(self, name: str, direction: Optional[str] = "left") -> None:
        """Show screen `name`: "left" lays it over the current page, "right"
        lifts the current page off it (see LayerTransition)."""
        if name == "chats" and getattr(self, "_list_stale", False) and \
                self.store is not None:
            self._list_stale = False      # repainted before it is uncovered
            self.chats_screen.refresh_list(
                self.store.conversations(me=self.keys.address))
        if name != "conversation":
            self.conversation_screen.cancel_backfill()
        if direction is None or self.manager.current == name or \
                getattr(self, "_instant_nav", False):
            self.manager.transition = NoTransition()
        else:
            self.manager.transition = LayerTransition(
                forward=direction != "right")
        self.manager.current = name

    # =========================================================================
    #  Appearance: theme, text size, motion
    # =========================================================================
    def set_appearance(self, theme: Optional[str] = None,
                       text_size: Optional[str] = None,
                       reduce_motion: Optional[bool] = None,
                       black: Optional[bool] = None) -> None:
        if theme is not None:
            save_pref("theme", theme)
        if black is not None:
            save_pref("black", bool(black))
        if text_size is not None:
            save_pref("text_size", text_size)
        if reduce_motion is not None:
            save_pref("reduce_motion", bool(reduce_motion))
        self.apply_appearance(force=text_size is not None)

    def apply_appearance(self, force: bool = False) -> None:
        """Re-read the preferences (and the system's theme); rebuild the
        interface if anything visible changed."""
        old = (T.name, APPEARANCE.scale)
        name = APPEARANCE.resolve()
        if force or (name, APPEARANCE.scale) != old:
            self._rebuild_ui(name)

    def _watch_system_theme(self, _dt) -> None:
        """Follow the phone's dark/light switch while the app is open. The
        check can take a subprocess on a desktop, so it runs off the UI
        thread and only hops back when the answer differs."""
        if APPEARANCE.mode != "system" or getattr(self, "_theme_probe", 0):
            return
        if IS_ANDROID:
            # A cheap JNI read, and pyjnius must not be used from a thread
            # that is never detached from the JVM — so on the UI thread.
            dark = system_prefers_dark()
            if APPEARANCE.themed(dark is not False) != T.name:
                self.apply_appearance()
            return
        self._theme_probe = 1

        def probe():
            try:
                dark = system_prefers_dark()
                want = APPEARANCE.themed(dark is not False)
                if want != T.name:
                    run_on_ui(self.apply_appearance)
            finally:
                self._theme_probe = 0
        threading.Thread(target=probe, daemon=True).start()

    def _rebuild_ui(self, name: str) -> None:
        """Build every screen again in the new theme, and put the user back
        exactly where they were: same screen, same chat, same draft."""
        current = self.manager.current
        peer = self.current_peer
        screen = self.conversation_screen
        draft = screen.entry.text
        reply = screen.reply_to
        screen.cancel_recording()
        self.voice.stop()
        for view in list(Window.children):
            if isinstance(view, ModalView):
                view.dismiss(animation=False)
        apply_theme(name)
        self._theme_name = name
        Window.clearcolor = C(T.bg)
        for old in list(self.manager.screens):
            self.manager.remove_widget(old)
        self._build_screens()
        android_style_system_bars()
        self.chats_screen.refresh_header()
        self.refresh_sidebar()
        self.chats_screen.set_status(*self._pending_status)
        if peer is not None and self.store is not None:
            self._chat_anchor = None
            self.refresh_chat(peer)
            self.conversation_screen.entry.text = draft
            if reply:
                self.conversation_screen.reply_to = reply
        if current == "info" and peer:
            self.chat_info_screen.show(peer)
        elif current == "group_info" and peer and gid_of(peer):
            self.group_info_screen.show(gid_of(peer))
        elif current == "new_group":
            self.new_group_screen.show()
        elif current == "settings":
            self.settings_screen.show()
        elif current == "profile":
            self.profile_screen.show()
        if current in self.manager.screen_names:
            self._navigate(current, None)

    def _probe_transport(self) -> None:
        """Work out the relay's transport in the background at startup.

        Doing it here rather than lazily on the first API call means the
        probe overlaps with identity mining and the first-run dialog, so by
        the time anyone presses Register the scheme is already known and
        that call goes straight through.
        """
        def worker():
            base = ENDPOINT.resolve(force=not ENDPOINT.resolved)
            if base is None:
                self.ui_queue.put(
                    ("status", "Can't reach the relay — tap to retry",
                     COL_DANGER))
            elif not ENDPOINT.secure:
                self.ui_queue.put(
                    ("status", "Relay reachable (transport not secured)",
                     COL_TICK_GOLD))
        threading.Thread(target=worker, daemon=True).start()

    def _dismiss_splash(self, _dt) -> None:
        """Fade the loading screen out, then start the app proper."""
        fade = Animation(opacity=0, d=SplashOverlay.FADE)
        fade.bind(on_complete=lambda *_a: self._splash_gone())
        fade.start(self.splash)

    def _splash_gone(self) -> None:
        if self.splash is not None and self.splash.parent is not None:
            self.splash.parent.remove_widget(self.splash)
        self.splash = None
        self._post_build(0)

    def _warm_caches(self, _dt=None) -> None:
        """Draw, once and while nothing else happens, what the settings page
        would otherwise draw the first time it opens: its two QR codes."""
        keys = self.keys
        if keys is None or not keys.has_identity:
            return
        try:
            qr_texture(keys.address)
            qr_texture(json.dumps(keys.public_bundle(), separators=(",", ":")))
        except Exception as exc:
            log.debug("QR warm-up skipped: %s", exc)

    def _post_build(self, _dt) -> None:
        """Deferred until the loading screen has gone — see SplashOverlay."""
        if self.keys.has_identity:
            self._activate_identity(self.keys.active["address"])
            Clock.schedule_once(self._warm_caches, 2.5)
        else:
            NewIdentityModal(self, first_run=True).open()

    def on_stop(self) -> None:
        if self.worker is not None:
            self.worker.stop_event.set()
        if self.store is not None:
            self.store.close()

    # ---- v11: keyboard shortcuts, pasting and dropping (computers) ---------------
    def _on_key_down(self, _window, key, _scancode=None, _codepoint=None,
                     modifiers=None) -> bool:
        """Ctrl+F search (in the chat open, else everywhere), Ctrl+N new
        chat, Ctrl+Shift+M mute in a call, Ctrl+V of an image into a chat;
        Esc is back (_on_keyboard). Cmd for Ctrl on a Mac."""
        mods = set(modifiers or ())
        if not mods & {"ctrl", "meta"} or self.store is None:
            return False
        current = self.manager.current
        if key == ord("f") and not mods & {"shift", "alt"}:
            if current == "conversation":
                self.conversation_screen.open_search()
            else:
                self.open_search()
            return True
        if key == ord("n") and not mods & {"shift", "alt"}:
            self.open_compose()
            return True
        if key == ord("m") and "shift" in mods:
            if self.call is not None and not self.call.ended:
                self.toggle_call_mute()
                return True
            return False
        if key == ord("v") and not mods & {"shift", "alt"} and \
                current == "conversation" and \
                self.conversation_screen.peer is not None:
            found = clipboard_image()
            if found:
                self.conversation_screen._picked(*found)
                return True
        return False

    def _on_drop_file(self, _window, filename, *_args) -> None:
        """A file dropped onto the window: an image goes to the open chat,
        to look at before it is sent."""
        path = filename.decode("utf-8", "replace") \
            if isinstance(filename, bytes) else str(filename)
        screen = self.conversation_screen
        if self.manager.current != "conversation" or screen.peer is None:
            self._set_status("Open a chat, then drop the photo on it", T.accent)
            return
        if not is_image_file(path):
            self._set_status("Only photos can be dropped here", T.accent)
            return
        screen._picked(path, False)

    def _on_keyboard(self, _window, key, *_args) -> bool:
        """Android/Esc back, innermost first: an open sheet, highlight mode,
        the emoji panel, a recording, a pending reply, a page — and only
        then the app."""
        if key not in (27, 1001):
            return False
        sheets = [v for v in Window.children if isinstance(v, ModalView)]
        if sheets:
            top = sheets[0]
            if isinstance(top, CallOverlay):
                self.hide_call()
                return True
            if getattr(top, "dismissable", True) and top.auto_dismiss:
                top.dismiss()
            return True
        if self.close_drawer():
            return True
        current = self.manager.current
        if current in ("info", "group_info"):
            self.close_chat_info()
            return True
        if current == "profile":
            self.close_profile()
            return True
        if current == "settings":
            self.close_settings()
            return True
        if current == "new_group":
            self.go_back_to_chats()
            return True
        if current == "conversation":
            screen = self.conversation_screen
            if screen.selecting:
                screen.clear_selection()
            elif screen.searching:
                screen.close_search()
            elif screen._strip_for is not None:
                screen.close_strip()
            elif screen.emoji_panel.is_open:
                screen.close_emoji()
            elif screen.recorder is not None:
                screen.cancel_recording()
            elif screen.reply_to is not None:
                screen.cancel_reply()
            else:
                self.go_back_to_chats()
            return True
        if current == "chats":
            chats = self.chats_screen
            if chats.searching:
                chats.exit_search()
                return True
            if getattr(chats, "selecting", False):
                chats.clear_selection()
                return True
            if getattr(chats, "view", "chats") != "chats":
                chats.show_view("chats")      # the archive, or requests
                return True
        # The outermost page: Android goes to the home screen with the app
        # kept as it is; a computer's Esc does nothing (it used to close
        # the window).
        android_move_to_back()
        return True

    # =========================================================================
    #  Identity lifecycle
    # =========================================================================
    def _activate_identity(self, address: str) -> None:
        """Switch the live identity WITHOUT restarting: stop the old sync
        worker, swap crypto/API/store, rebuild the UI, start a new worker."""
        if self.worker is not None:
            self.worker.stop_event.set()
            self.worker = None
        if self.store is not None:
            self.store.close()
            self.store = None
        self.keys.activate(address)
        self.crypto = CryptoEngine(self.keys)
        self.api = ApiClient(self.keys)
        self.store = LocalStore(self.keys.store_path())
        self._load_pictures()
        self.current_peer = None
        self._navigate("chats", None)
        self.chats_screen.refresh_header()
        self.refresh_sidebar()
        if self.keys.username:
            self._start_worker()
            self._ask_notification_permission()
            self._sync_background_service()
            action, call_id = self._launch_call_action()
            if action == "answer" and call_id:
                self._answer_on_ring = str(call_id)
            self._check_pending_offer()
            peer = self._launch_peer()
            if peer and self._known_conversation(peer):
                self.open_conversation(peer)
        else:
            self._set_status("Pick a username to start chatting",
                             COL_TICK_GOLD)
            RegisterModal(self).open()

    def _load_pictures(self) -> None:
        """Which disc shows which picture, for the identity now in use."""
        PICTURES.load(self.store, [i["address"] for i in
                                   self.keys.identities])
        Avatar.refresh()

    def _on_picture(self, peer: str, path: Optional[str]) -> None:
        """A picture arrived (or went): every disc showing it follows."""
        PICTURES.set(peer, path)
        Avatar.refresh(peer)

    def _start_worker(self) -> None:
        self.worker = SyncWorker(self)
        self.worker.start()
        self._set_status("Connecting…", COL_TEXT_DIM)
        # Learn what the relay can carry (media needs v9) off the UI thread,
        # so the composer knows before anyone reaches for the camera.
        api = self.api
        threading.Thread(target=lambda: api.features(), daemon=True).start()

    def media_available(self) -> bool:
        """Non-blocking: answers from the cached /api/health probe."""
        features = getattr(self.api, "_features", None) if self.api else None
        if features is None:
            if self.api is not None:
                api = self.api
                threading.Thread(target=lambda: api.features(),
                                 daemon=True).start()
            return False
        return bool(features.get("blobs"))

    def on_registered(self) -> None:
        self.chats_screen.refresh_header()
        self._start_worker()

    def on_identity_created(self, address: str) -> None:
        self._activate_identity(address)

    _pause_beat = None

    def pause_identity(self) -> Optional[str]:
        """Stop syncing and close the database, for a restore that is about
        to change the files. Returns the identity that was in use.

        The app's heartbeat goes on meanwhile (v12): it is what keeps the
        background service from syncing, and a service that took over while
        a restore ran would hold a database open as it was replaced, and
        store what arrived in a file nobody would read again."""
        if self.worker is not None:
            self.worker.stop_event.set()
            self.worker = None
        if self.store is not None:
            self.store.close()
            self.store = None
        write_heartbeat("app")
        if self._pause_beat is None:
            self._pause_beat = Clock.schedule_interval(
                lambda _dt: write_heartbeat("app"), HEARTBEAT_EVERY)
        active = self.keys.active
        return active["address"] if active else None

    def resume_identity(self, previous: Optional[str]) -> None:
        """After a restore: back to the identity that was in use, or, on a
        new device, to the first one restored."""
        if self._pause_beat is not None:
            self._pause_beat.cancel()
            self._pause_beat = None
        if previous is None and self.keys.has_identity:
            previous = self.keys.identities[0]["address"]
        if previous is not None:
            self._activate_identity(previous)

    def on_identity_removed(self, address: str, note: str = "") -> None:
        """Finish removing an identity and land somewhere sensible.

        If the identity being removed is the ACTIVE one its worker and store
        must be torn down before the files are deleted, or the sync thread
        keeps writing to a database that is being unlinked.
        """
        if address == self.keys.address:
            if self.worker is not None:
                self.worker.stop_event.set()
                self.worker = None
            if self.store is not None:
                self.store.close()
                self.store = None
        remaining = self.keys.remove_identity(address)
        if remaining:
            self._activate_identity(remaining)
            self._set_status(f"Identity removed{note}", COL_TEXT_DIM)
        else:
            # Nothing left: return to the first-run experience rather than
            # leaving a half-live UI pointing at an identity that is gone.
            self.current_peer = None
            PICTURES.load(None)
            self.chats_screen.refresh_header()
            self.chats_screen.refresh_list([])
            self._navigate("chats", None)
            self._set_status(f"No identities on this device{note}",
                             COL_TICK_GOLD)
            NewIdentityModal(self, first_run=True).open()

    def on_identity_dialog_closed(self) -> None:
        self.chats_screen.refresh_header()

    def on_contact_added(self, address: str) -> None:
        self.refresh_sidebar()
        self.open_conversation(address)

    # =========================================================================
    #  Navigation
    # =========================================================================
    def _known_conversation(self, peer: str) -> bool:
        if self.store is None:
            return False
        kind = self.conversation_kind(peer)
        if kind == "self":
            return True
        if kind == "group":
            return self.store.group(gid_of(peer)) is not None
        return self.store.get_contact(peer) is not None

    def _auto_read(self, peer: str) -> bool:
        if self.conversation_kind(peer) != "dm":
            return True
        return bool((self.store.get_contact(peer) or {}).get("auto_read", 1))

    def open_conversation(self, peer: str) -> None:
        if self.store is None:
            return
        if IS_ANDROID:
            android_clear_notification(peer)
        self.current_peer = peer
        self._chat_anchor = None                # fresh window per chat
        self._chat_ceiling = None
        # v12: with messages unread, the chat opens at the first of them,
        # under a "New messages" line; more than the first paint holds and
        # the window starts there (three messages before it, for context).
        unread = self.store.unread_for(peer)
        first = unread[0][0] if unread else None
        self.conversation_screen.mark_new_from(first, len(unread))
        if first is not None and len(unread) > FIRST_PAINT - 3:
            self._chat_anchor, self._chat_ceiling = self.store.id_around(
                peer, first, 3, CHAT_PAGE_SIZE)
            self.conversation_screen._rendered_peer = None
        if (self.store.chat_flags().get(peer) or {}).get("marked_unread"):
            self.store.set_chat_flag([peer], "marked_unread", 0)
        if self._auto_read(peer):
            self.mark_peer_read(peer, refresh=False)
        self._navigate("conversation", "left")
        self.refresh_chat(peer)
        self.refresh_sidebar()

    def open_conversation_at(self, peer: str, message_id: int) -> None:
        """Open a chat at one message, however far back: a window around
        it (CHAT_PAGE_SIZE / 3 older, as many newer), scrolled to it, the
        message flashing. Newer messages follow as you scroll down; the
        jump button returns to the end."""
        if self.store is None:
            return
        if peer == self.current_peer and \
                self.conversation_screen.focus_message(message_id):
            self._navigate("conversation", "left")
            return
        self.open_conversation(peer)
        lo, hi = self.store.id_around(peer, message_id, CHAT_PAGE_SIZE // 3,
                                      CHAT_PAGE_SIZE // 3)
        self._chat_anchor, self._chat_ceiling = lo, hi
        self.conversation_screen._rendered_peer = None     # a new window
        self.refresh_chat(peer)
        Clock.schedule_once(lambda _dt: self.conversation_screen.focus_message(
            message_id), 0.05)

    def load_newer_messages(self) -> None:
        """Reading back in a window: the next page of newer messages joins
        on below; reaching the end, the chat follows new arrivals again."""
        peer = self.current_peer
        if peer is None or self._chat_ceiling is None:
            return
        newer = self.store.messages_after(peer, self._chat_ceiling,
                                          CHAT_PAGE_SIZE // 2)
        caught_up = not newer or self.store.count_after(
            peer, newer[-1]["id"]) == 0
        self._chat_ceiling = None if caught_up else newer[-1]["id"]
        self.refresh_chat(peer)

    def reopen_live(self) -> None:
        """Back to the end of the conversation from a window further back."""
        peer = self.current_peer
        if peer is None:
            return
        self._chat_anchor, self._chat_ceiling = None, None
        self.conversation_screen._rendered_peer = None
        self.refresh_chat(peer)
        self.conversation_screen.scroll_to_bottom(animate=False)

    def go_back_to_chats(self) -> None:
        screen = self.conversation_screen
        screen.keep_draft()
        screen.clear_selection()
        screen.cancel_recording()
        screen.close_emoji()
        self.voice.stop()
        self.current_peer = None
        self._navigate("chats", "right")
        self.refresh_sidebar()

    # =========================================================================
    #  Rendering
    # =========================================================================
    def refresh_sidebar(self) -> None:
        """Repaint the conversation list (name kept from v2 for continuity).
        Hidden behind another screen, it is only marked stale and repainted
        when it shows again: opening a chat no longer pays for it."""
        if self.store is None:
            return
        if self.manager.current != "chats":
            self._list_stale = True
            return
        self._list_stale = False
        conversations = self.store.conversations(me=self.keys.address)
        self.chats_screen.refresh_list(conversations)
        self._title_unread(conversations)

    def _title_unread(self, conversations: list) -> None:
        """A computer's window says how many unread messages wait in chats
        that are not muted: "(3) Ferritext" in its title and taskbar."""
        if IS_MOBILE:
            return
        unread = sum(int(c.get("unread") or 0) for c in conversations
                     if not c.get("muted") and not c.get("blocked"))
        base = f"{APP_NAME} {APP_VERSION} — end-to-end encrypted messenger"
        title = f"({unread}) {base}" if unread else base
        if title != getattr(self, "_title_now", None):
            self._title_now = title
            try:
                Window.set_title(title)
            except Exception:
                pass

    def refresh_chat(self, peer: Optional[str]) -> None:
        """Repaint the open conversation from the local store.

        Only the most recent CHAT_PAGE_SIZE messages are materialised; older
        ones are paged in on demand. With the incremental renderer the cost
        of an arriving message is independent of the conversation's length.
        """
        if peer is None or peer != self.current_peer or self.store is None:
            return
        kind = self.conversation_kind(peer)
        contact = (self.store.get_contact(peer) or {}) if kind == "dm" else {}
        group = self.store.group(gid_of(peer)) if kind == "group" else None
        unread = self.store.unread_for(peer)
        self.conversation_screen.set_peer(peer, contact, len(unread), kind,
                                          group)
        cold = self._chat_anchor is None
        if cold:              # cold open: what fills the screen, at once
            messages = self.store.messages_for(peer, limit=FIRST_PAINT)
            self._chat_anchor = messages[0]["id"] if messages else None
        else:                                    # anchored: list only grows
            messages = self.store.messages_for(peer,
                                               from_id=self._chat_anchor,
                                               to_id=self._chat_ceiling)
        reactions = self.store.reactions_for(
            peer, [m.get("client_msg_id") for m in messages])
        for msg in messages:
            msg["reactions"] = reactions.get(msg.get("client_msg_id"), [])
        self.conversation_screen.has_older = bool(
            self._chat_anchor is not None
            and self.store.has_messages_before(peer, self._chat_anchor))
        ticks = bool(contact.get("ticks_enabled", 1)) if kind == "dm" \
            else True
        self.conversation_screen.render(messages, ticks,
                                        self._mark_single_read, peer=peer)
        self.conversation_screen.set_newer(
            0 if self._chat_ceiling is None else
            self.store.count_after(peer, self._chat_ceiling))
        if cold and self.conversation_screen.has_older:
            # The rest of the first page, built once the chat is showing.
            Clock.schedule_once(lambda _dt: self._extend_history(
                peer, CHAT_PAGE_SIZE - len(messages)), LAYER_IN + 0.04)
        # Photos/voice notes that arrived while the background service was
        # syncing were never downloaded; fetch them now someone is looking —
        # those the download rules (v14) let come by themselves.
        for msg in messages:
            if msg["direction"] == "in" and \
                    msg.get("media_state") == "pending" and \
                    downloads_by_itself(self.store, msg):
                self.fetch_media(msg["id"])

    def load_older_messages(self) -> None:
        """Page one more CHAT_PAGE_SIZE of history in above the anchor."""
        if self.current_peer is not None:
            self._extend_history(self.current_peer, CHAT_PAGE_SIZE)

    def _extend_history(self, peer: str, count: int) -> None:
        """Up to `count` messages older than those shown, prepended a few a
        frame (ConversationScreen.run_backfill) — never a full rebuild."""
        screen = self.conversation_screen
        if peer != self.current_peer or self._chat_anchor is None or \
                screen._rendered_peer != peer or screen._backfill_ev or \
                count <= 0:
            return
        older = self.store.messages_for(peer, limit=count,
                                        before_id=self._chat_anchor)
        if not older:
            screen.set_has_older(False)
            return
        reactions = self.store.reactions_for(
            peer, [m.get("client_msg_id") for m in older])
        for msg in older:
            msg["reactions"] = reactions.get(msg.get("client_msg_id"), [])
        pages = [older[max(0, end - BACKFILL_CHUNK):end]
                 for end in range(len(older), 0, -BACKFILL_CHUNK)]

        def page_done(page):
            # The window now starts at this page: what refresh_chat lists
            # stays exactly what is drawn, so arrivals still append.
            self._chat_anchor = page[0]["id"]

        def done():
            screen.set_has_older(self.store.has_messages_before(
                peer, self._chat_anchor))
        screen.run_backfill(pages, screen._rendered_ticks, on_page=page_done,
                            on_done=done)

    # =========================================================================
    #  Read marking (the 3/3 tick, from the recipient's side)
    # =========================================================================
    def mark_peer_read(self, peer: Optional[str], refresh: bool = True) -> None:
        if peer is None or self.store is None:
            return
        unread = self.store.unread_for(peer)
        if not unread:
            return
        self.store.mark_read_local([local_id for local_id, _ in unread])
        server_ids = [sid for _, sid in unread if sid]
        if server_ids and self.worker is not None:
            threading.Thread(target=self.worker.send_read_receipts,
                             args=(server_ids,), daemon=True).start()
        if refresh:
            self.refresh_chat(peer)
            self.refresh_sidebar()

    def _mark_single_read(self, local_id: int,
                          server_id: Optional[int]) -> None:
        self.store.mark_read_local([local_id])
        if server_id and self.worker is not None:
            threading.Thread(target=self.worker.send_read_receipts,
                             args=([server_id],), daemon=True).start()
        self.refresh_chat(self.current_peer)
        self.refresh_sidebar()

    # =========================================================================
    #  Sending
    # =========================================================================
    def send_current(self) -> None:
        if self._chat_ceiling is not None:      # what you send is at the end
            self.reopen_live()
        self._send_current()

    def _send_current(self) -> None:
        """Send what is in the composer — as a reply, if one is pending."""
        if self.store is None or self.current_peer is None:
            return
        screen = self.conversation_screen
        if screen.closed_note.parent is not None:
            return
        body = sanitize_text(screen.entry.text)
        if not body:
            return
        preview = screen.take_preview(body)
        screen.entry.text = ""
        reply = screen.take_reply()
        self.send_text(self.current_peer, body, reply=reply, preview=preview)

    def _after_local_row(self, peer: str) -> None:
        if threading.current_thread() is threading.main_thread():
            if peer == self.current_peer:
                self.refresh_chat(peer)
            self._dirty_list = True
        else:                         # media pipeline: repaint via the queue
            self.ui_queue.put(("message_stored", peer))

    # =========================================================================
    #  Message actions (v9): star, delete, forward, share, copy
    # =========================================================================
    def star_messages(self, local_ids: list, starred: bool) -> None:
        self.store.set_starred(local_ids, starred)
        self.refresh_chat(self.current_peer)

    def delete_messages(self, local_ids: list, for_everyone: bool) -> None:
        """Delete for me, or — for the user's OWN messages only — for both.

        For both: the instruction is sent first, and nothing is removed here
        until the relay has accepted it, so a failure leaves the messages
        visible and the user able to try again, rather than gone from this
        screen while still sitting on the other phone.
        """
        rows = self.store.messages_by_ids(local_ids)
        if not rows:
            return
        peer = rows[0]["peer"]
        if not for_everyone:
            for row in self.store.delete_messages([r["id"] for r in rows]):
                discard_media_file(row.get("media_path"))
            self.refresh_chat(self.current_peer)
            self._dirty_list = True
            return
        own = [r for r in rows if r["direction"] == "out"
               and r.get("client_msg_id")]
        if len(own) != len(rows):
            self._set_status("You can only delete your own messages for "
                             "everyone", COL_TICK_GOLD)
            return

        if self.conversation_kind(peer) == "self":
            self._finish_delete_for_everyone(own, True)
            return

        def work():
            ok = self._send_control(
                peer, {"op": "delete",
                       "cids": [r["client_msg_id"] for r in own]},
                "Deleted a message" if len(own) == 1
                else f"Deleted {len(own)} messages")
            run_on_ui(self._finish_delete_for_everyone, own, ok)
        threading.Thread(target=work, daemon=True).start()

    def _finish_delete_for_everyone(self, rows: list, ok: bool) -> None:
        if not ok:
            self._set_status("Couldn't delete for everyone — check your "
                             "connection and try again", COL_DANGER)
            return
        for row in self.store.delete_messages([r["id"] for r in rows]):
            discard_media_file(row.get("media_path"))
        self.refresh_chat(self.current_peer)
        self.refresh_sidebar()

    def forward_messages(self, local_ids: list, targets: list) -> int:
        """Send copies to other contacts of this identity. Photos and voice
        notes are forwarded by REFERENCE — the sealed blob already on the
        relay, with its key — so nothing is uploaded again."""
        rows = [r for r in self.store.messages_by_ids(local_ids)
                if r.get("kind") != "event"]
        sent = 0
        for target in targets:
            to_self = self.conversation_kind(target) == "self"
            for row in rows:
                ext = json.loads(row.get("ext") or "{}")
                media = ext.get("media")
                local = row.get("media_path") and Path(
                    row["media_path"]).is_file()
                if row["kind"] in ("image", "voice") and media and (
                        media.get("blob") or to_self):
                    # By REFERENCE: the sealed blob already on the relay.
                    self._queue_message(
                        target, row["body"],
                        {"k": "media", "media": media, "fwd": 1}, row["kind"],
                        {"media": media, "fwd": 1},
                        media_path=row.get("media_path"),
                        media_state="ready" if local or to_self else "")
                elif row["kind"] in ("image", "voice") and media and local:
                    # Kept only here (a note to self): upload it now.
                    extra = {k: v for k, v in media.items()
                             if k in ("w", "h", "thumb", "dur", "wave", "cap")}
                    data = Path(row["media_path"]).read_bytes()
                    threading.Thread(target=self._send_media, args=(
                        target, row["kind"], data,
                        media.get("mime", "application/octet-stream"), extra,
                        row["body"], None,
                        Path(row["media_path"]).suffix.lstrip(".") or "bin"),
                        daemon=True).start()
                else:
                    self.send_text(target, row["body"], forwarded=True)
                sent += 1
        self.refresh_sidebar()
        return sent

    # =========================================================================
    #  Reactions (v9.1)
    # =========================================================================
    def react(self, local_id: int, emoji: str) -> None:
        """Add a reaction to a message, or take it back: choosing one you
        already gave removes it. Up to MAX_REACTIONS per person (v12); one
        more replaces the oldest. Recorded here at once; the others hear
        about it in the background."""
        row = self.store.message(local_id) if self.store else None
        emoji = sanitize_emoji(emoji)
        if not row or not row.get("client_msg_id") or \
                row.get("kind") == "event" or not emoji:
            return
        peer, cid, me = row["peer"], row["client_msg_id"], self.keys.address
        mine = self.store.reactions_of(peer, cid, me)
        adding = emoji not in mine
        mine = (mine + [emoji])[-MAX_REACTIONS:] if adding else \
            [e for e in mine if e != emoji]
        if not self.store.set_reactions(peer, cid, me, mine):
            return
        self.ui_queue.put(("reaction", peer, cid, me, emoji if adding
                           else ""))
        self.refresh_chat(self.current_peer)
        if self.conversation_kind(peer) == "self":
            return
        snip = single_line_text(message_text(row) or {
            "image": "a photo", "voice": "a voice message"}.get(
                row.get("kind"), "a message"), 40)
        fallback = (f"Reacted {emoji} to \u201c{snip}\u201d" if adding
                    else "Removed a reaction")
        # 'e', the latest left, is what a release before 12 keeps.
        ctl = {"op": "react", "cid": cid, "e": mine[-1] if mine else "",
               "es": mine}

        def work():
            if not self._send_control(peer, ctl, fallback):
                self.ui_queue.put(("status", "Couldn't send that reaction — "
                                   "it shows here only", COL_TICK_GOLD))
        threading.Thread(target=work, daemon=True).start()

    # =========================================================================
    #  Groups (v9.1)
    # =========================================================================
    def create_group(self, name: str, addresses: list) -> Optional[str]:
        """Create a group of us + `addresses` (contacts), with us as admin,
        and send each member the invitation. Returns the conversation key."""
        name = sanitize_text(name)[:MAX_GROUP_NAME].strip()
        members = [{"a": self.keys.address, "k": self.keys.public_key_hex,
                    **({"u": self.keys.username} if self.keys.username
                       else {})}]
        for address in dict.fromkeys(addresses):
            contact = self.store.get_contact(address)
            if contact is None or address == self.keys.address:
                continue
            entry = {"a": address, "k": contact["public_key"]}
            if contact.get("username"):
                entry["u"] = contact["username"]
            members.append(entry)
        if not name or len(members) < 2 or len(members) > MAX_GROUP_MEMBERS:
            return None
        gid = os.urandom(16).hex()
        state = {"id": gid, "name": name, "v": 1,
                 "admin": self.keys.address, "members": members}
        self.store.save_group(state, "active")
        peer = group_peer(gid)
        self.store.add_event(peer, f"You created \u201c{name}\u201d")
        threading.Thread(target=self._announce_group, args=(
            gid, (), f"{self.keys.username or 'Someone'} added you to the "
                     f"group \u201c{name}\u201d", False), daemon=True).start()
        self.refresh_sidebar()
        return peer

    def _announce_group(self, gid: str, also=(), fallback: str = "",
                        bump: bool = True) -> None:
        if not self._publish_group_state(gid, also, fallback, bump):
            self.ui_queue.put(("status", "Not every member could be reached "
                               "yet — they'll get the group when they "
                               "next receive a message", COL_TICK_GOLD))
        self.ui_queue.put(("message_stored", group_peer(gid)))

    def rename_group(self, gid: str, name: str) -> bool:
        group = self.store.group(gid)
        name = sanitize_text(name)[:MAX_GROUP_NAME].strip()
        if not group or group["admin"] != self.keys.address or not name \
                or name == group["name"]:
            return False
        state = self._group_state(gid)
        state["name"] = name
        self.store.save_group(state, group["state"])
        self.store.add_event(group_peer(gid), f"You renamed the group "
                                              f"\u201c{name}\u201d")
        threading.Thread(target=self._announce_group, args=(gid,),
                         daemon=True).start()
        self.refresh_chat(self.current_peer)
        self.refresh_sidebar()
        return True

    def add_group_members(self, gid: str, addresses: list) -> int:
        group = self.store.group(gid)
        if not group or group["admin"] != self.keys.address:
            return 0
        state = self._group_state(gid)
        have = {m["a"] for m in state["members"]}
        added = []
        for address in addresses:
            contact = self.store.get_contact(address)
            if contact is None or address in have or \
                    len(state["members"]) >= MAX_GROUP_MEMBERS:
                continue
            entry = {"a": address, "k": contact["public_key"]}
            if contact.get("username"):
                entry["u"] = contact["username"]
            state["members"].append(entry)
            added.append(contact.get("username") or short_addr(address, 10))
        if not added:
            return 0
        self.store.save_group(state, group["state"])
        self.store.add_event(group_peer(gid), "You added " + ", ".join(added))
        threading.Thread(target=self._announce_group, args=(gid,),
                         daemon=True).start()
        self.refresh_chat(self.current_peer)
        return len(added)

    def remove_group_member(self, gid: str, address: str) -> bool:
        group = self.store.group(gid)
        if not group or group["admin"] != self.keys.address or \
                address == self.keys.address:
            return False
        gone = [m for m in group["members"] if m["a"] == address]
        if not gone:
            return False
        state = self._group_state(gid)
        state["members"] = [m for m in state["members"] if m["a"] != address]
        if len(state["members"]) < 2:
            return False
        self.store.save_group(state, group["state"])
        self.store.add_event(group_peer(gid), "You removed " + (
            gone[0].get("u") or short_addr(address, 10)))
        threading.Thread(target=self._announce_group, args=(
            gid, [(address, gone[0]["k"])]), daemon=True).start()
        self.refresh_chat(self.current_peer)
        return True

    def leave_group(self, gid: str) -> None:
        """Tell every member, then keep the history read-only here."""
        group = self.store.group(gid)
        if not group or group["state"] != "active":
            return
        recipients = self.group_recipients(gid)
        self.store.set_group_state(gid, "left")
        self.store.add_event(group_peer(gid), "You left the group")

        def work():
            for address, pub in recipients:
                self._send_control_to(address, {"op": "leave", "grp": gid},
                                      f"{self.keys.username or 'A member'} "
                                      f"left \u201c{group['name']}\u201d",
                                      pub=pub)
            self.ui_queue.put(("message_stored", group_peer(gid)))
        threading.Thread(target=work, daemon=True).start()
        self.refresh_chat(self.current_peer)
        self.refresh_sidebar()

    def set_group_notify(self, gid: str, on: bool) -> None:
        """On: unmute the group. Off: offer how long to mute it."""
        if on:
            self.set_mute([group_peer(gid)], None)
        else:
            self.choose_mute([group_peer(gid)])

    def copy_text(self, text: str) -> None:
        Clipboard.copy(text)
        self._set_status("Copied", COL_OK)

    def open_link(self, url: str) -> None:
        """A link tapped in a message: first, where it leads (v11)."""
        LinkSheet(self, url).open()

    def share_messages(self, local_ids: list) -> None:
        """Hand messages to another app: Android's share sheet, or — on a
        desktop, which has no share sheet — the clipboard."""
        rows = self.store.messages_by_ids(local_ids)
        if not rows:
            return
        image = next((r for r in rows if r["kind"] == "image"
                      and r.get("media_path")), None)
        text = "\n\n".join(r["body"] for r in rows if r["kind"] == "text")
        if IS_ANDROID:
            try:
                if image is not None and len(rows) == 1:
                    android_share_image(image["media_path"])
                else:
                    android_share_text(text or rows[0]["body"])
                return
            except Exception:
                log.exception("share sheet failed; copying instead")
        self.copy_text(text or rows[0]["body"])
        self._set_status("Copied — paste it into any app", COL_OK)

    # =========================================================================
    #  Media (v9): photos and voice notes
    # =========================================================================
    def send_image(self, path: str, caption: str = "",
                   temporary: bool = False) -> None:
        peer = self.current_peer
        if peer is None:
            return
        reply = self.conversation_screen.take_reply()
        threading.Thread(target=self._prepare_image,
                         args=(peer, path, caption, reply, temporary),
                         daemon=True).start()

    def _prepare_image(self, peer, path, caption, reply,
                       temporary: bool = False) -> None:
        try:
            data, width, height, thumb = compress_image(path)
        except Exception as exc:
            log.warning("could not read image %s: %s", path, exc)
            self.ui_queue.put(("status", "That file isn't an image this "
                               "app can read", COL_DANGER))
            return
        finally:
            # The full-size original (with its camera details) is not kept:
            # what is sent, and stays, is the compressed copy.
            if temporary:
                discard_media_file(path)
        extra = {"w": width, "h": height, "thumb": thumb}
        if caption:
            extra["cap"] = caption
        self._send_media(peer, "image", data, "image/jpeg", extra,
                         caption or "Photo", reply, "jpg")

    def send_voice(self, path: str, duration_ms: int, wave: str = "") -> None:
        peer = self.current_peer
        if peer is None:
            return
        reply = self.conversation_screen.take_reply()

        def work():
            try:
                data = Path(path).read_bytes()
            except OSError as exc:
                self.ui_queue.put(("status", f"Recording unavailable: {exc}",
                                   COL_DANGER))
                return
            finally:
                discard_media_file(path)
            extra = {"dur": int(duration_ms)}
            if wave:
                extra["wave"] = wave
            # A phone records AAC (.m4a); a computer, WAV.
            wav = path.lower().endswith(".wav")
            self._send_media(peer, "voice", data,
                             "audio/wav" if wav else "audio/mp4", extra,
                             voice_label(duration_ms), reply,
                             "wav" if wav else "m4a")
        threading.Thread(target=work, daemon=True).start()

    def _send_media(self, peer, kind, data, mime, extra, body, reply,
                    suffix) -> None:
        """Worker thread: keep a local copy, seal, upload, then send the
        reference. The bubble appears at once, marked 'uploading'. A note to
        self keeps the file here and uploads nothing; a group's members all
        share one upload."""
        to_self = self.conversation_kind(peer) == "self"
        if not to_self and not (self.api is not None and
                                self.api.features().get("blobs")):
            self.ui_queue.put((
                "status", "This relay can't carry photos or voice notes "
                "yet — it needs the v9 relay", COL_TICK_GOLD))
            return
        if len(data) > MAX_MEDIA_BYTES - 64:
            self.ui_queue.put(("status", "That's too large to send",
                               COL_DANGER))
            return
        MEDIA_DIR.mkdir(parents=True, exist_ok=True)
        local_path = MEDIA_DIR / f"{uuid.uuid4().hex}.{suffix}"
        try:
            local_path.write_bytes(data)
        except OSError as exc:
            self.ui_queue.put(("status", f"Could not save media: {exc}",
                               COL_DANGER))
            return
        media = dict(extra, kind=kind, mime=mime, size=len(data))
        ext = {"media": media}
        if reply:
            ext["reply"] = reply
        rows = {}
        self._queue_message(
            peer, body, {}, kind, ext, media_path=str(local_path),
            media_state="ready" if to_self else "uploading",
            on_local_row=lambda lid, cid: rows.update(id=lid, cid=cid))
        local_id, cid = rows.get("id"), rows.get("cid")
        if local_id is None or to_self:
            return
        self._upload_media(local_id, peer, body, cid, data)

    def retry_media(self, local_id: int) -> None:
        """Re-run a failed upload from the copy kept on this device: the
        same message, in its place (v14; it used to be replaced)."""
        row = self.store.message(local_id)
        if not row or not row.get("media_path"):
            return
        threading.Thread(target=self._upload_media,
                         args=(local_id, row["peer"], row["body"],
                               row["client_msg_id"]), daemon=True).start()

    def fetch_media(self, local_id: int) -> None:
        """Download + verify + decrypt one media message, in the background.

        A 404/410 from the relay means it let the blob expire: the message
        is marked 'expired' and the bubble offers to ask the sender for it
        again, which their device does automatically if it still has it.
        """
        row = self.store.message(local_id) if self.store else None
        if not row or row["direction"] != "in":
            return
        media = json.loads(row.get("ext") or "{}").get("media") or {}
        if not media.get("blob") or row.get("media_state") in (
                "downloading", "ready", "unreadable"):
            return
        self.store.set_media(local_id, state="downloading")
        peer = row["peer"]

        def work():
            try:
                blob = self.api.download_blob(media["blob"])
                data = open_media(blob, media["key"], media["sha"])
                if row["kind"] == "image":
                    # v12: measured before anything draws it.
                    data = safe_received_image(data)
                    if data is None:
                        log.warning("a photo that is no picture of a sane "
                                    "size was not kept")
                        self.store.set_media(local_id, state="unreadable")
                        self.ui_queue.put(("message_stored", peer))
                        return
                MEDIA_DIR.mkdir(parents=True, exist_ok=True)
                suffix = media_suffix(row["kind"], media.get("mime"))
                target = MEDIA_DIR / f"{row.get('client_msg_id') or uuid.uuid4().hex}.{suffix}"
                target.write_bytes(data)
                self.store.set_media(local_id, path=str(target),
                                     state="ready")
            except ApiClient.ApiError as exc:
                self.store.set_media(
                    local_id, state="expired" if exc.status in (404, 410)
                    else "failed")
            except (requests.RequestException, ValueError, OSError) as exc:
                log.warning("media download failed: %s", exc)
                self.store.set_media(local_id, state="failed")
            self.ui_queue.put(("message_stored", peer))
        threading.Thread(target=work, daemon=True).start()

    def download_on_tap(self, msg: dict) -> None:
        """v14 (B14): a tap downloads a photo or voice note that waited; on
        mobile data it asks first, unless told not to ask again."""
        if on_metered_network() and download_pref("ask_metered"):
            MobileDataSheet(self, msg).open()
        else:
            self.fetch_media(msg["id"])

    def request_resend(self, local_id: int) -> None:
        """Ask the sender to upload an expired photo/voice note again."""
        row = self.store.message(local_id)
        if not row or not row.get("client_msg_id"):
            return
        peer = row["peer"]
        what = "voice message" if row["kind"] == "voice" else "photo"
        self.store.set_media(local_id, state="requested")
        self.refresh_chat(self.current_peer)
        gid = gid_of(peer)

        def work():
            op = {"op": "resend", "cid": row["client_msg_id"]}
            if gid:
                op["grp"] = gid
                ok = self._send_control_to(row.get("author") or "", op,
                                           f"Please send that {what} again")
            else:
                ok = self._send_control(peer, op,
                                        f"Please send that {what} again")
            if not ok:
                self.store.set_media(local_id, state="expired")
                self.ui_queue.put(("message_stored", peer))
        threading.Thread(target=work, daemon=True).start()

    # =========================================================================
    #  Voice calls
    # =========================================================================
    call: Optional["Call"] = None
    _call_overlay = None
    _call_pill = None
    _ringer = None
    _call_clock = None
    _call_service_on = False

    def call_blocker(self, peer: Optional[str]) -> Optional[str]:
        """Why `peer` cannot be called from here, now — or None."""
        if not peer or self.store is None:
            return "Open a chat to call"
        if self.conversation_kind(peer) != "dm":
            return "Calls are between two people"
        if self.call is not None and not self.call.ended:
            return "You are already in a call"
        if self.store.is_blocked(peer):
            return "Unblock them to call"
        features = self.api.features() if self.api is not None else {}
        if not features.get("calls"):
            return "Calls need the relay to be updated first"
        contact = self.store.get_contact(peer) or {}
        if not contact.get("caps", 0) & LocalStore.CAP_CALL:
            return ("They can take calls once they run Ferritext 9.1.2 or "
                    "later — and have written to you since")
        if not calls_possible_here():
            return "This computer has no microphone or speaker to call with"
        return None

    def start_call(self, peer: Optional[str] = None) -> None:
        peer = peer or self.current_peer
        why = self.call_blocker(peer)
        if why:
            self._set_status(why, T.accent)
            return

        def go():
            if self.call is not None and not self.call.ended:
                return
            call = Call(peer, outgoing=True)
            self.call = call
            self.show_call()
            self._start_call_clock()
            # v11: the call service from the moment of dialling. Android
            # starts a microphone service only for an app on screen, and a
            # caller who leaves while it rings would otherwise be answered
            # with their microphone silent.
            if IS_ANDROID and not self._call_service_on:
                try:
                    android_call_service(True)
                    self._call_service_on = True
                except Exception:
                    log.exception("could not start the call service")
            threading.Thread(target=self._place_call, args=(call,),
                             daemon=True).start()
        self._with_microphone(go)

    def _with_microphone(self, then: Callable[[], None]) -> None:
        if IS_ANDROID and not android_has_permission(
                "android.permission.RECORD_AUDIO"):
            def answered(_p, grants):
                if grants and all(grants):
                    run_on_ui(then)
                else:
                    run_on_ui(self._set_status, "Calls need the microphone "
                              "permission", T.accent)
            android_request_permissions(["android.permission.RECORD_AUDIO"],
                                        answered)
            return
        then()

    def _call_relay(self) -> tuple:
        """(the relay's call address, a ticket for it) — or (None, '') when
        the relay offers none, and only a direct way can work."""
        features = self.api.features() if self.api is not None else {}
        if not features.get("calls"):
            return None, ""
        try:
            from urllib.parse import urlsplit
            data = self.api.call_ticket()
            port = int(data.get("udp") or features.get("call_udp") or 0)
            host = urlsplit(ENDPOINT.base or "").hostname or ""
            found = socket.getaddrinfo(host, port, socket.AF_INET,
                                       socket.SOCK_DGRAM)
            return (found[0][4][0], port), str(data.get("ticket") or "")
        except Exception as exc:
            log.warning("no way through the relay for a call: %s", exc)
            return None, ""

    def _new_engine(self, call: "Call", role: int, relay, ticket: str,
                    ) -> "CallEngine":
        engine = CallEngine(
            call.id, call.tag_bytes, role, relay, ticket,
            on_event=lambda kind, value, cid=call.id: self.ui_queue.put(
                ("call_engine", cid, kind, value)),
            send_ws=self._call_ws_send)
        call.engine = engine
        engine.start()
        if call.ended:
            engine.stop()
        return engine

    @staticmethod
    def _await_relay(call: "Call", engine: "CallEngine", relay) -> None:
        """Give the relay a moment to say where we are, so the first
        message can carry our public address."""
        until = time.monotonic() + 1.0
        while relay and not engine.relay_ok and not call.ended and \
                time.monotonic() < until:
            time.sleep(0.02)

    def _place_call(self, call: "Call") -> None:
        """Worker thread: the caller's side of setting up."""
        relay, ticket = self._call_relay()
        if call.ended:
            return
        engine = self._new_engine(call, 0, relay, ticket)
        self._await_relay(call, engine, relay)
        if call.ended:
            return
        op = {"op": "call", "id": call.id, "tag": call.tag, "k": call.pub,
              "codecs": call_codecs(), "c": engine.candidates(),
              "t": int(time.time())}
        call.signalled = True
        if not self._send_control_to(call.peer, op, "Voice call"):
            self.ui_queue.put(("call_engine", call.id, "failed",
                               "The call could not be placed"))

    def _prepare_incoming(self, call: "Call") -> None:
        """Worker thread: the callee's side, while it rings — find the way
        to the caller now, so speech flows the moment it is answered."""
        relay, ticket = self._call_relay()
        if call.ended:
            return
        engine = self._new_engine(call, 1, relay, ticket)
        engine.set_keys(call.keys())
        engine.add_candidates(call.remote_cands)
        engine.set_send_codecs(call.their_codecs)
        if call.state == "connecting":                # answered already
            engine.start_audio()
        self._await_relay(call, engine, relay)
        if call.ended:
            return
        call.signalled = True
        self._send_control_to(call.peer, {"op": "ringing", "id": call.id,
                                          "k": call.pub,
                                          "c": engine.candidates(),
                                          "codecs": call_codecs()},
                              "Voice call")

    def _incoming_call(self, sender: str, sig: dict) -> None:
        contact = self.store.get_contact(sender) if self.store else None
        if contact is None:
            return
        age = time.time() - sig["t"] if sig.get("t") else 0
        if age > CALL_OFFER_MAX_AGE:
            self._log_call(sender, "Missed call", missed=True)
            return
        current = self.call
        if current is not None and not current.ended:
            if current.id != sig["id"]:
                self._send_call_end(sender, sig["id"], "busy")
                self._log_call(sender, "Missed call", missed=True)
            return
        if not calls_possible_here():
            self._send_call_end(sender, sig["id"], "unavailable")
            self._log_call(sender, "Missed call", missed=True)
            return
        if sig["id"] in self._declined_calls:
            return                     # declined from its notification
        call = Call(sender, outgoing=False, call_id=sig["id"],
                    tag=sig["tag"])
        call.their_key, call.remote_cands = sig["k"], sig["c"]
        call.their_codecs = sig.get("codecs") or ["ima16"]
        self.call = call
        self.show_call()
        self._start_call_clock()
        if IS_ANDROID:
            android_cancel_call_notification()     # the screen rings now
        threading.Thread(target=self._prepare_incoming, args=(call,),
                         daemon=True).start()
        if self._answer_on_ring == call.id:
            self._answer_on_ring = None
            self.answer_call()
        else:
            self._ring(True)

    def _on_call_signal(self, sender: str, sig: dict) -> None:
        if self.store is None:
            return
        op, call = sig["op"], self.call
        if op == "call":
            self._incoming_call(sender, sig)
            return
        if call is None or call.ended or call.id != sig["id"] or \
                call.peer != sender:
            return
        engine = call.engine
        if op in ("ringing", "answer") and call.outgoing and \
                call.their_key is None:
            call.their_key = sig["k"]
            if engine is not None:
                engine.set_keys(call.keys())
        if op in ("ringing", "answer") and call.outgoing and \
                engine is not None:
            call.their_codecs = sig.get("codecs") or ["ima16"]
            engine.set_send_codecs(call.their_codecs)
        if op in ("ringing", "answer", "cands") and engine is not None:
            engine.add_candidates(sig.get("c") or [])
        if op == "ringing" and call.outgoing and call.state == "calling":
            call.state = "ringing"
            self._ringback(True)
        elif op == "answer" and call.outgoing and \
                call.state in ("calling", "ringing"):
            self._ringback(False)
            call.answered_at = time.monotonic()
            # Their voice can come quicker than the message saying they
            # answered: then the call is on already.
            if engine is not None and engine.last_heard is not None:
                call.state, call.connected_at = "active", time.monotonic()
            else:
                call.state = "connecting"
            if engine is not None:
                engine.start_audio()
            self._call_audio_started()
        elif op == "end":
            self._finish_call(sig["why"], local=False)
        self._refresh_call()

    def _on_call_engine(self, call_id: str, kind: str, value) -> None:
        call = self.call
        if call is None or call.id != call_id or call.ended:
            return
        if kind == "path":
            call.path = value
        elif kind == "reflexive":
            # Our public address arrived after the first message went: send
            # it on, so the direct way can be found.
            if getattr(call, "signalled", False) and call.engine:
                op = {"op": "cands", "id": call.id,
                      "c": call.engine.candidates()}
                threading.Thread(target=self._send_control_to,
                                 args=(call.peer, op, "Voice call"),
                                 daemon=True).start()
        elif kind == "audio" and call.state == "connecting":
            call.state = "active"
            call.connected_at = time.monotonic()
        elif kind == "quiet":
            call.quiet = True
        elif kind == "heard":
            call.quiet = False
        elif kind == "bye":
            self._finish_call("hangup", local=False)
        elif kind == "lost":
            self._set_status("The call dropped", T.alert)
            self._finish_call("failed", local=True)
        elif kind in ("audio_failed", "failed"):
            self._set_status(str(value) if kind == "failed" else
                             f"The call's sound would not start ({value})",
                             T.alert)
            self._finish_call("failed", local=True)
        self._refresh_call()

    def answer_call(self) -> None:
        call = self.call
        if call is None or call.ended or call.outgoing or \
                call.state != "incoming":
            return

        def go():
            if call.ended or call.state != "incoming":
                return
            call.state = "connecting"
            call.answered_at = time.monotonic()
            self._ring(False)
            engine = call.engine
            op = {"op": "answer", "id": call.id, "k": call.pub,
                  "c": engine.candidates() if engine else [],
                  "codec": pick_send_codec(call.their_codecs),
                  "codecs": call_codecs()}
            threading.Thread(target=self._send_control_to,
                             args=(call.peer, op, "Voice call"),
                             daemon=True).start()
            if engine is not None:
                engine.start_audio()
            self._call_audio_started()
            self._refresh_call()
        self._with_microphone(go)

    def decline_call(self) -> None:
        self._finish_call("declined", local=True)

    def end_call(self) -> None:
        call = self.call
        if call is None:
            return
        if call.connected_at is not None or call.state == "connecting":
            why = "hangup"
        else:
            why = "cancelled" if call.outgoing else "declined"
        self._finish_call(why, local=True)

    def _finish_call(self, why: str, local: bool) -> None:
        call = self.call
        if call is None or call.ended:
            return
        call.ended = True
        call.summary = call_summary(call, why, local)
        self._ring(False)
        self._ringback(False)
        self._call_audio_stopped()
        self._stop_call_clock()
        engine = call.engine
        if local:
            if engine is not None:
                engine.hangup()
            self._send_call_end(call.peer, call.id, why)
        elif engine is not None:
            engine.stop()
        self._log_call(call.peer, call.summary,
                       missed=not call.outgoing and not local and
                       call.connected_at is None)
        self._refresh_call()
        Clock.schedule_once(lambda _dt: self._close_call_screen(call), 1.4)

    def _send_call_end(self, peer: str, call_id: str, why: str) -> None:
        call = self.call
        if call is not None and call.id == call_id:
            if getattr(call, "end_sent", False):
                return                 # said already, while off screen
            call.end_sent = True
        threading.Thread(target=self._send_control_to, args=(
            peer, {"op": "end", "id": call_id, "why": why}, "Voice call"),
            daemon=True).start()

    def _log_call(self, peer: str, text: str, missed: bool = False) -> None:
        """What became of a call, as a line in the chat."""
        if self.store is None:
            return
        self.store.add_event(peer, text)
        if peer == self.current_peer:
            self.refresh_chat(peer)
        self._dirty_list = True
        if missed:
            name = (self.store.get_contact(peer) or {}).get("username") or \
                short_addr(peer, 12)
            if IS_ANDROID:
                try:
                    android_notify(peer, name, "Missed call")
                except Exception:
                    log.exception("could not post a missed call")
            else:
                self._set_status(f"Missed call from {name}", COL_ACCENT)

    def toggle_call_mute(self) -> None:
        call = self.call
        if call is None or call.ended:
            return
        call.muted = not call.muted
        if call.engine is not None:
            call.engine.muted = call.muted
        self._refresh_call()

    def toggle_call_speaker(self) -> None:
        call = self.call
        if call is None or call.ended:
            return
        call.speaker = not call.speaker
        call.route = "speaker" if call.speaker else "earpiece"
        if call.engine is not None:
            call.engine.set_speaker(call.speaker)
        if IS_ANDROID:
            android_proximity(not call.speaker)
        self._refresh_call()

    @staticmethod
    def call_audio_has_speaker() -> bool:
        return IS_ANDROID

    def call_routes(self) -> list:
        call = self.call
        engine = call.engine if call is not None else None
        return engine.routes() if engine is not None else []

    def choose_call_route(self) -> None:
        """The call screen's sound button (v11): with only the phone and
        its speaker, it switches between them; with a headset connected
        too, it offers them all."""
        call = self.call
        if call is None or call.ended:
            return
        routes = self.call_routes()
        if len(routes) <= 2:
            self.toggle_call_speaker()
            return
        now = call.engine.route() if call.engine else ""
        icons = {"earpiece": "phone", "wired": "phone", "speaker": "speaker",
                 "bluetooth": "bluetooth"}
        MenuSheet([(icons.get(key, "speaker"),
                    label + ("  ✓" if key == now else ""),
                    lambda k=key: self.set_call_route(k))
                   for key, label in routes], title="Sound").open()

    def set_call_route(self, key: str) -> None:
        call = self.call
        if call is None or call.ended or call.engine is None:
            return
        call.speaker = key == "speaker"
        call.route = key
        call.engine.set_route(key)
        if IS_ANDROID:
            android_proximity(key == "earpiece")
        self._refresh_call()

    def _call_audio_started(self) -> None:
        if IS_ANDROID:
            call = self.call
            android_proximity(not (call and call.speaker))
            try:
                android_call_service(True)
                self._call_service_on = True
            except Exception:
                log.exception("could not start the call service")

    def _call_audio_stopped(self) -> None:
        if IS_ANDROID:
            android_proximity(False)
            if self._call_service_on:
                self._call_service_on = False
                try:
                    android_call_service(False)
                except Exception:
                    log.exception("could not stop the call service")

    # ---- the call's screen ---------------------------------------------------------
    def show_call(self) -> None:
        call = self.call
        if call is None:
            return
        android_show_over_lock(True)
        if self._call_pill is not None:
            self._call_pill.remove()
            self._call_pill = None
        if self._call_overlay is None or self._call_overlay.call is not call:
            self._call_overlay = CallOverlay(self, call)
        if self._call_overlay.parent is None:
            self._call_overlay.open()
        self._call_overlay.refresh()

    def hide_call(self) -> None:
        """Set the call screen aside (back): the call goes on, a bar at
        the top leads back to it."""
        call = self.call
        if call is None or call.ended or self._call_overlay is None:
            return
        self._call_overlay.dismiss()
        if self._call_pill is None:
            self._call_pill = CallPill(self)
            Window.add_widget(self._call_pill)
        self._refresh_call()

    def _close_call_screen(self, call: "Call") -> None:
        if self.call is call:
            self.call = None
            android_show_over_lock(False)
        if self._call_overlay is not None and self._call_overlay.call is call:
            self._call_overlay.dismiss()
            self._call_overlay = None
        if self._call_pill is not None and self.call is None:
            self._call_pill.remove()
            self._call_pill = None

    def _refresh_call(self) -> None:
        call = self.call
        if self._call_overlay is not None and \
                self._call_overlay.parent is not None:
            self._call_overlay.refresh()
        if self._call_pill is not None and call is not None:
            what = call_clock(call.duration()) if call.state == "active" \
                else {"incoming": "Incoming call", "ringing": "Ringing…",
                      "calling": "Calling…",
                      "connecting": "Connecting…"}.get(call.state, "Call")
            self._call_pill.set_text(f"{what}  ·  tap to return")

    def _start_call_clock(self) -> None:
        if self._call_clock is None:
            self._call_clock = Clock.schedule_interval(self._call_tick, 0.5)

    def _stop_call_clock(self) -> None:
        if self._call_clock is not None:
            self._call_clock.cancel()
            self._call_clock = None

    def _call_tick(self, _dt) -> None:
        call = self.call
        if call is None or call.ended:
            return
        now = time.monotonic()
        if call.state in ("calling", "ringing") and \
                now - call.created > CALL_RING_SECONDS:
            self._finish_call("timeout", local=True)
        elif call.state == "incoming" and \
                now - call.created > CALL_RING_SECONDS + 10:
            self._finish_call("timeout", local=True)
        elif call.state == "connecting" and \
                now - (call.answered_at or now) > CALL_CONNECT_SECONDS:
            self._set_status("No way through to them was found", T.alert)
            self._finish_call("failed", local=True)
        self._refresh_call()

    def _ringback(self, on: bool) -> None:
        """The caller's tone while it rings at the other end (v11)."""
        tone = getattr(self, "_ringback_tone", None)
        if not on:
            if tone is not None:
                self._ringback_tone = None
                try:
                    tone.stop()
                except Exception:
                    log.exception("the ringback would not stop")
            return
        if tone is None:
            tone = AndroidRingback() if IS_ANDROID else DesktopRingback()
            try:
                tone.start()
                self._ringback_tone = tone
            except Exception:
                log.exception("no ringback tone")

    def _ring(self, on: bool) -> None:
        if not on:
            if self._ringer is not None:
                ringer, self._ringer = self._ringer, None
                try:
                    ringer.stop()
                except Exception:
                    log.exception("the ringer would not stop")
            return
        if self._ringer is None:
            self._ringer = AndroidRinger() if IS_ANDROID else DesktopRinger()
            try:
                self._ringer.start()
            except Exception:
                log.exception("the ringer would not start")

    # ---- a call's sound over the WebSocket -----------------------------------------
    def _call_ws_send(self, tag: bytes, role: int, packet: bytes) -> bool:
        """Engine thread: one packet, through the relay's WebSocket."""
        worker = self.worker
        if worker is None or not hasattr(worker, "send_ws"):
            return False
        return bool(worker.send_ws({"type": "cmedia", "tag": tag.hex(),
                                    "role": role, "d": b64e(packet)}))

    def call_ws_packet(self, tag, data) -> None:
        """Sync thread: a packet the relay forwarded over the WebSocket."""
        call = self.call
        if call is None or call.engine is None or tag != call.tag or \
                not isinstance(data, str) or len(data) > 2 * CALL_MAX_PACKET:
            return
        try:
            call.engine.ws_packet(b64d(data))
        except ValueError:
            pass

    def _check_pending_offer(self) -> None:
        """A call that rang while the app was closed: the background
        service kept its offer. Still fresh, it rings here now."""
        if self.store is None or not self.keys.has_identity:
            return
        path = DATA_DIR / f"call_offer_{self.keys.address}.json"
        try:
            pending = json.loads(path.read_text("utf-8"))
            path.unlink()
        except (OSError, ValueError):
            return
        sig = sanitize_call_signal("call", (pending or {}).get("sig") or {})
        sender = (pending or {}).get("from")
        if sig is not None and isinstance(sender, str):
            self._on_call_signal(sender, sig)

    # =========================================================================
    #  UI-queue pump (the only place workers reach the UI)
    # =========================================================================
    def _drain_ui_queue(self, _dt) -> None:
        """Drain worker events and repaint AT MOST ONCE per tick.

        Previously each event triggered its own full chat + list repaint, so
        a burst of N messages (a reconnect flushing a backlog, say) did N
        repaints. Now the whole burst is collapsed into a single pass.
        """
        try:
            while True:
                event = self.ui_queue.get_nowait()
                kind = event[0]
                if kind == "status":
                    self._set_status(event[1], event[2])
                elif kind == "needs_registration":
                    self._handle_needs_registration(event[1])
                elif kind == "message_stored":
                    peer = event[1]
                    if peer == self.current_peer and self.store is not None:
                        if self._auto_read(peer) and self.foreground and \
                                self.manager.current == "conversation":
                            self.mark_peer_read(peer, refresh=False)
                        self._dirty_chat = True
                    self._dirty_list = True
                elif kind == "expired":
                    # Disappearing messages went: so does what the shade
                    # still said of them.
                    if IS_ANDROID:
                        android_clear_notification(event[1])
                elif kind == "held_released" and self.store is not None:
                    peer, count = event[1], event[2]
                    if peer:
                        name = (self.store.get_contact(peer) or {}).get(
                            "username") or short_addr(peer, 10)
                        self._set_status(
                            f"{count} message{'s' if count != 1 else ''} "
                            f"from {name} arrived", COL_OK)
                    self._dirty_list = True
                elif kind == "media_pending" and self.store is not None:
                    row = self.store.message_by_cid(event[1], event[2], "in")
                    if row is not None and downloads_by_itself(self.store,
                                                               row):
                        self.fetch_media(row["id"])
                elif kind == "resend_request" and self.store is not None:
                    self._on_resend_request(*event[1:4])
                elif kind == "reaction":
                    if event[1] == self.current_peer:
                        self.conversation_screen.note_reaction(*event[2:5])
                elif kind == "group_publish" and self.store is not None:
                    threading.Thread(target=self._announce_group,
                                     args=(event[1],), daemon=True).start()
                elif kind == "picture":
                    self._on_picture(event[1], event[2])
                elif kind == "picture_wanted" and self.store is not None:
                    threading.Thread(target=self.ask_for_picture,
                                     args=event[1:4], daemon=True).start()
                elif kind == "picture_request" and self.store is not None:
                    threading.Thread(target=self.answer_picture_request,
                                     args=event[1:3], daemon=True).start()
                elif kind == "call_signal":
                    self._on_call_signal(event[1], event[2])
                elif kind == "call_engine":
                    self._on_call_engine(*event[1:4])
        except queue.Empty:
            pass
        if self._dirty_chat:
            self._dirty_chat = False
            self.refresh_chat(self.current_peer)
        if self._dirty_list:
            self._dirty_list = False
            self.refresh_sidebar()

    # =========================================================================
    #  Notifications
    # =========================================================================
    @staticmethod
    def _window_focused() -> bool:
        return bool(getattr(Window, "focus", True))

    def notify_incoming(self, peer: str, body: str, kind: str,
                        author: Optional[str] = None) -> None:
        """A new message (sync thread, v11): notify — unless that very chat
        is in front of the user, or muted. Run from here rather than the
        screen's queue, a paused app notifies too: Android stops a paused
        app's screen, not its sync thread. On a computer, the system's own
        notification while the window is elsewhere; a line in the app
        while it is in front."""
        if self.store is None:
            return
        looking = self.foreground and peer == self.current_peer and \
            self.manager.current == "conversation"
        if looking and (IS_MOBILE or self._window_focused()):
            return
        name, preview, muted = notification_text(self.store, peer, body,
                                                 kind, author)
        if muted:
            return
        if IS_ANDROID:
            android_message_notification(self, peer, name, preview[:160])
        elif not self._window_focused():
            if desktop_notifications_enabled():
                desktop_notify(name, preview)
            desktop_flash_window()
        else:
            self.ui_queue.put(("status", f"New message from {name}",
                               COL_ACCENT))

    def call_signal_arrived(self, sender: str, sig: dict) -> None:
        """A call's message (sync thread, v11). On screen, or with a call
        on, it goes to the call screen. Away from the screen with no call,
        it is handled as the background service would — the offer kept and
        rung through a notification — because a paused app's screen would
        not see it until someone came back to it."""
        call = self.call
        in_call = call is not None and not call.ended
        if self.foreground or in_call:
            if in_call and not self.foreground and sig["op"] == "end" and \
                    call.id == sig["id"] and call.peer == sender:
                self._halt_call_quietly(call)
            self.ui_queue.put(("call_signal", sender, sig))
            return
        _service_call_signal(self, sender, sig)

    # ---- v11: a call while the app is off screen -------------------------------
    @staticmethod
    def _call_overdue(call: "Call") -> Optional[str]:
        """Why a call should end now ('timeout', 'failed'), or None — the
        same limits _call_tick applies on screen."""
        now = time.monotonic()
        if call.state in ("calling", "ringing") and \
                now - call.created > CALL_RING_SECONDS:
            return "timeout"
        if call.state == "incoming" and \
                now - call.created > CALL_RING_SECONDS + 10:
            return "timeout"
        if call.state == "connecting" and \
                now - (call.answered_at or now) > CALL_CONNECT_SECONDS:
            return "failed"
        return None

    def _halt_call_quietly(self, call: "Call",
                           why: Optional[str] = None) -> None:
        """Off screen, a call that has ended (or, `why`, run out of time)
        stops its sound, its ringing and its 'Call in progress' service at
        once; its screen and its line in the chat follow when the app is
        back. Safe from any thread: no widget is touched."""
        engine = call.engine
        if engine is not None:
            try:
                engine.hangup() if why else engine.stop()
            except Exception:
                log.exception("could not stop a call's sound")
        if why and not getattr(call, "end_sent", False):
            call.end_sent = True
            threading.Thread(target=self._send_control_to, args=(
                call.peer, {"op": "end", "id": call.id, "why": why},
                "Voice call"), daemon=True).start()
        ringer, self._ringer = self._ringer, None
        tone = getattr(self, "_ringback_tone", None)
        self._ringback_tone = None
        for part in (ringer, tone):
            if part is not None:
                try:
                    part.stop()
                except Exception:
                    log.exception("the ringing would not stop")
        try:
            (DATA_DIR / ".call_active").unlink()     # ends the call service
        except OSError:
            pass
        if IS_ANDROID:
            android_cancel_call_notification()

    def _start_call_watchdog(self) -> None:
        """While the app is away with a call on, the call's time limits are
        kept by a thread: the screen's clock does not run then."""
        if self._watchdog is not None and self._watchdog.is_alive():
            return

        def watch():
            while not self.foreground:
                call = self.call
                if call is None or call.ended:
                    return
                why = self._call_overdue(call)
                if why:
                    self._halt_call_quietly(call, why)
                    return
                time.sleep(1.0)
        self._watchdog = threading.Thread(target=watch, daemon=True,
                                          name="fext-call-watch")
        self._watchdog.start()

    def _call_from_notification(self, action: str, call_id: str) -> None:
        """A call's notification was tapped: 'answer' (or 'show') it."""
        if not _CALL_ID_RE.match(call_id or ""):
            return
        if action == "answer":
            self._answer_on_ring = call_id
        call = self.call
        if call is not None and call.id == call_id and not call.ended:
            self.show_call()
            if action == "answer" and call.state == "incoming":
                self._answer_on_ring = None
                self.answer_call()
            return
        self._check_pending_offer()

    def _sync_background_service(self) -> None:
        """Run the background service if the user wants delivery while the
        app is closed (default), stop it if not. Started from here — the
        foreground — because Android 12+ refuses to start one otherwise."""
        if not IS_ANDROID:
            return
        try:
            android_service(background_delivery_enabled())
        except Exception:
            log.exception("could not start/stop the background service")

    def _ask_notification_permission(self) -> None:
        """Android 13+ needs explicit permission before any notification
        shows; earlier versions grant it at install."""
        if IS_ANDROID:
            try:
                if android_sdk() >= 33 and not android_has_permission(
                        "android.permission.POST_NOTIFICATIONS"):
                    android_request_permissions(
                        ["android.permission.POST_NOTIFICATIONS"])
            except Exception:
                log.exception("notification permission request failed")

    def _bind_notification_taps(self) -> None:
        if not IS_ANDROID:
            return
        try:
            from android import activity
            activity.bind(on_new_intent=self._on_new_intent)
        except Exception:
            log.exception("could not listen for notification taps")

    def _on_new_intent(self, intent) -> None:
        try:
            peer = intent.getStringExtra("fext_peer")
            action = intent.getStringExtra("fext_call_action")
            call_id = intent.getStringExtra("fext_call")
        except Exception:
            peer = action = call_id = None
        if action and call_id:
            run_on_ui(self._call_from_notification, str(action), str(call_id))
        elif peer:
            run_on_ui(self._open_from_notification, str(peer))

    def _open_from_notification(self, peer: str) -> None:
        if self._known_conversation(peer):
            self.open_conversation(peer)

    def _launch_peer(self) -> Optional[str]:
        """The chat a notification tap asked for when it COLD-started us."""
        if not IS_ANDROID:
            return None
        try:
            autoclass, _ = _jni()
            intent = autoclass("org.kivy.android.PythonActivity"
                               ).mActivity.getIntent()
            peer = intent.getStringExtra("fext_peer") if intent else None
            return str(peer) if peer else None
        except Exception:
            return None

    def _launch_call_action(self) -> tuple:
        """(action, call id) a call's notification COLD-started us with."""
        if not IS_ANDROID:
            return None, None
        try:
            autoclass, _ = _jni()
            intent = autoclass("org.kivy.android.PythonActivity"
                               ).mActivity.getIntent()
            if intent is None:
                return None, None
            return (intent.getStringExtra("fext_call_action"),
                    intent.getStringExtra("fext_call"))
        except Exception:
            return None, None

    def _handle_needs_registration(self, message: str) -> None:
        """The relay does not recognise this identity — offer to register.

        Reached when the relay's database has been reset, or when this key
        was never registered here. The keypair is intact, so recovery is
        just picking a name again; only the local claim of having a name is
        dropped.
        """
        if self._register_modal is not None:
            return                       # already asking
        if self.worker is not None:
            self.worker.stop_event.set()
            self.worker = None
        self.keys.clear_username()
        self.chats_screen.refresh_header()
        self._set_status("This relay doesn't recognise your identity — "
                         "pick a username to reconnect", COL_TICK_GOLD)
        reason = ("The relay no longer has a record of this identity "
                  "(its database may have been reset). Your keys are "
                  "safe — choose a name to register again.")
        self._register_modal = RegisterModal(self, reason=reason)
        self._register_modal.bind(
            on_dismiss=lambda *_a: setattr(self, "_register_modal", None))
        self._register_modal.open()

    def retry_now(self) -> None:
        """User-initiated reconnect: re-probe the transport AND skip whatever
        backoff is pending. Re-probing matters because the most common cause
        of a stuck connection is a stale transport choice — the relay gained
        or lost TLS since the choice was cached."""
        ENDPOINT.invalidate()
        self._probe_transport()
        if self.worker is not None and self.worker.is_alive():
            self.worker.nudge()
            self._set_status("Reconnecting…", COL_TEXT_DIM)
        elif self.keys.has_identity and self.keys.username:
            self._start_worker()

    def on_start(self) -> None:
        if platform.system() == "Windows" and DESKTOP_ICO.is_file():
            Clock.schedule_once(
                lambda _dt: windows_window_icons(str(DESKTOP_ICO)), 0)

    def on_pause(self) -> bool:
        self.foreground = False          # background: back off politely
        self.conversation_screen.keep_draft()
        if self.call is not None and not self.call.ended:
            self._start_call_watchdog()
        return True

    def on_resume(self) -> None:
        """Returning to the app must feel instant, not 'wait out the timer'.

        Android suspends sockets in the background, so the worker is very
        often sitting in a long backoff at the moment the user looks at the
        screen again. Nudging here is what turns a 30-second blank stare
        into an immediate reconnect.
        """
        self.foreground = True
        if self.worker is not None and self.worker.is_alive():
            self.worker.nudge()
        elif self.keys.has_identity and self.keys.username:
            self._start_worker()
        # Messages that arrived while we were in the background were left
        # unread on purpose (nobody was looking); now somebody is.
        peer = self.current_peer
        if peer and self.store is not None and \
                self.manager.current == "conversation":
            if IS_ANDROID:
                android_clear_notification(peer)
            if self._auto_read(peer):
                self.mark_peer_read(peer)
        # The background service may have been sent pictures meanwhile, or
        # a call that is still ringing.
        if self.store is not None:
            self._load_pictures()
            self._check_pending_offer()
        android_style_system_bars()
        self._watch_system_theme(0)

    def _set_status(self, text: str, color: Optional[str] = None) -> None:
        color = retint(color) if color else T.text_3
        self._pending_status = (text, color)
        self.chats_screen.set_status(text, color)

    # =========================================================================
    #  Dialog launchers
    # =========================================================================
    def open_add_contact(self) -> None:
        if self.store is not None and self.keys.username:
            AddContactModal(self).open()
        else:
            self._set_status("Register this identity first", COL_TICK_GOLD)

    def open_contact_settings(self) -> None:
        if self.current_peer is not None:
            ChatHistorySheet(self, self.current_peer).open()

    def open_chat_info(self) -> None:
        peer = self.current_peer
        if peer is None or self.store is None:
            return
        if self.conversation_kind(peer) == "group":
            self.group_info_screen.show(gid_of(peer))
            self._navigate("group_info", "left")
        else:
            self.chat_info_screen.show(peer)
            self._navigate("info", "left")

    def close_chat_info(self) -> None:
        self._navigate("conversation", "right")
        self.refresh_chat(self.current_peer)

    def open_search(self) -> None:
        if self.manager.current != "chats":
            self.go_back_to_chats()
        self.chats_screen.enter_search()

    # ---- the menu and the pages it opens ---------------------------------------
    def open_drawer(self) -> None:
        # Made for the theme it opens in: a theme change rebuilds it.
        if self.drawer is None or self.drawer.theme != T.name:
            self.drawer = NavDrawer(self)
        self.drawer.open()

    def close_drawer(self) -> bool:
        """Close the menu if it is open; True if it was."""
        if self.drawer is not None and self.drawer.is_open:
            self.drawer.close()
            return True
        return False

    def open_profile(self) -> None:
        if not self.keys.has_identity:
            return
        self._profile_from = self.manager.current
        self.profile_screen.show()
        self._navigate("profile", "left")

    def close_profile(self) -> None:
        back = getattr(self, "_profile_from", "chats")
        if back not in self.manager.screen_names or back == "profile":
            back = "chats"
        if back == "settings":
            self.settings_screen.show()
        self._navigate(back, "right")
        if back == "chats":
            self.chats_screen.refresh_header()

    # ---- pictures ------------------------------------------------------------------
    def picture_menu(self, gid: Optional[str] = None) -> None:
        """See, choose, take or remove a picture: this identity's own, or
        (as its admin) a group's."""
        peer = group_peer(gid) if gid else self.keys.address
        has = bool(PICTURES.path(peer))
        items = []
        if has:
            items.append(("image", "See the photo",
                          lambda: self.view_picture(peer)))
        items.append(("image", "Choose a photo",
                      lambda: self._pick_picture(gid)))
        items.append(("camera", "Take a photo",
                      lambda: self._shoot_picture(gid)))
        if has:
            items.append(("delete", "Remove the photo",
                          lambda: self.set_picture(None, gid), True))
        MenuSheet(items, title="Group photo" if gid else
                  "Profile photo").open()

    def view_picture(self, peer: str) -> bool:
        path = PICTURES.path(peer)
        if path:
            ImageViewer(path, nocache=True).open()
            return True
        return False

    def _pick_picture(self, gid: Optional[str]) -> None:
        if IS_ANDROID:
            try:
                android_pick_image(
                    lambda path: self._frame_picture(path, gid, True))
            except Exception:
                log.exception("photo picker failed")
                self._set_status("Couldn't open the photo picker", T.alert)
        else:
            ImageChooserModal(
                lambda path: self._frame_picture(path, gid, False),
                title="Group photo" if gid else "Profile photo").open()

    def _shoot_picture(self, gid: Optional[str]) -> None:
        if IS_ANDROID:
            try:
                android_take_photo(
                    lambda path: self._frame_picture(path, gid, True))
            except Exception:
                log.exception("camera failed")
                self._set_status("Couldn't open the camera", T.alert)
        else:
            open_desktop_camera(
                lambda path: self._frame_picture(path, gid, True),
                on_choose=lambda: self._pick_picture(gid))

    def _frame_picture(self, path: str, gid: Optional[str],
                       temporary: bool) -> None:
        try:
            PictureCropSheet(path, lambda data: self.set_picture(data, gid),
                             title="Group photo" if gid else "Profile photo",
                             temporary=temporary).open()
        except Exception:
            log.exception("could not open a photo to frame")
            if temporary:
                discard_media_file(path)
            self._set_status("That photo could not be opened", T.alert)

    def set_picture(self, data: Optional[bytes],
                    gid: Optional[str] = None) -> bool:
        """Make `data` (a JPEG from picture_jpeg; None removes it) the
        picture of this identity — or of group `gid`, when we are its
        admin — and send it to everyone concerned."""
        if self.store is None or not self.keys.has_identity:
            return False
        if gid is not None:
            group = self.store.group(gid)
            if group is None or group["admin"] != self.keys.address or \
                    group["state"] != "active":
                self._set_status("Only the group's admin can change its "
                                 "photo", T.accent)
                return False
            peer = group_peer(gid)
            target = peer_picture_path(self.keys.address, peer)
        else:
            peer = self.keys.address
            target = own_picture_path(peer)
        path = None
        if data:
            if not write_picture(target, data):
                self._set_status("The photo could not be saved", T.alert)
                return False
            path = str(target)
        else:
            discard_picture_file(target)
        self.store.set_picture(
            peer, next_picture_version(self.store.picture_version(peer)),
            path)
        self._on_picture(peer, path)
        threading.Thread(target=self.broadcast_picture, args=(gid,),
                         daemon=True).start()
        if self.manager.current == "profile" and gid is None:
            self.profile_screen.show()
        elif self.manager.current == "group_info" and \
                self.group_info_screen.gid == gid:
            self.group_info_screen.show(gid)
        what = "Group photo" if gid else "Profile photo"
        self._set_status(f"{what} {'updated' if path else 'removed'}",
                         COL_TEXT_DIM)
        return True

    def open_settings(self) -> None:
        self._settings_from = self.manager.current
        self.settings_screen.show()
        self._navigate("settings", "left")

    def close_settings(self) -> None:
        back = getattr(self, "_settings_from", "chats")
        if back not in self.manager.screen_names or back == "settings":
            back = "chats"
        self._navigate(back, "right")
        if back == "chats":
            self.refresh_sidebar()
            self.chats_screen.refresh_header()

    def open_compose(self) -> None:
        if self.store is not None and self.keys.username:
            ComposeSheet(self).open()
        else:
            self._set_status("Register this identity first", T.accent)

    def open_new_group(self) -> None:
        if self.store is None or not self.keys.username:
            self._set_status("Register this identity first", T.accent)
            return
        self.new_group_screen.show()
        self._navigate("new_group", "left")

    def confirm_leave_group(self, gid: str) -> None:
        group = self.store.group(gid) if self.store else None
        if not group:
            return
        sheet = Sheet(f"Leave “{group['name']}”?")
        sheet.add(hint("The others are told you left. Your copy of the "
                       "history stays on this device, read-only; only the "
                       "admin can add you back."))

        def leave(_w):
            sheet.dismiss()
            self.leave_group(gid)
            if self.manager.current == "group_info":
                self.group_info_screen.show(gid)
        sheet.add(button_row(Btn("Stay", kind="quiet",
                                 on_release=lambda _w: sheet.dismiss()),
                             Btn("Leave", kind="solid_danger",
                                 on_release=leave)))
        sheet.open()

    def list_contact(self, address: str) -> None:
        """Put someone known only from a group into the chat list."""
        if self.store is None:
            return
        contact = self.store.get_contact(address)
        if contact is None:
            peer = self.current_peer or ""
            group = self.store.group(gid_of(peer)) if gid_of(peer) else None
            member = next((m for m in (group or {}).get("members", [])
                           if m["a"] == address), None)
            if member is None:
                return
            self.store.upsert_contact(address, member.get("u"), member["k"])
        else:
            self.store.upsert_contact(address, contact.get("username"),
                                      contact["public_key"], listed=True)
        self.refresh_sidebar()
        self.open_conversation(address)

    # ---- per-chat switches (chat info and the ⋮ menu) ------------------------
    def set_notify(self, peer: str, on: bool) -> None:
        """On: unmute. Off: muted until turned back on."""
        self.set_mute([peer], None if on else LocalStore.MUTE_FOREVER)

    def set_mute(self, peers: list, until: Optional[float]) -> None:
        """v11: mute chats until `until` (epoch seconds), until turned back
        on (LocalStore.MUTE_FOREVER), or — None — unmute them. Muted chats
        still receive and show every message; they only stop notifying."""
        for peer in peers:
            self.store.set_mute(peer, until)
            if until is not None and IS_ANDROID:
                android_clear_notification(peer)
        if until is None:
            verb = "Notifications on" if len(peers) == 1 else "Unmuted"
        else:
            verb = mute_label(until, short=True)
        self._after_list_change(peers, verb)
        current = self.manager.current
        if current == "info" and self.chat_info_screen.peer in peers:
            self.chat_info_screen.show(self.chat_info_screen.peer)
        elif current == "group_info" and self.current_peer in peers and \
                gid_of(self.current_peer):
            self.group_info_screen.show(gid_of(self.current_peer))

    def choose_mute(self, peers: list) -> None:
        """The mute choices for chats (unmuting them if all are muted)."""
        MuteSheet(self, peers).open()

    # ---- v11: disappearing messages ---------------------------------------------
    def choose_timer(self, peer: str) -> None:
        gid = gid_of(peer)
        if gid and (self.store.group(gid) or {}).get("admin") != \
                self.keys.address:
            self._set_status("Only the group's admin sets this", T.accent)
            return
        TimerSheet(self, peer).open()

    def timer_laggards(self, peer: str) -> str:
        """Who in a chat runs an app that keeps disappearing messages."""
        if self.conversation_kind(peer) == "dm":
            contact = self.store.get_contact(peer) or {}
            if contact.get("caps", 0) & LocalStore.CAP_TIMER:
                return ""
            return contact.get("username") or short_addr(peer, 10)
        names = []
        for address, _key in self.group_recipients(gid_of(peer) or ""):
            contact = self.store.get_contact(address) or {}
            if not contact.get("caps", 0) & LocalStore.CAP_TIMER:
                names.append(contact.get("username") or short_addr(address, 8))
        return ", ".join(names[:3]) + (" and others" if len(names) > 3
                                       else "")

    def set_chat_timer(self, peer: str, seconds: int) -> None:
        """Set a chat's timer here and tell the other side (in a group,
        every member): new messages carry it from now on."""
        at = time.time()
        if not self.store.set_chat_timer(peer, seconds, at):
            return
        self.store.add_event(peer, timer_event("You", seconds))
        fallback = ("Turned on disappearing messages: " +
                    timer_label(seconds).lower()) if seconds else \
            "Turned off disappearing messages"
        if self.conversation_kind(peer) in ("dm", "group"):
            threading.Thread(target=self._send_control, args=(
                peer, {"op": "timer", "s": seconds, "at": at}, fallback),
                daemon=True).start()
        self._after_list_change([peer], "Disappearing messages " + (
            timer_label(seconds).lower() if seconds else "off"))
        if self.manager.current == "info":
            self.chat_info_screen.show(peer)
        elif self.manager.current == "group_info" and gid_of(peer):
            self.group_info_screen.show(gid_of(peer))

    # ---- v11: verifying a contact -------------------------------------------------
    def open_verify(self, peer: str) -> None:
        if self.store is None or self.store.get_contact(peer) is None:
            return
        VerifySheet(self, peer).open()

    def set_verified(self, peer: str, verified: bool) -> None:
        self.store.set_verified(peer, verified)
        name = (self.store.get_contact(peer) or {}).get("username") or \
            short_addr(peer, 10)
        self.store.add_event(peer, f"You verified {name}" if verified else
                             f"You cleared {name}'s verification")
        self._after_list_change([peer], "Verified" if verified
                                else "Verification cleared")
        if self.manager.current == "info":
            self.chat_info_screen.show(peer)

    # ---- v9.1.2: what a held chat can have done to it -------------------------
    def set_chats_muted(self, peers: list, muted: bool) -> None:
        if muted:
            self.choose_mute(peers)
        else:
            self.set_mute(peers, None)

    def set_chats_archived(self, peers: list, archived: bool) -> None:
        self.store.set_chat_flag(peers, "archived", 1 if archived else 0)
        self._after_list_change(peers, "Archived" if archived
                                else "Back in your chats")

    def set_chats_pinned(self, peers: list, pinned: bool) -> None:
        now = time.time()
        # the first picked ends up on top, as it was pinned last
        for i, peer in enumerate(reversed(peers)):
            self.store.set_chat_flag([peer], "pinned",
                                     now + i / 1000 if pinned else None)
        self._after_list_change(peers, "Pinned" if pinned else "Unpinned")

    def mark_chats_unread(self, peers: list) -> None:
        self.store.set_chat_flag(peers, "marked_unread", 1)
        self._after_list_change(peers, "Marked as unread")

    def mark_chats_read(self, peers: list) -> None:
        for peer in peers:
            self.mark_peer_read(peer, refresh=False)
        self.store.set_chat_flag(peers, "marked_unread", 0)
        self._after_list_change(peers, "Marked as read")

    def set_blocked(self, peers: list, blocked: bool) -> None:
        """Block: what they send is held, sealed, unseen and unannounced;
        their calls are refused. Unblock: what was held arrives, in order
        (v11; it used to be thrown away)."""
        peers = [p for p in peers if self.conversation_kind(p) == "dm"]
        self.store.set_chat_flag(peers, "blocked", 1 if blocked else 0)
        if blocked and IS_ANDROID:
            for peer in peers:
                android_clear_notification(peer)
        self._after_list_change(peers, "Blocked" if blocked else "Unblocked")
        if self.current_peer in peers:
            self.refresh_chat(self.current_peer)
        worker = self.worker
        if not blocked and worker is not None:
            for peer in peers:
                if self.store.held_count(peer):
                    threading.Thread(target=worker.release_held, args=(peer,),
                                     daemon=True).start()

    # ---- v14: message requests (B16) ---------------------------------------------
    def accept_request(self, peer: str) -> None:
        """Their chat joins the list, and from now on ticks and read
        receipts go both ways (the relay is told, as for the ticks switch).
        What they sent so far is marked read."""
        self.store.set_accepted(peer)
        self.set_ticks(peer, True)
        self.mark_peer_read(peer)
        self._after_list_change([peer], "Accepted")

    def decline_request(self, peer: str) -> None:
        """No: their messages go and the request leaves the list. They are
        not blocked: if they write again, it is a request again."""
        self.delete_chats([peer], "Declined")

    def report_contact(self, peer: str, reason: str, note: str,
                       block: bool) -> None:
        """Report `peer` to the relay's operator (if the relay takes
        reports), and block them if asked."""
        if block:
            self.set_blocked([peer], True)
        if not (self.api and self.api.features().get("reports")):
            return

        def work():
            try:
                self.api.report(peer, reason, note)
            except (requests.RequestException, ApiClient.ApiError) as exc:
                self.ui_queue.put(("status", f"The report did not go: {exc}",
                                   COL_DANGER))
                return
            self.ui_queue.put(("status", "Reported" + (" and blocked"
                                                       if block else ""),
                               COL_OK))
        threading.Thread(target=work, daemon=True).start()

    def delete_chats(self, peers: list, verb: str = "Deleted") -> None:
        """Remove chats from this device (a group is left first) and from
        the list, until something new arrives in them."""
        for peer in peers:
            if peer.startswith(GROUP_PREFIX):
                group = self.store.group(gid_of(peer))
                if group and group.get("state") == "active":
                    self.leave_group(gid_of(peer))
            self.store.clear_conversation(peer)
            self.store.set_chat_flag([peer], "hidden", 1)
            self.store.set_chat_flag([peer], "pinned", None)
            self.store.set_chat_flag([peer], "archived", 0)
            if IS_ANDROID:
                android_clear_notification(peer)
        if self.current_peer in peers:
            self.go_back_to_chats()
        self._after_list_change(peers, verb)

    def _after_list_change(self, peers: list, verb: str) -> None:
        n = len(peers)
        if n:
            self._set_status(f"{verb}" + (f" · {n} chats" if n > 1 else ""),
                             COL_OK)
        self.refresh_sidebar()
        if self.current_peer in peers and self.manager.current != "chats":
            self.refresh_chat(self.current_peer)

    def toggle_notify(self, peer: str) -> None:
        if self.store.mute_state(peer)[0]:
            self.set_mute([peer], None)
        else:
            self.choose_mute([peer])

    def set_ticks(self, peer: str, enabled: bool) -> None:
        """Both ends must agree for 2nd/3rd ticks; the relay enforces it, so
        the preference is synced there (and retried by being re-set)."""
        self.store.set_contact_setting(peer, "ticks_enabled", int(enabled))
        self.refresh_chat(peer)

        def work():
            try:
                self.api.set_ticks(peer, enabled)
            except (requests.RequestException, ApiClient.ApiError):
                self.ui_queue.put(("status", "Ticks preference saved here; "
                                   "the relay hears about it once you're "
                                   "online", COL_TICK_GOLD))
        threading.Thread(target=work, daemon=True).start()

    def set_auto_read(self, peer: str, auto: bool) -> None:
        self.store.set_contact_setting(peer, "auto_read", int(auto))
        if auto:
            self.mark_peer_read(peer)
        self.refresh_chat(peer)


# =============================================================================
#  Background sync service (Android) — runs in its own process
# =============================================================================
class HeadlessApp(MessagingMixin):
    """Everything SyncWorker and the media/send helpers need from an app,
    with no UI: the background service's stand-in for FextApp. Its send
    paths are MessagingMixin's — the very same code the app runs."""

    foreground = False
    current_peer = None

    def __init__(self, keys: "IdentityManager") -> None:
        self.keys = keys
        self.crypto = CryptoEngine(keys)
        self.api = ApiClient(keys)
        self.store = LocalStore(keys.store_path())
        self.ui_queue: "queue.Queue" = queue.Queue()
        self._declined_calls: set = set()

    def _set_status(self, text: str, color: Optional[str] = None) -> None:
        log.info("service: %s", text)

    def close(self) -> None:
        self.store.close()


def notification_text(store: "LocalStore", peer: str, body: str, kind: str,
                      author: Optional[str] = None) -> tuple:
    """(title, text, muted) for a new message. A group's notification is
    titled with the group and names who wrote."""
    preview = "Photo" if kind == "image" else body
    muted = store.mute_state(peer)[0] or store.is_blocked(peer)
    gid = gid_of(peer)
    if gid:
        group = store.group(gid) or {}
        who = (store.get_contact(author or "") or {}).get("username") or \
            short_addr(author or "", 10)
        return (group.get("name") or "Group", f"{who}: {preview}", muted)
    contact = store.get_contact(peer) or {}
    if not contact.get("accepted", 1):
        preview = "Message request"     # v14: what they wrote waits unseen
    return (contact.get("username") or short_addr(peer, 12), preview, muted)


def _service_call_signal(app: HeadlessApp, sender: str, sig: dict) -> None:
    """A call while the app is closed. The service cannot take it — only
    the app has a screen and the sound — so it keeps the offer for the app
    and says so; if the caller gives up first, it is a missed call."""
    path = DATA_DIR / f"call_offer_{app.keys.address}.json"
    name = (app.store.get_contact(sender) or {}).get("username") or \
        short_addr(sender, 12)
    if sig["op"] == "call":
        if sig["id"] in app._declined_calls:
            return
        if sig.get("t") and time.time() - sig["t"] > CALL_OFFER_MAX_AGE:
            app.store.add_event(sender, "Missed call")
            app.ui_queue.put(("message_stored", sender))
            return
        if app.store.get_contact(sender) is None:
            return
        try:
            path.write_text(json.dumps({"from": sender, "sig": sig,
                                        "at": time.time()}), "utf-8")
        except OSError:
            log.exception("could not keep a call's offer")
            return
        # v11: it rings — over the lock screen, with Answer and Decline —
        # rather than waiting for someone to open the app.
        rang = False
        if IS_ANDROID:
            try:
                rang = android_call_notification(app, sender, sig["id"], name)
            except Exception:
                log.exception("could not ring for a call")
            if not rang:
                try:
                    android_notify(sender, name, "Incoming voice call")
                except Exception:
                    log.exception("could not post a call's notification")
        else:
            desktop_notify(name, "Incoming voice call")
    elif sig["op"] == "end":
        try:
            pending = json.loads(path.read_text("utf-8"))
        except (OSError, ValueError):
            return
        if (pending.get("sig") or {}).get("id") == sig["id"]:
            try:
                path.unlink()
            except OSError:
                pass
            app.store.add_event(sender, "Missed call")
            app.ui_queue.put(("message_stored", sender))
            if IS_ANDROID:
                android_cancel_call_notification()
                try:
                    android_notify(sender, name, "Missed call")
                except Exception:
                    log.exception("could not post a missed call")
            else:
                desktop_notify(name, "Missed call")


def _service_handle(app: HeadlessApp, event: tuple) -> None:
    # New messages and calls are announced from the sync thread itself
    # (MessagingMixin.notify_incoming, call_signal_arrived).
    kind = event[0]
    if kind == "expired" and IS_ANDROID:
        android_clear_notification(event[1])
    elif kind == "resend_request":
        app._on_resend_request(*event[1:4])
    elif kind == "group_publish":
        threading.Thread(target=app._publish_group_state, args=(event[1],),
                         daemon=True).start()
    elif kind == "picture_wanted":
        threading.Thread(target=app.ask_for_picture, args=event[1:4],
                         daemon=True).start()
    elif kind == "picture_request":
        threading.Thread(target=app.answer_picture_request, args=event[1:3],
                         daemon=True).start()
    # Everything else (status lines, repaint hints, media downloads) is for
    # a screen; the app catches up from the database when it next opens.


def run_background_service(max_cycles: Optional[int] = None,
                           tick: float = 2.0) -> None:
    """The service's main loop.

    Idles while the app's own worker is alive (its heartbeat is fresh), and
    syncs + notifies when it is not. Re-reads the identity file every cycle,
    so switching identity in the app is picked up, and steps aside within a
    few seconds of the app reappearing.
    """
    log.info("background service: started")
    app = worker = None
    cycles = 0
    while max_cycles is None or cycles < max_cycles:
        cycles += 1
        keys = IdentityManager()
        active = keys.active if keys.has_identity else None
        wanted = (active is not None and active.get("username")
                  and background_delivery_enabled()
                  and not heartbeat_fresh("app"))
        if worker is not None and (not wanted or
                                   app.keys.address != active["address"]):
            worker.stop_event.set()
            worker.join(timeout=10)
            app.close()
            app = worker = None
            log.info("background service: standing down")
        if wanted and worker is None:
            try:
                app = HeadlessApp(keys)
                worker = SyncWorker(app)
                worker.beat_owner = "service"
                worker.start()
                log.info("background service: syncing %s", keys.address)
            except Exception:
                log.exception("background service: could not start a worker")
                app = worker = None
        if app is not None:
            try:
                while True:
                    _service_handle(app, app.ui_queue.get_nowait())
            except queue.Empty:
                pass
        time.sleep(tick)
    if worker is not None:
        worker.stop_event.set()
        app.close()


# =============================================================================
#  Entrypoint
# =============================================================================
def main() -> None:
    FextApp().run()


if __name__ == "__main__":
    if ANDROID_SERVICE == SERVICE_NAME:
        run_background_service()
    else:
        main()
